            // Traitement réel via backend API

            window.processIeFile = async function(file) {

                const uploadArea = document.getElementById('ie-upload-area');

                const loadingSpinner = document.getElementById('ie-loading-spinner');

                const resultsSection = document.getElementById('ie-results-section');



                const errBox = document.getElementById('ie-upload-error');

                const errTxt = document.getElementById('ie-upload-error-text');

                if (errBox) errBox.classList.add('hidden');

                if (errTxt) errTxt.textContent = '';



                if (uploadArea) uploadArea.classList.add('hidden');

                if (loadingSpinner) loadingSpinner.classList.remove('hidden');

                if (resultsSection) resultsSection.classList.add('hidden');



                if (typeof window.loadIePlanInViewer === 'function') {

                    try { window.loadIePlanInViewer(file); } catch(eView) { console.warn("[IE_VIEWER] Pre-load error:", eView); }

                }



                try {

                    const formData = new FormData();

                    if (file instanceof File || file instanceof Blob) {

                        formData.append('file', file);

                    }

                    if (file && file.path) {

                        formData.append('file_path', file.path);

                    }



                    const base = (typeof window.API_BASE !== 'undefined' && window.API_BASE) || (typeof API_BASE !== 'undefined' && API_BASE) || 'http://127.0.0.1:8000';

                    const resp = await fetch(`${base}/ie-mto/calculate`, {

                        method: 'POST',

                        body: formData

                    });



                    if (!resp.ok) {

                        const errText = await resp.text();

                        throw new Error(`Erreur serveur (${resp.status}): ${errText}`);

                    }



                    const data = await resp.json();

                    if (data.status === 'success') {

                        window.renderIeMtoResults(data);

                        showToast(`Plan I&E analysé avec succès (${data.items?.length || 0} articles extraits).`, "success");

                    } else {

                        throw new Error(data.detail || "Échec de l'extraction");

                    }

                } catch(err) {

                    console.error("[MTO_IE] Erreur lors de l'analyse :", err);

                    showToast(`Erreur d'analyse : ${err.message}`, "error");

                    if (errBox && errTxt) {

                        errTxt.textContent = `Erreur d'analyse : ${err.message}`;

                        errBox.classList.remove('hidden');

                    }

                    if (uploadArea) uploadArea.classList.remove('hidden');

                } finally {

                    if (loadingSpinner) loadingSpinner.classList.add('hidden');

                }

