            function updateIeKpis() {

                const items = window.currentIeMtoData || [];

                let cTot = 0, tTot = 0, wTot = 0, instCnt = 0, valCnt = 0, panCnt = 0;



                items.forEach(it => {

                    const cat = it.category || '';

                    const q = parseFloat(it.quantity) || 0;

                    const w = parseFloat(it.weight_total) || 0;

                    wTot += w;



                    if (cat === 'CABLE' || cat === 'EARTHING') cTot += q;

                    else if (cat === 'CABLE_TRAY' || cat === 'CONDUIT') tTot += q;

                    else if (['TRANSMITTER', 'INDICATOR', 'SWITCH', 'PRIMARY_ELEMENT', 'INSTRUMENT'].includes(cat)) instCnt += Math.round(q);

                    else if (['CONTROL_VALVE', 'SAFETY_VALVE'].includes(cat)) valCnt += Math.round(q);

                    else if (['PANEL', 'JUNCTION_BOX', 'PULL_BOX', 'SWITCHGEAR_FEEDER'].includes(cat)) panCnt += Math.round(q);

                });



                const elC = document.getElementById('kpi-ie-cables');

                if (elC) elC.textContent = `${cTot.toFixed(1)} m`;

                const elT = document.getElementById('kpi-ie-trays');

                if (elT) elT.textContent = `${tTot.toFixed(1)} m`;

                const elI = document.getElementById('kpi-ie-instruments');

                if (elI) elI.textContent = `${instCnt} EA`;

                const elV = document.getElementById('kpi-ie-valves');

                if (elV) elV.textContent = `${valCnt} EA`;

                const elP = document.getElementById('kpi-ie-panels');

                if (elP) elP.textContent = `${panCnt} EA`;

                const elW = document.getElementById('kpi-ie-weight');

                if (elW) elW.textContent = `${wTot.toLocaleString('fr-FR', {minimumFractionDigits:2, maximumFractionDigits:2})} kg`;



                const anoms = window.currentIeMtoAnomalies || [];

                const openCount = anoms.filter(a => a.status === 'OPEN').length;

                const elR = document.getElementById('kpi-ie-reserves');

                if (elR) elR.textContent = `${openCount} / ${anoms.length}`;



                const badge = document.getElementById('ie-plan-status-badge');

                if (badge) {

                    if (openCount === 0) {

                        badge.textContent = "100% Conforme";

                        badge.style.background = "rgba(16,185,129,0.15)";

                        badge.style.color = "#34D399";

                        badge.style.borderColor = "rgba(16,185,129,0.3)";

                    } else {

                        badge.textContent = `${openCount} Réserve(s) à lever`;

                        badge.style.background = "rgba(239,68,68,0.15)";

                        badge.style.color = "#F87171";

                        badge.style.borderColor = "rgba(239,68,68,0.3)";

                    }

                }

            }



            // Rendu des Anomalies avec les 3 Boutons Interactifs

            window.renderIeMtoAnomalies = function(anomalies) {

                const list = document.getElementById('ie-anomalies-list');

                const counter = document.getElementById('ie-reserves-counter');

                if (!list) return;



                if (!anomalies || anomalies.length === 0) {

                    list.innerHTML = `<div style="text-align:center; padding:30px 10px; color:var(--text-secondary); font-size:13px;">

                        <i class="ph ph-check-circle" style="font-size:32px; color:#10B981; margin-bottom:8px; display:inline-block;"></i>

                        <br>Aucune anomalie détectée sur ce plan. Conformité CEI / ISA parfaite !

                    </div>`;

                    if (counter) counter.textContent = "0 Réserves";

                    return;

                }



                if (counter) counter.textContent = `${anomalies.length} Réserve(s)`;



                list.innerHTML = anomalies.map((a, idx) => {

                    const isValidated = a.status === 'VALIDATED';

                    const isIgnored = a.status === 'IGNORED';

                    const sevColor = a.severity === 'CRITICAL' ? '#EF4444' : (a.severity === 'MAJOR' ? '#F59E0B' : '#3B82F6');



                    return `

                    <div style="background:rgba(255,255,255,0.02); border:1px solid ${isValidated ? 'rgba(16,185,129,0.4)' : (isIgnored ? 'rgba(156,163,175,0.2)' : 'var(--border-color)')}; border-left:4px solid ${isValidated ? '#10B981' : (isIgnored ? '#6B7280' : sevColor)}; border-radius:8px; padding:12px; display:flex; flex-direction:column; gap:8px;">

                        <div style="display:flex; justify-content:space-between; align-items:center; flex-wrap:wrap; gap:6px;">

                            <span style="font-size:10px; font-weight:800; padding:2px 6px; border-radius:4px; background:${isValidated ? 'rgba(16,185,129,0.2)' : (isIgnored ? 'rgba(156,163,175,0.2)' : `${sevColor}22`)}; color:${isValidated ? '#34D399' : (isIgnored ? '#9CA3AF' : sevColor)};">

                                ${escapeHtml(a.severity || 'MAJOR')} • ${escapeHtml(a.rule || 'RULE')}

                            </span>

                            <span style="font-size:11px; font-family:monospace; color:var(--text-secondary); font-weight:700;">${escapeHtml(a.tag || '-')}</span>

                        </div>

                        <div style="font-size:13px; font-weight:700; color:var(--text-primary);">${escapeHtml(a.title || 'Anomalie')}</div>

                        <div style="font-size:12px; color:var(--text-secondary); line-height:1.4;">${escapeHtml(a.message || '')}</div>

                        ${a.recommendation ? `<div style="font-size:12px; color:#60A5FA; display:flex; align-items:center; gap:6px;"><i class="ph ph-arrow-bend-down-right"></i> <strong>Action recommandée :</strong> ${escapeHtml(a.recommendation)}</div>` : ''}



                        <!-- Bloc statut de validation avec résumé matériel standardisé -->

                        ${isValidated ? `

                        <div style="font-size:12px; background:rgba(16,185,129,0.08); border:1px solid rgba(16,185,129,0.3); border-radius:6px; padding:8px 12px; display:flex; flex-direction:column; gap:4px;">

                            <div style="display:flex; justify-content:space-between; align-items:center;">

                                <span style="color:#34D399; font-weight:700; display:inline-flex; align-items:center; gap:6px;">

                                    <i class="ph ph-check-circle" style="font-size:16px;"></i> Réserve levée — Article I&E inséré dans la nomenclature :

                                </span>

                                <span style="font-size:10px; color:#A7F3D0; font-family:monospace;">${escapeHtml(a.validated_at || '')}</span>

                            </div>

                            ${a._inserted_ie_item ? `

                            <div style="display:flex; align-items:center; gap:8px; flex-wrap:wrap; background:rgba(0,0,0,0.25); padding:4px 8px; border-radius:4px; font-size:11px;">

                                <span style="color:#60A5FA; font-weight:700;">${escapeHtml(a._inserted_ie_item.tag)}</span>

                                <span style="color:var(--text-primary); font-weight:600;">${escapeHtml(a._inserted_ie_item.description)}</span>

                                <span style="color:#10B981; font-weight:700;">Qté : ${a._inserted_ie_item.quantity} ${a._inserted_ie_item.unit}</span>

                                <span style="color:#CBD5E1; font-family:monospace;">Poids : ${a._inserted_ie_item.weight_total} kg</span>

                            </div>` : ''}

                        </div>` : ''}



                        ${isIgnored ? `

                        <div style="font-size:11px; background:rgba(156,163,175,0.1); border:1px solid rgba(156,163,175,0.2); border-radius:6px; padding:6px 10px; color:#9CA3AF;">

                            <i class="ph ph-prohibit"></i> Réserve ignorée par l'ingénieur.

                        </div>` : ''}



                        ${a.note ? `

                        <div style="font-size:11px; background:rgba(59,130,246,0.08); border:1px solid rgba(59,130,246,0.25); border-radius:6px; padding:6px 10px; color:#93C5FD;">

                            <i class="ph ph-note"></i> <strong>Note ingénieur :</strong> ${escapeHtml(a.note)}

                        </div>` : ''}



                        <!-- LES 3 BOUTONS INTERACTIFS -->

                        <div style="display:flex; gap:8px; margin-top:4px; flex-wrap:wrap;">

                            <button onclick="validateIeAnomaly(${idx})" style="padding:6px 12px; font-size:11px; font-weight:700; border-radius:6px; border:1px solid ${isValidated ? '#10B981' : 'rgba(16,185,129,0.4)'}; background:${isValidated ? '#10B981' : 'rgba(16,185,129,0.1)'}; color:${isValidated ? '#fff' : '#34D399'}; cursor:pointer; display:inline-flex; align-items:center; gap:5px;">

                                <i class="ph ph-check"></i> ${isValidated ? 'Réserve Validée' : 'Valider / Lever'}

                            </button>

                            <button onclick="promptIeAnomalyNote(${idx})" style="padding:6px 10px; font-size:11px; font-weight:600; border-radius:6px; border:1px solid var(--border-color); background:rgba(255,255,255,0.04); color:var(--text-primary); cursor:pointer; display:inline-flex; align-items:center; gap:5px;">

                                <i class="ph ph-note-pencil"></i> Note

                            </button>

                            <button onclick="ignoreIeAnomaly(${idx})" style="padding:6px 10px; font-size:11px; font-weight:600; border-radius:6px; border:1px solid var(--border-color); background:transparent; color:var(--text-secondary); cursor:pointer; display:inline-flex; align-items:center; gap:5px;">

                                <i class="ph ph-eye-slash"></i> ${isIgnored ? 'Réouvrir' : 'Ignorer'}

                            </button>

                        </div>

                    </div>`;

                }).join('');

            };



            // Résolution d'un article standardisé I&E à partir d'une réserve

            window.resolveStandardIeItemFromAnomaly = function(a, idx, currentData) {

                const rule = a.rule || '';

                let cat = "EQUIPMENT";

                let tag = a.tag || `IE-RES-${idx+1}`;

                let desc = `ARTICLE RÉSERVE [${a.rule}]`;

                let size = "-";

                let sched = "CEI / ISA";

                let mat = "Standard";

                let qty = parseFloat(a.delta_qty) || 1.0;

                let unit = "EA";

                let unitW = 5.0;



                if (rule === 'MISSING_CABLE_TRAY') {

                    cat = "CABLE_TRAY";

                    tag = "CDC-300x60 [RÉSERVE LEVÉE]";

                    desc = "CHEMIN DE CÂBLES PERFORÉ GALVANISÉ 300x60 mm";

                    size = "300x60 mm";

                    sched = "Galvanisé à chaud";

                    mat = "Acier Galva";

                    qty = qty > 0 ? qty : 35.0;

                    unit = "m";

                    unitW = 4.40;

                } else if (rule === 'MISSING_JUNCTION_BOX') {

                    cat = "JUNCTION_BOX";

                    tag = "JB-102 [RÉSERVE LEVÉE]";

                    desc = "BOÎTE DE JONCTION INSTRUMENTATION INOX 316L AVEC BORNIERS & 16 PRESSE-ÉTOUPES M20";

                    size = "400x300x160 mm";

                    sched = "ATEX Ex-e / Ex-ia IP66";

                    mat = "Inox 316L";

                    qty = 1.0;

                    unit = "EA";

                    unitW = 12.0;

                } else if (rule === 'MISSING_MULTIPAIR_CABLE') {

                    cat = "CABLE";

                    tag = "C-MP-02 [RÉSERVE LEVÉE]";

                    desc = "CÂBLE MULTIPAIRE BLINDÉ 12X2X0.5 VERS SALLE DE CONTRÔLE";

                    size = "12x2x0.5";

                    sched = "INSTRUMENTATION BLINDÉ";

                    mat = "Cuivre étamé / PVC";

                    qty = qty > 0 ? qty : 75.0;

                    unit = "m";

                    unitW = 0.42;

                } else if (rule === 'VOLTAGE_DROP_RISK') {

                    cat = "CABLE";

                    tag = `${a.tag || 'CABLE'} [SECTION SURCLASSÉE]`;

                    desc = "CÂBLE RENFORCÉ U-1000 R2V 3G4 (CONFORMITÉ CHUTE DE TENSION ≤ 3%)";

                    size = "3G4";

                    sched = "U-1000 R2V";

                    mat = "Cuivre / PVC";

                    qty = 90.0;

                    unit = "m";

                    unitW = 0.26;

                }



                const totalW = Number((qty * unitW).toFixed(2));

                return {

                    category: cat,

                    tag: tag,

                    description: desc,

                    size: size,

                    schedule: sched,

                    material: mat,

                    quantity: qty,

                    unit: unit,

                    weight_unit: unitW,

                    weight_total: totalW,

                    remarks: `Résolu par validation ARKAN (Règle ${rule})`,

                    _is_validated_reserve: true,

                    _source_reserve_idx: idx

                };

            };



            // Validation d'une anomalie avec insertion dans la nomenclature

            window.validateIeAnomaly = function(idx) {

                if (!window.currentIeMtoAnomalies || !window.currentIeMtoAnomalies[idx]) return;

                const a = window.currentIeMtoAnomalies[idx];



                if (a.status === 'VALIDATED') {

                    a.status = 'OPEN';

                    a.validated_at = null;

                    a._inserted_ie_item = null;



                    // Retirer de la table MTO

                    if (window.currentIeMtoData) {

                        const itemIdx = window.currentIeMtoData.findIndex(it => it._source_reserve_idx === idx);

                        if (itemIdx !== -1) {

                            window.currentIeMtoData.splice(itemIdx, 1);

                        }

                    }

                    showToast("Validation annulée — réserve réouverte.", "info");

                } else {

                    a.status = 'VALIDATED';

                    a.validated_at = new Date().toLocaleString('fr-FR');



                    const newItem = window.resolveStandardIeItemFromAnomaly(a, idx, window.currentIeMtoData);

                    a._inserted_ie_item = newItem;



                    if (!window.currentIeMtoData) window.currentIeMtoData = [];

                    const existingIdx = window.currentIeMtoData.findIndex(it => it._source_reserve_idx === idx);

                    if (existingIdx !== -1) {

                        window.currentIeMtoData[existingIdx] = newItem;

                    } else {

                        window.currentIeMtoData.push(newItem);

                    }

                    showToast(`Réserve levée : ${newItem.description} (${newItem.quantity} ${newItem.unit}) inséré dans la nomenclature MTO !`, "success");

                }



                window.renderIeMtoAnomalies(window.currentIeMtoAnomalies);

                window.renderIeMtoTable(window.currentIeMtoData);

                updateIeKpis();

            };



            // Note sur anomalie

            window.promptIeAnomalyNote = function(idx) {

                if (!window.currentIeMtoAnomalies || !window.currentIeMtoAnomalies[idx]) return;

                const a = window.currentIeMtoAnomalies[idx];

                const currentNote = a.note || "";

                const userNote = prompt("Saisissez votre note technique d'ingénierie (justification, dérogation, calcul) :", currentNote);

                if (userNote !== null) {

                    a.note = userNote.trim();

                    const item = (window.currentIeMtoData || []).find(it => it._source_reserve_idx === idx);

                    if (item) {

                        item.remarks = a.note ? `Note ingénieur : ${a.note}` : `Résolu par validation ARKAN (Règle ${a.rule})`;

                    }

                    window.renderIeMtoAnomalies(window.currentIeMtoAnomalies);

                    window.renderIeMtoTable(window.currentIeMtoData);

                    showToast("Note ingénieur enregistrée.", "info");

                }

            };



            // Ignorer / Réouvrir

            window.ignoreIeAnomaly = function(idx) {

                if (!window.currentIeMtoAnomalies || !window.currentIeMtoAnomalies[idx]) return;

                const a = window.currentIeMtoAnomalies[idx];

                if (a.status === 'IGNORED') {

                    a.status = 'OPEN';

                    showToast("Réserve réouverte.", "info");

                } else {

                    if (a.status === 'VALIDATED') {

                        const itemIdx = window.currentIeMtoData.findIndex(it => it._source_reserve_idx === idx);

                        if (itemIdx !== -1) window.currentIeMtoData.splice(itemIdx, 1);

                    }

                    a.status = 'IGNORED';

                    a._inserted_ie_item = null;

                    showToast("Réserve ignorée.", "warning");

                }

                window.renderIeMtoAnomalies(window.currentIeMtoAnomalies);

                window.renderIeMtoTable(window.currentIeMtoData);

                updateIeKpis();

            };



            // Filtres discipline & catégorie

            window.setIeDisciplineFilter = function(filter) {

                window.currentIeDisciplineFilter = filter;

                document.querySelectorAll('.ie-disc-btn').forEach(btn => {

                    btn.classList.remove('active');

                    btn.style.background = 'transparent';

                    btn.style.color = 'var(--text-secondary)';

                });

                const activeBtn = document.getElementById(`btn-ie-filter-${filter.toLowerCase()}`);

                if (activeBtn) {

                    activeBtn.classList.add('active');

                    activeBtn.style.background = 'var(--accent-primary)';

                    activeBtn.style.color = '#fff';

                }

                window.renderIeMtoTable(window.currentIeMtoData);

            };



            window.setIeCategoryFilter = function(cat) {

                window.currentIeCategoryFilter = cat;

                document.querySelectorAll('.ie-cat-btn').forEach(btn => {

                    btn.classList.remove('active');

                    btn.style.background = 'transparent';

                    btn.style.color = 'var(--text-secondary)';

                });

                event.target.classList.add('active');

                event.target.style.background = 'var(--accent-primary)';

                event.target.style.color = '#fff';

                window.renderIeMtoTable(window.currentIeMtoData);

            };



            window.filterIeTableBySearch = function() {

                window.renderIeMtoTable(window.currentIeMtoData);

            };



            // Rendu du tableau d'extraction avec support d'édition

            window.renderIeMtoTable = function(items) {

                const tbody = document.getElementById('ie-mto-table-body');

                const tfoot = document.getElementById('ie-mto-table-footer');

                const searchVal = (document.getElementById('ie-table-search')?.value || '').toLowerCase().trim();

                if (!tbody) return;



                items = items || [];

                const catFilter = window.currentIeCategoryFilter;

                const discFilter = window.currentIeDisciplineFilter;



                const filtered = items.filter(it => {

                    const cat = it.category || '';

                    if (catFilter !== 'ALL') {

                        if (catFilter === 'CABLE' && cat !== 'CABLE') return false;

                        if (catFilter === 'CABLE_TRAY' && !['CABLE_TRAY', 'CONDUIT'].includes(cat)) return false;

                        if (catFilter === 'EARTHING' && cat !== 'EARTHING') return false;

                        if (catFilter === 'INSTRUMENT' && !['TRANSMITTER', 'INDICATOR', 'SWITCH', 'PRIMARY_ELEMENT', 'INSTRUMENT', 'CONTROL_VALVE', 'SAFETY_VALVE'].includes(cat)) return false;

                        if (catFilter === 'PANEL' && !['PANEL', 'JUNCTION_BOX', 'PULL_BOX', 'SWITCHGEAR_FEEDER'].includes(cat)) return false;

                    }



                    if (discFilter === 'ELEC') {

                        if (['TRANSMITTER', 'INDICATOR', 'SWITCH', 'PRIMARY_ELEMENT', 'CONTROL_VALVE', 'SAFETY_VALVE'].includes(cat)) return false;

                    } else if (discFilter === 'INST') {

                        if (['CABLE_TRAY', 'CONDUIT', 'EARTHING'].includes(cat) || (cat === 'PANEL' && !it.tag.includes('JB'))) return false;

                    }



                    if (searchVal) {

                        const corpus = `${it.tag || ''} ${it.description || ''} ${it.size || ''} ${it.remarks || ''}`.toLowerCase();

                        if (!corpus.includes(searchVal)) return false;

                    }

                    return true;

                });



                if (filtered.length === 0) {

                    tbody.innerHTML = `<tr><td colspan="12" style="text-align:center; padding:30px; color:var(--text-secondary);">Aucun article ne correspond aux filtres sélectionnés.</td></tr>`;

                    if (tfoot) tfoot.innerHTML = '';

                    return;

                }



                let sumQty = 0, sumWeight = 0;



                tbody.innerHTML = filtered.map((it, idx) => {

                    const isVal = Boolean(it._is_validated_reserve);

                    const qty = parseFloat(it.quantity) || 0;

                    const wTot = parseFloat(it.weight_total) || 0;

                    sumQty += qty;

                    sumWeight += wTot;



                    return `

                    <tr style="border-bottom:1px solid rgba(255,255,255,0.03); background:${isVal ? 'rgba(16,185,129,0.06)' : 'transparent'};">

                        <td style="padding:10px 12px; text-align:center; color:var(--text-secondary);">${idx+1}</td>

                        <td style="padding:10px 12px; text-align:center;">

                            <span style="font-size:10px; font-weight:800; padding:2px 6px; border-radius:4px; background:${isVal ? 'rgba(16,185,129,0.2)' : 'rgba(59,130,246,0.15)'}; color:${isVal ? '#34D399' : '#60A5FA'};">

                                ${isVal ? 'VALIDÉ' : 'EXTRAIT'}

                            </span>

                        </td>

                        <td style="padding:10px 12px; font-size:11px; font-weight:700; color:var(--text-secondary);">${escapeHtml(it.category || '-')}</td>

                        <td style="padding:10px 12px; font-family:monospace; font-weight:700; color:${isVal ? '#34D399' : '#60A5FA'};">${escapeHtml(it.tag || '-')}</td>

                        <td style="padding:10px 12px; font-weight:600; color:var(--text-primary);">${escapeHtml(it.description || '-')}</td>

                        <td style="padding:10px 12px; text-align:center; color:var(--accent-primary); font-weight:700;">${escapeHtml(it.size || '-')}</td>

                        <td style="padding:10px 12px; text-align:center; color:var(--text-secondary);">${escapeHtml(it.schedule || '-')}</td>

                        <td style="padding:10px 12px; text-align:right; font-weight:700; color:${isVal ? '#34D399' : 'var(--text-primary)'};">${qty.toFixed(1)}</td>

                        <td style="padding:10px 12px; text-align:center; color:var(--text-secondary);">${escapeHtml(it.unit || 'EA')}</td>

                        <td style="padding:10px 12px; text-align:right; font-weight:700; color:#22D3EE;">${wTot.toFixed(2)}</td>

                        <td style="padding:10px 12px; font-size:11px; color:${isVal ? '#93C5FD' : 'var(--text-secondary)'};">${escapeHtml(it.remarks || '-')}</td>

                        <td style="padding:10px 12px; text-align:center;">

                            <button onclick="deleteIeItem(${items.indexOf(it)})" style="background:transparent; border:none; color:var(--text-secondary); cursor:pointer; font-size:15px;" title="Supprimer de la nomenclature">

                                <i class="ph ph-trash"></i>

                            </button>

                        </td>

                    </tr>`;

                }).join('');



                if (tfoot) {

                    tfoot.innerHTML = `

                    <tr>

                        <td colspan="7" style="padding:12px; text-align:right; text-transform:uppercase; letter-spacing:0.5px;">TOTAL SÉLECTION</td>

                        <td style="padding:12px; text-align:right; color:#10B981; font-size:13px;">${sumQty.toFixed(1)}</td>

                        <td style="padding:12px; text-align:center;">-</td>

                        <td style="padding:12px; text-align:right; color:#22D3EE; font-size:13px;">${sumWeight.toLocaleString('fr-FR', {minimumFractionDigits:2, maximumFractionDigits:2})} kg</td>

                        <td colspan="2"></td>

                    </tr>`;

                }

            };



            window.deleteIeItem = function(idx) {

                if (window.currentIeMtoData && window.currentIeMtoData[idx]) {

                    window.currentIeMtoData.splice(idx, 1);

                    window.renderIeMtoTable(window.currentIeMtoData);

                    updateIeKpis();

                    showToast("Article retiré de la nomenclature.", "info");

                }

            };



            // Téléchargement Excel Professionnel (.xlsx)

            window.downloadIeExcel = async function(e) {

                if (e) e.preventDefault();

                const btn = document.getElementById('btn-ie-download-excel');

                const origHtml = btn ? btn.innerHTML : '';

                if (btn) btn.innerHTML = `<i class="ph ph-spinner" style="animation:spin 0.8s linear infinite;"></i> Génération Excel...`;



                try {

                    const payload = {

                        filename: (window.currentIeMetadata?.drawing_number || 'MTO_IE').replace(/[^a-zA-Z0-9_\-]/g, '_') + '.xlsx',

                        items: window.currentIeMtoData || [],

                        metadata: window.currentIeMetadata || {},

                        anomalies: window.currentIeMtoAnomalies || []

                    };



                    const base = (typeof window.API_BASE !== 'undefined' && window.API_BASE) || (typeof API_BASE !== 'undefined' && API_BASE) || 'http://127.0.0.1:8000';

                    const resp = await fetch(`${base}/ie-mto/export-excel`, {

                        method: 'POST',

                        headers: { 'Content-Type': 'application/json' },

                        body: JSON.stringify(payload)

                    });



                    if (!resp.ok) throw new Error(`Erreur génération Excel (${resp.status})`);

                    const data = await resp.json();



                    if (data.status === 'success' && data.excel_url) {

                        const fullUrl = data.excel_url.startsWith('http') ? data.excel_url : `${base}${data.excel_url}`;

                        const link = document.createElement('a');

                        link.href = fullUrl;

                        link.setAttribute('download', data.excel_filename || 'MTO_IE_Export.xlsx');

                        document.body.appendChild(link);

                        link.click();

                        document.body.removeChild(link);

                        showToast("Classeur Excel I&E à 6 onglets téléchargé avec succès !", "success");

                    } else {

                        throw new Error("Réponse serveur invalide");

                    }

                } catch(err) {

                    console.error("[MTO_IE] Erreur Excel :", err);

