        // ── 1. Toast Notification System (replaces all alert()) ──



        let _toastIdCounter = 0;



        function showToast(message, type = 'info', title = null, durationMs = 4000) {



            const container = document.getElementById('toast-container');



            if (!container) { console.warn('Toast:', message); return; }







            const icons = { success: 'ph-check-circle', error: 'ph-warning-circle', warning: 'ph-warning', info: 'ph-info' };



            const titles = { success: 'Succès', error: 'Erreur', warning: 'Attention', info: 'Information' };



            const id = 'toast-' + (++_toastIdCounter);







            const toast = document.createElement('div');



            toast.id = id;



            toast.className = `toast toast-${type}`;



            toast.innerHTML = `



                <i class="ph ${icons[type] || icons.info} toast-icon"></i>



                <div class="toast-body">



                    <div class="toast-title">${title || titles[type]}</div>



                    <div class="toast-message">${message}</div>



                </div>



                <span class="toast-close" onclick="dismissToast('${id}')">✕</span>



                <div class="toast-bar" style="animation-duration:${durationMs}ms;"></div>



            `;



            container.appendChild(toast);



            setTimeout(() => dismissToast(id), durationMs);



        }



        function dismissToast(id) {



            const el = document.getElementById(id);



            if (!el) return;



            el.classList.add('dismissing');



            setTimeout(() => el && el.remove(), 300);



        }



