        // ── 5. Table Sort & Filter ──



        let _pidSortCol = -1;



        let _pidSortAsc = true;



        function filterPidTable(query) {



            const tbody = document.getElementById('pid-extracted-table-body');



            if (!tbody) return;



            const q = query.toLowerCase().trim();







            // Sync values with the primary P&ID drawing search input



            const searchInput = document.getElementById('pid-search-input');



            if (searchInput && searchInput.value !== query) {



                searchInput.value = query;



            }







            const rows = tbody.querySelectorAll('tr');



            rows.forEach(row => {



                const text = row.textContent.toLowerCase();



                row.style.display = (!q || text.includes(q)) ? '' : 'none';



            });







            // Filter sidebar elements



            const sidebarRows = document.querySelectorAll('.pid-equip-row');



            sidebarRows.forEach(row => {



                const tag = row.getAttribute('data-tag') || '';



                const type = row.getAttribute('data-type') || '';



                const match = !q || tag.includes(q) || type.includes(q);



                row.style.display = match ? 'flex' : 'none';



            });







            // Hide empty category groups in sidebar



            const groups = document.querySelectorAll('.pid-category-group');



            groups.forEach(group => {



                const subRows = group.querySelectorAll('.pid-equip-row');



                let hasVisible = false;



                for (let i = 0; i < subRows.length; i++) {



                    if (subRows[i].style.display !== 'none') {



                        hasVisible = true;



                        break;



                    }



                }



                group.style.display = hasVisible ? 'block' : 'none';



            });



        }



        function sortPidTable(colIdx) {



            const tbody = document.getElementById('pid-extracted-table-body');



            if (!tbody) return;



            const asc = (_pidSortCol === colIdx) ? !_pidSortAsc : true;



            _pidSortCol = colIdx; _pidSortAsc = asc;







            // Update header classes



            document.querySelectorAll('#pid-extraction-table th.sortable').forEach((th, i) => {



                th.classList.remove('sort-asc', 'sort-desc');



                if (i === colIdx) th.classList.add(asc ? 'sort-asc' : 'sort-desc');



            });







            const rows = Array.from(tbody.querySelectorAll('tr'));



            rows.sort((a, b) => {



                const cells_a = a.querySelectorAll('td');



                const cells_b = b.querySelectorAll('td');



                if (!cells_a[colIdx] || !cells_b[colIdx]) return 0;



                let va = cells_a[colIdx].textContent.trim();



                let vb = cells_b[colIdx].textContent.trim();



                if (colIdx === 3) { // Confidence: numeric sort



                    va = parseFloat(va) || 0;



                    vb = parseFloat(vb) || 0;



                    return asc ? va - vb : vb - va;



                }



                return asc ? va.localeCompare(vb, 'fr') : vb.localeCompare(va, 'fr');



            });



            rows.forEach(r => tbody.appendChild(r));



        }







