        let _tourStep = 0;



        let _tourHighlighted = null;



        function startTour() {



            _tourStep = 0;



            document.getElementById('tour-overlay').style.display = 'block';



            renderTourStep();



        }



        function renderTourStep() {



            const step = _tourSteps[_tourStep];



            document.getElementById('tour-title').textContent = step.title;



            document.getElementById('tour-desc').textContent = step.desc;



            document.getElementById('tour-next-btn').textContent = (_tourStep === _tourSteps.length - 1) ? 'Terminer [OK]' : 'Suivant →';







            // Dots



            const dots = document.getElementById('tour-dots');



            dots.innerHTML = _tourSteps.map((_, i) => `<div class="tour-dot ${i === _tourStep ? 'active' : ''}"></div>`).join('');







            // Highlight target



            if (_tourHighlighted) { _tourHighlighted.classList.remove('tour-highlight'); _tourHighlighted = null; }



            const target = step.target ? document.getElementById(step.target) : null;



            if (target) {



                target.classList.add('tour-highlight');



                _tourHighlighted = target;



                // Position tooltip near target



                const rect = target.getBoundingClientRect();



                const tip = document.getElementById('tour-tooltip');



                tip.style.transform = '';



                const tipW = 320; const tipH = 180;



                let top = rect.bottom + 12;



                let left = rect.left;



                if (top + tipH > window.innerHeight) top = rect.top - tipH - 12;



                if (left + tipW > window.innerWidth) left = window.innerWidth - tipW - 12;



                tip.style.top = Math.max(10, top) + 'px';



                tip.style.left = Math.max(10, left) + 'px';



            } else {



                const tip = document.getElementById('tour-tooltip');



                tip.style.top = '50%'; tip.style.left = '50%';



                tip.style.transform = 'translate(-50%,-50%)';



            }



        }



        function tourNext() {



            if (_tourStep >= _tourSteps.length - 1) { skipTour(); return; }



            _tourStep++;



            renderTourStep();



        }



        function skipTour() {



            document.getElementById('tour-overlay').style.display = 'none';



            if (_tourHighlighted) { _tourHighlighted.classList.remove('tour-highlight'); _tourHighlighted = null; }



            localStorage.setItem('arkan_tour_done', '1');



        }







        document.addEventListener('keydown', function(e) {



            const isEditingText = ['INPUT', 'TEXTAREA'].includes(document.activeElement.tagName);







            // Spotlight keyboard navigation



            const spotlight = document.getElementById('spotlight-overlay');



            if (spotlight && spotlight.style.display !== 'none') {



                if (e.key === 'ArrowDown') {



                    e.preventDefault();



                    if (spotlightResultsData.length > 0) {



                        spotlightSelectedIndex = (spotlightSelectedIndex + 1) % spotlightResultsData.length;



                        renderSpotlightResults();



                        const items = document.querySelectorAll('.spotlight-item');



                        if (items[spotlightSelectedIndex]) items[spotlightSelectedIndex].scrollIntoView({ block: 'nearest' });



                    }



                    return;



                } else if (e.key === 'ArrowUp') {



                    e.preventDefault();



                    if (spotlightResultsData.length > 0) {



                        spotlightSelectedIndex = (spotlightSelectedIndex - 1 + spotlightResultsData.length) % spotlightResultsData.length;



                        renderSpotlightResults();



                        const items = document.querySelectorAll('.spotlight-item');



                        if (items[spotlightSelectedIndex]) items[spotlightSelectedIndex].scrollIntoView({ block: 'nearest' });



                    }



                    return;



                } else if (e.key === 'Enter') {



                    e.preventDefault();



                    if (spotlightSelectedIndex >= 0 && spotlightSelectedIndex < spotlightResultsData.length) {



                        spotlightResultsData[spotlightSelectedIndex].action();



                        closeGlobalSearch();



                    }



                    return;



                }



            }







            // Ctrl+K -> Global search



            if (e.ctrlKey && e.key.toLowerCase() === 'k') {



                e.preventDefault();



                openGlobalSearch();



            }



            // Ctrl+Z -> Undo P&ID action



            if (e.ctrlKey && e.key.toLowerCase() === 'z') {



                if (!isEditingText && window.currentView === 'pid') {



                    e.preventDefault();



                    undoPidAction();



                }



            }



            // Ctrl+Y -> Redo P&ID action



            if (e.ctrlKey && e.key.toLowerCase() === 'y') {



                if (!isEditingText && window.currentView === 'pid') {



                    e.preventDefault();



                    redoPidAction();



                }



