        function calculateCivilQuantities(type, dimsText) {



            // Default fallbacks



            let beton = 0;



            let coffrage = 0;



            let ferraillage = 0;







            // Try to extract 3 numbers (length x width x thickness) or (diameter x height)



            const numbers = [];



            const matches = (dimsText || "").match(/(\d+(?:\.\d+)?)/g);



            if (matches) {



                matches.forEach(m => numbers.push(parseFloat(m)));



            }







            const lowType = (type || "").toLowerCase();







            if (lowType.includes("semelle") || lowType.includes("pad") || lowType.includes("fondation") || lowType.includes("sem")) {



                let l = 1.5, w = 1.5, h = 0.5;



                if (numbers.length >= 3) {



                    l = numbers[0]; w = numbers[1]; h = numbers[2];



                    if (l > 10) { l /= 1000; w /= 1000; h /= 1000; }



                } else if (numbers.length === 2) {



                    l = numbers[0]; w = numbers[0]; h = numbers[1];



                    if (l > 10) { l /= 1000; w /= 1000; h /= 1000; }



                }



                beton = l * w * h;



                coffrage = 2 * (l + w) * h;



                ferraillage = beton * 85; 



            } else if (lowType.includes("poteau") || lowType.includes("column") || lowType.includes("pot") || lowType.includes("col")) {



                let l = 0.4, w = 0.4, h = 3.0;



                if (numbers.length >= 3) {



                    l = numbers[0]; w = numbers[1]; h = numbers[2];



                    if (l > 10) { l /= 1000; w /= 1000; }



                    if (h > 100) { h /= 1000; }



                } else if (numbers.length === 2) {



                    l = numbers[0]; w = numbers[0]; h = numbers[1];



                    if (l > 10) { l /= 1000; w /= 1000; }



                    if (h > 100) { h /= 1000; }



                }



                beton = l * w * h;



                coffrage = 2 * (l + w) * h;



                ferraillage = beton * 120;



            } else if (lowType.includes("voile") || lowType.includes("wall") || lowType.includes("mur")) {



                let l = 5.0, w = 0.2, h = 3.0;



                if (numbers.length >= 3) {



                    l = numbers[0]; w = numbers[1]; h = numbers[2];



                    if (l > 100) { l /= 1000; }



                    if (w > 10) { w /= 1000; }



                    if (h > 100) { h /= 1000; }



                } else if (numbers.length === 2) {



                    l = numbers[0]; w = 0.2; h = numbers[1];



                    if (l > 100) { l /= 1000; }



                    if (h > 100) { h /= 1000; }



                }



                beton = l * w * h;



                coffrage = 2 * l * h;



                ferraillage = beton * 95;



            } else if (lowType.includes("pieu") || lowType.includes("pile")) {



                let d = 0.6, h = 12.0;



                if (numbers.length >= 2) {



                    d = numbers[0]; h = numbers[1];



                    if (d > 10) { d /= 1000; }



                    if (h > 100) { h /= 1000; }



                }



                beton = Math.PI * (d / 2) * (d / 2) * h;



                coffrage = 0;



                ferraillage = beton * 110;



            } else if (lowType.includes("platine") || lowType.includes("ancrage") || lowType.includes("anc")) {



                let l = 0.3, w = 0.3, h = 0.02;



                if (numbers.length >= 3) {



                    l = numbers[0]; w = numbers[1]; h = numbers[2];



                    if (l > 10) { l /= 1000; w /= 1000; h /= 1000; }



                }



                beton = 0;



                coffrage = 0;



                ferraillage = l * w * h * 7850;



            } else {



                let l = 1.0, w = 1.0, h = 1.0;



                if (numbers.length >= 3) {



                    l = numbers[0]; w = numbers[1]; h = numbers[2];



                    if (l > 10) { l /= 1000; w /= 1000; h /= 1000; }



                }



                beton = l * w * h;



                coffrage = 2 * (l + w) * h;



                ferraillage = beton * 90;



            }







            return { beton, coffrage, ferraillage };



        }







        function getCurrentTableState() {



            const tbody = document.getElementById('pid-extracted-table-body');



            if (!tbody) return [];



            const rows = tbody.querySelectorAll('tr');



            const state = [];



            const discipline = document.getElementById('plan-discipline-selector')?.value || 'pid';







