                const typeInput = cells[1].querySelector('input');







                if (discipline === 'isometric') {



                if (titleEl) titleEl.textContent = "Lecteur d'Isométriques de Tuyauterie (IA)";



                if (subEl) subEl.textContent = "Extraction automatique de spools, soudures chantier (FW), soudures atelier (WS), cotes d'élévation, pentes et supports.";



