                    if (tagInput) {



                        tag = tagInput.value.trim();



                        type = typeInput ? typeInput.value.trim() : '';



                        dimensions = dimInput ? dimInput.value.trim() : '';



                        confidence = 100;



                    } else {



                        tag = cells[0].textContent.trim();



                        type = cells[1].textContent.trim();



                        dimensions = cells[2].textContent.trim();



                        beton = parseFloat(cells[3].textContent.trim()) || 0;



                        coffrage = parseFloat(cells[4].textContent.trim()) || 0;



                        ferraillage = parseFloat(cells[5].textContent.trim()) || 0;



                        confidence = 95;



                    }



                    if (tag) {



                        state.push({ tag, type, dimensions, line: dimensions, beton, coffrage, ferraillage, confidence, isManual: !!tagInput });



                    }



                } else {



                    const lineInput = cells[2].querySelector('input');



