                        tag = cells[0].textContent.trim();



                        type = cells[1].textContent.trim();



                        line = cells[2].textContent.trim();



                        const confText = cells[3].textContent.trim();



                        confidence = parseInt(confText) || 95;



                    }



                    if (tag) {



                        state.push({ tag, type, line, confidence, isManual: !!tagInput });



                    }



                }



            });



            return state;



        }







