        function savePidState() {



            const currentState = getCurrentTableState();



            if (pidUndoStack.length > 0) {



                const prev = pidUndoStack[pidUndoStack.length - 1];



                if (JSON.stringify(prev) === JSON.stringify(currentState)) return;



            }



            pidUndoStack.push(currentState);



            if (pidUndoStack.length > 30) pidUndoStack.shift();



            pidRedoStack = [];



            updateUndoRedoButtons();



        }







        function undoPidAction() {



            if (pidUndoStack.length === 0) return;



            const currentState = getCurrentTableState();



            pidRedoStack.push(currentState);







            const prev = pidUndoStack.pop();



            renderTableFromState(prev);



            updateUndoRedoButtons();



            showToast("Action annulée", "info");



        }







        function redoPidAction() {



            if (pidRedoStack.length === 0) return;



            const currentState = getCurrentTableState();



            pidUndoStack.push(currentState);







            const next = pidRedoStack.pop();



            renderTableFromState(next);



            updateUndoRedoButtons();



            showToast("Action rétablie", "info");



        }







        function deletePidRow(btn) {



            savePidState();



            btn.closest('tr').remove();



            savePidState();



        }







        function updateUndoRedoButtons() {



            const uBtn = document.getElementById('pid-btn-undo');



            const rBtn = document.getElementById('pid-btn-redo');



            if (uBtn) {



                uBtn.disabled = pidUndoStack.length === 0;



                uBtn.style.opacity = pidUndoStack.length === 0 ? '0.5' : '1';



                uBtn.style.cursor = pidUndoStack.length === 0 ? 'not-allowed' : 'pointer';



            }



            if (rBtn) {



                rBtn.disabled = pidRedoStack.length === 0;



                rBtn.style.opacity = pidRedoStack.length === 0 ? '0.5' : '1';



                rBtn.style.cursor = pidRedoStack.length === 0 ? 'not-allowed' : 'pointer';



            }



        }







        // --- 4. Exporter en Markdown ---



        function triggerDownload(content, filename) {



            const blob = new Blob([content], { type: 'text/markdown;charset=utf-8;' });



            const url = URL.createObjectURL(blob);



            const a = document.createElement('a');



            a.href = url;



            a.download = filename;



            document.body.appendChild(a);



            a.click();



            document.body.removeChild(a);



            URL.revokeObjectURL(url);



            showToast(`Fichier ${filename} exporté !`, 'success');



        }







