        // ── Volet Gauche Ajustable Manuellement & Roulette Déroulante ──



        function initSidebarResizer() {



            const sidebar = document.querySelector('.sidebar');



            const resizer = document.getElementById('sidebar-resizer');



            const scrollable = document.getElementById('sidebar-scrollable');



            if (!sidebar || !resizer) return;







            // Restauration de la largeur personnalisée enregistrée



            try {



                const savedWidth = localStorage.getItem('arkan_sidebar_width');



                if (savedWidth) {



                    const parsed = parseInt(savedWidth, 10);



                    if (!isNaN(parsed) && parsed >= 160 && parsed <= 600) {



                        const maxW = Math.max(160, Math.floor(window.innerWidth * 0.38));



                        sidebar.style.width = Math.min(parsed, maxW) + 'px';



                    }



                }



            } catch(e) {}







            // Branchement interactif de la roulette de souris sur l'ensemble du volet gauche



            if (scrollable) {



                sidebar.addEventListener('wheel', function(e) {



                    if (e.target !== scrollable && !scrollable.contains(e.target)) {



                        scrollable.scrollTop += e.deltaY;



                    }



                }, { passive: true });



            }







            let isResizing = false;







            resizer.addEventListener('mousedown', function(e) {



                e.preventDefault();



                isResizing = true;



                sidebar.classList.add('is-resizing');



                resizer.classList.add('is-resizing');



                document.body.style.cursor = 'col-resize';



                document.body.style.userSelect = 'none';







                function onMouseMove(e) {



                    if (!isResizing) return;



                    let newWidth = e.clientX;



                    const maxAllowed = Math.max(180, Math.floor(window.innerWidth * 0.45));



                    newWidth = Math.max(160, Math.min(newWidth, Math.min(600, maxAllowed)));



                    sidebar.style.width = newWidth + 'px';



                }







                function onMouseUp() {



                    if (!isResizing) return;



                    isResizing = false;



                    sidebar.classList.remove('is-resizing');



                    resizer.classList.remove('is-resizing');



                    document.body.style.cursor = '';



                    document.body.style.userSelect = '';



                    document.removeEventListener('mousemove', onMouseMove);



                    document.removeEventListener('mouseup', onMouseUp);







                    try {



                        const finalWidth = sidebar.offsetWidth;



                        localStorage.setItem('arkan_sidebar_width', finalWidth.toString());



                    } catch(e) {}







                    handleWindowProportions();



                }







                document.addEventListener('mousemove', onMouseMove);



                document.addEventListener('mouseup', onMouseUp);



            });







            // Double-clic pour réinitialiser à la largeur proportionnelle standard



            resizer.addEventListener('dblclick', function() {



                const defaultW = Math.min(280, Math.max(180, Math.floor(window.innerWidth * 0.22)));



                sidebar.style.width = defaultW + 'px';



                try {



                    localStorage.setItem('arkan_sidebar_width', defaultW.toString());



                } catch(e) {}



                if (typeof showToast === 'function') {



                    showToast('Volet latéral réinitialisé (' + defaultW + 'px)', 'info');



                }



                handleWindowProportions();



            });



        }







        // ── Gestionnaire Global de Proportionnement d'Affichage (Sortie Plein Écran & Redimensionnement) ──



        function handleWindowProportions() {



            const winW = window.innerWidth;



            const winH = window.innerHeight;



            const sidebar = document.querySelector('.sidebar');







            // 1. Proportionnement automatique et intelligent du volet gauche



            if (sidebar) {



                const maxAllowed = Math.max(160, Math.floor(winW * 0.35));



                if (sidebar.offsetWidth > maxAllowed) {



                    sidebar.style.width = maxAllowed + 'px';



                }



            }







            // 2. Réajustement instantané des graphiques Chart.js



            if (window.Chart && Chart.instances) {



                try {



                    Object.values(Chart.instances).forEach(function(chart) {



                        if (chart && typeof chart.resize === 'function') {



                            chart.resize();



                        }



                    });



                } catch(e) {}



            }







            // 4. Réajustement du Lecteur de Plans P&ID si actif



            if (typeof resizeCanvas === 'function') {



                const pidView = document.getElementById('pid-view');



                if (pidView && pidView.classList.contains('active-view')) {



                    try { resizeCanvas(); } catch(e) {}



                }



            }







            // 5. Contention sécurisée des modales ouvertes pour ne jamais dépasser de la fenêtre



            document.querySelectorAll('.modal-container, .modal-box, [id*="-modal-box"]').forEach(function(modal) {



                if (modal.offsetWidth > winW * 0.96) {



                    modal.style.width = '95vw';



                }



                if (modal.offsetHeight > winH * 0.92) {



                    modal.style.height = '90vh';



                }



            });



        }







