        function updateVaultPhysics() {



            const damping = 0.88;



            const repulsion = 4500;



            const springDist = 130;



            const springK = 0.0035;



            const centerGravity = 0.0007;







            // 1. Force de répulsion entre chaque paire de nœuds (Coulomb)



            for (let i = 0; i < vaultSimNodes.length; i++) {



                const n1 = vaultSimNodes[i];



                for (let j = i + 1; j < vaultSimNodes.length; j++) {



                    const n2 = vaultSimNodes[j];



                    const dx = n2.x - n1.x;



                    const dy = n2.y - n1.y;



                    const distSq = dx * dx + dy * dy + 100;



                    const dist = Math.sqrt(distSq);



                    const force = repulsion / distSq;



                    const fx = (dx / dist) * force;



                    const fy = (dy / dist) * force;



                    n1.vx -= fx;



                    n1.vy -= fy;



                    n2.vx += fx;



                    n2.vy += fy;



                }



            }







            // 2. Force de ressort sur les arêtes (Hooke)



            for (let e of vaultSimEdges) {



                const dx = e.target.x - e.source.x;



                const dy = e.target.y - e.source.y;



                const dist = Math.sqrt(dx * dx + dy * dy) || 1;



                const delta = dist - springDist;



                const force = delta * springK;



                const fx = (dx / dist) * force;



                const fy = (dy / dist) * force;



                e.source.vx += fx;



                e.source.vy += fy;



                e.target.vx -= fx;



                e.target.vy -= fy;



            }







            // 3. Gravité vers le centre & intégration de vitesse



            for (let n of vaultSimNodes) {



                if (n === vaultCam.draggedNode) continue; // Nœud glissé fixé sous la souris



                n.vx -= n.x * centerGravity;



                n.vy -= n.y * centerGravity;



                n.vx *= damping;



                n.vy *= damping;



                n.x += n.vx;



                n.y += n.vy;



            }



        }







        function renderVaultCanvas() {



            const canvas = document.getElementById('vault-graph-canvas');



            if (!canvas) return;



            const ctx = canvas.getContext('2d');



            const dpr = window.devicePixelRatio || 1;



            const rect = canvas.getBoundingClientRect();







            if (canvas.width !== rect.width * dpr || canvas.height !== rect.height * dpr) {



                canvas.width = rect.width * dpr;



                canvas.height = rect.height * dpr;



            }







            ctx.save();



            ctx.scale(dpr, dpr);



            ctx.clearRect(0, 0, rect.width, rect.height);







            // Appliquer la translation et le zoom de la caméra



            ctx.translate(vaultCam.x, vaultCam.y);



            ctx.scale(vaultCam.zoom, vaultCam.zoom);







            // Filtrage actif par cluster et recherche



            const searchLower = vaultSearchQuery.toLowerCase();







            // 1. Dessiner les arêtes [[wikilinks]]



            for (let e of vaultSimEdges) {



                const sVisible = isNodeVisibleInFilter(e.source, vaultActiveCluster, searchLower);



                const tVisible = isNodeVisibleInFilter(e.target, vaultActiveCluster, searchLower);



                if (!sVisible && !tVisible) continue;







                const isHighlighted = (vaultSelectedNode && (e.source === vaultSelectedNode || e.target === vaultSelectedNode)) ||



                                      (vaultHoveredNode && (e.source === vaultHoveredNode || e.target === vaultHoveredNode));







                ctx.beginPath();



                ctx.moveTo(e.source.x, e.source.y);



                ctx.lineTo(e.target.x, e.target.y);



                ctx.strokeStyle = isHighlighted ? 'rgba(192, 132, 252, 0.85)' : 'rgba(255, 255, 255, 0.08)';



                ctx.lineWidth = isHighlighted ? 2.0 / vaultCam.zoom : 1.0 / vaultCam.zoom;



                ctx.stroke();



            }







            // 2. Dessiner les nœuds (sphères lumineuses Obsidian)



            for (let n of vaultSimNodes) {



                const visible = isNodeVisibleInFilter(n, vaultActiveCluster, searchLower);



                const isSelected = n === vaultSelectedNode;



                const isHovered = n === vaultHoveredNode;



                const alpha = visible ? 1.0 : 0.15;







