                return `<span onclick="navigateToVaultWikilink('${targetKey}')" style="color:#C084FC; background:rgba(168,85,247,0.15); border:1px solid rgba(168,85,247,0.4); border-radius:4px; padding:1px 6px; font-weight:600; cursor:pointer; text-decoration:underline; font-size:11px; display:inline-block; margin:1px 2px;" title="Aller à la note [[${targetKey}]]">&#128279; [[${label}]]</span>`;



            });







            // Conversion minimale markdown : titres et listes



            safe = safe.replace(/^### (.*$)/gim, '<h4 style="color:#F1F5F9; font-size:12.5px; margin:12px 0 4px 0; font-weight:700;">$1</h4>');



            safe = safe.replace(/^## (.*$)/gim, '<h3 style="color:#A78BFA; font-size:13.5px; margin:14px 0 6px 0; font-weight:700;">$1</h3>');



            safe = safe.replace(/^# (.*$)/gim, '<h2 style="color:#38BDF8; font-size:15px; margin:16px 0 8px 0; font-weight:800;">$1</h2>');



            safe = safe.replace(/^\> (.*$)/gim, '<blockquote style="border-left:3px solid #A855F7; margin:6px 0; padding-left:10px; color:#94A3B8; font-style:italic;">$1</blockquote>');



            safe = safe.replace(/^- (.*$)/gim, '<li style="margin-left:16px; margin-bottom:3px;">$1</li>');



            safe = safe.replace(/\n\n/g, '<br><br>');







            return safe;



        }







