        window.deduplicateArhCommentsClient = function(rawComments) {



            if (!Array.isArray(rawComments)) return [];



            const seenKeys = new Set();



            const result = [];



            for (const c of rawComments) {



                if (!c || typeof c !== 'object') continue;



                const normTitle = String(c.title || '')



                    .replace(/\(\s*Page\s*\d+[^)]*\)/gi, '')



                    .replace(/\s+/g, ' ')



                    .trim()



                    .toUpperCase();



                const piece = String(c.piece_code || c.category || '').toUpperCase();



                const key = `${piece}::${normTitle}`;



                if (seenKeys.has(key)) continue;



                seenKeys.add(key);



                result.push(c);



            }



            return result;



        };







