            let dossierStage = stageSelect ? stageSelect.value : "";







            if (!projName || projName.trim() === "") {



                if (projNameEl) projNameEl.style.border = "2px solid #E74C3C";



                alert("🛑 IMPORTATION ANNULÉE : Aucun Projet ARH sélectionné.\nVeuillez choisir un projet dans la liste déroulante ou cliquer sur '+ Nouveau' pour en créer un.");



                const fileInput = document.getElementById('arh-file-input');



                if (fileInput) fileInput.value = "";



                return;



            }



            if (projNameEl) projNameEl.style.border = "1px solid var(--border-color)";







            if (!dossierStage || dossierStage.trim() === "") {



                if (stageSelect) stageSelect.style.border = "2px solid #E74C3C";



                alert("🛑 IMPORTATION ANNULÉE : Aucun Stade de Dossier ARH sélectionné.\nVeuillez choisir s'il s'agit d'un Dossier Préliminaire (Usine) ou d'un Dossier Final (Chantier/Mise en produit).");



                const fileInput = document.getElementById('arh-file-input');



                if (fileInput) fileInput.value = "";



                return;



            }



            if (stageSelect) stageSelect.style.border = "1px solid var(--border-color)";







            const unitName = document.getElementById('arh-unit-input').value.trim() || "UNIT-100";







            const progressEl = document.getElementById('arh-upload-progress');



            const statusEl = document.getElementById('arh-progress-status');



            const progressBar = document.getElementById('arh-progress-bar');



            const progressPercent = document.getElementById('arh-progress-percent');







            let equipTypeSelect = document.getElementById('arh-equipment-type-select');



            let equipmentType = equipTypeSelect ? equipTypeSelect.value : "AUTO";







            progressEl.classList.remove('hidden');



            if (progressBar) progressBar.style.width = '0%';



            if (progressPercent) progressPercent.textContent = '0%';



            statusEl.textContent = `Téléversement et analyse du dossier ARH du projet '${projName}' [Stade: ${dossierStage}]...`;







            const formData = new FormData();



            formData.append('project_name', projName);



            formData.append('unit_name', unitName);



            formData.append('dossier_stage', dossierStage);



            formData.append('equipment_type', equipmentType);







            for (let i = 0; i < files.length; i++) {



                formData.append('files', files[i]);



            }







            return new Promise((resolve, reject) => {



                const xhr = new XMLHttpRequest();



                xhr.open('POST', `${API_BASE}/api/arh/upload`, true);







                xhr.upload.onprogress = function(e) {



                    if (e.lengthComputable) {



                        const percentComplete = Math.round((e.loaded / e.total) * 100);



                        if (progressBar) progressBar.style.width = percentComplete + '%';



                        if (progressPercent) progressPercent.textContent = percentComplete + '%';



                        if (percentComplete >= 100) {



                            statusEl.textContent = `Traitement IA, vérification des feuilles, calculs et des cachets en cours...`;



                        }



                    }



                };







                xhr.onload = async function() {



                    progressEl.classList.add('hidden');



                    if (xhr.status >= 200 && xhr.status < 300) {



                        try {



                            const data = JSON.parse(xhr.responseText);



                            currentArhDossier = data.data || data.dossier;



                            showToast("Audit du dossier ARH terminé avec succès !", "success");



                            const fileInput = document.getElementById('arh-file-input');



                            if (fileInput) fileInput.value = "";



                            renderArhDossierWorkspace(currentArhDossier);



                            loadArhDashboard();



                            loadArhProjects();



                            resolve(data);



                        } catch (e) {



                            showToast("Erreur lors de la lecture de la réponse serveur.", "error");



                            reject(e);



                        }



                    } else {



                        try {



                            const err = JSON.parse(xhr.responseText);



                            showToast("Erreur d'analyse ARH: " + (err.detail || "Opération échouée"), "error");



                        } catch(e) {



                            showToast("Erreur HTTP " + xhr.status + " lors de l'envoi du dossier.", "error");



                        }



                        reject(xhr.responseText);



                    }



                };







                xhr.onerror = function() {



                    progressEl.classList.add('hidden');



                    showToast("Erreur de connexion au serveur ARH.", "error");



                    reject(new Error("Network Error"));



                };







                xhr.send(formData);



            });



        }







