        function selectArhPageForVisualization(filename, pageNum, totalPages, targetSnippet = '', targetTitle = '') {



            currentVisFilename = filename;



            currentVisPage = parseInt(pageNum);



            currentVisTotalPages = parseInt(totalPages);







            let dossierId = "";



            if (currentArhDossier) {



                dossierId = currentArhDossier.dossier_id || (currentArhDossier.data && currentArhDossier.data.dossier_id) || "";



            }







            // Si targetSnippet ou targetTitle ne sont pas passés, tenter de les extraire depuis le sheet_audit_log



            if (!targetSnippet && !targetTitle && currentArhDossier) {



                const logs = currentArhDossier.sheet_audit_log || (currentArhDossier.data && currentArhDossier.data.sheet_audit_log) || [];



                const matchedLog = logs.find(l => parseInt(l.page) === currentVisPage && (l.document === filename || !filename));



                if (matchedLog && matchedLog.anomalies && matchedLog.anomalies.length > 0) {



                    const firstAnom = matchedLog.anomalies[0];



                    targetSnippet = firstAnom.target_content || (firstAnom.highlight_terms && firstAnom.highlight_terms[0]) || firstAnom.quote_snippet || '';



                    targetTitle = firstAnom.title || '';



                }



            }







            // Update Metadata display



            document.getElementById('arh-vis-filename').textContent = filename;



            document.getElementById('arh-vis-page').textContent = `${currentVisPage} / ${currentVisTotalPages}`;







            // Show panels and download button



            document.getElementById('arh-visualizer-meta').style.display = 'flex';



            document.getElementById('arh-visualizer-controls').style.display = 'flex';







            const downloadBtn = document.getElementById('arh-visualizer-download-btn');



            downloadBtn.style.display = 'inline-flex';



            downloadBtn.href = `${API_BASE}/api/arh/dossiers/${dossierId}/view-pdf/${filename}`;







            // Hide empty prompt, show image



            document.getElementById('arh-visualizer-empty').style.display = 'none';







            const visImg = document.getElementById('arh-visualizer-image');



            const loader = document.getElementById('arh-visualizer-loader');







            visImg.style.display = 'none';



            loader.classList.remove('hidden');







            // Force load the page image with query parameters for precise highlighting



            const qParams = [];



            if (targetSnippet) qParams.push(`q=${encodeURIComponent(targetSnippet)}`);



            if (targetTitle) qParams.push(`title=${encodeURIComponent(targetTitle)}`);



            const qStr = qParams.length > 0 ? `&${qParams.join('&')}` : '';







            const imgUrl = `${API_BASE}/api/arh/dossiers/${dossierId}/pages/${encodeURIComponent(filename)}/${currentVisPage}.png?t=${Date.now()}${qStr}`;



            visImg.src = imgUrl;



            visImg.onload = () => {



                loader.classList.add('hidden');



                visImg.style.display = 'block';



                resetArhVisZoom();



            };



            visImg.onerror = () => {



                if (qParams.length > 0) {



                    const fallbackUrl = `${API_BASE}/api/arh/dossiers/${dossierId}/pages/${encodeURIComponent(filename)}/${currentVisPage}.png?highlight=false&t=${Date.now()}`;



                    visImg.src = fallbackUrl;



                } else {



                    loader.classList.add('hidden');



                    document.getElementById('arh-visualizer-empty').style.display = 'block';



                    document.getElementById('arh-visualizer-empty').innerHTML = `



                        <i class="ph ph-x-circle" style="font-size:40px; color:#EB5757; margin-bottom:12px; display:block;"></i>



                        Erreur de génération visuelle de la page ${currentVisPage} pour '${filename}'.



                    `;



                }



            };



        }







        function changeArhVisPage(offset) {



            let targetPage = currentVisPage + offset;



            if (targetPage < 1) targetPage = 1;



            if (targetPage > currentVisTotalPages) targetPage = currentVisTotalPages;







            if (targetPage !== currentVisPage) {



                // Trouver la ligne correspondante dans la table pour la surbrillance



                const rows = document.querySelectorAll('#arh-sheets-table-body tr');



                for (let r of rows) {



                    const cols = r.querySelectorAll('td');



                    if (cols.length >= 2) {



                        const fileCol = cols[0].title || cols[0].textContent.trim();



                        const pageCol = cols[1].textContent.trim().split('/')[0].trim();



                        if (fileCol === currentVisFilename && parseInt(pageCol) === targetPage) {



                            r.click();



                            r.scrollIntoView({ block: 'nearest', behavior: 'smooth' });



                            return;



                        }



                    }



                }



                // Si non trouvé dans la table de non-conformité, forcer le changement d'image



                selectArhPageForVisualization(currentVisFilename, targetPage, currentVisTotalPages);



            }



        }







        function zoomArhVisImage(delta) {



            currentVisZoom = Math.max(0.5, Math.min(3.0, currentVisZoom + delta));



            const img = document.getElementById('arh-visualizer-image');



            if (img) {



                img.style.transform = `scale(${currentVisZoom})`;



            }



        }







        function resetArhVisZoom() {



            currentVisZoom = 1.0;



            const img = document.getElementById('arh-visualizer-image');



            if (img) {



                img.style.transform = `scale(1.0)`;



            }



        }







