        function resolveArhCommentDiscipline(c) {



            let disc = (c.discipline || '').toUpperCase();



            if (disc && disc !== 'GÉNÉRAL' && disc !== 'AUTRE') return disc;







            const primaryText = `${c.title || ''} ${c.category || ''}`.toUpperCase();



            const fullText = `${primaryText} ${c.observation || ''} ${c.standard || ''} ${c.document_concerned || ''}`.toUpperCase();







            // 1. Électricité & Instrumentation



            if (primaryText.includes('ELEC') || primaryText.includes('INST') || primaryText.includes('ATEX') || primaryText.includes('BATTER') || primaryText.includes('SOLAR') || primaryText.includes('PHOTO') || primaryText.includes('61439') || primaryText.includes('60079') || primaryText.includes('SIL') || primaryText.includes('TRANSMITTER') || primaryText.includes('FLOWMETER') || primaryText.includes('DIELECTR') || primaryText.includes('INSULATION')) {



                return 'ÉLECTRICITÉ & INSTRUMENTATION';



            }



            if (fullText.includes('BATTERIE') || fullText.includes('PANNEAU SOLAIRE') || fullText.includes('ATMOSPHÈRE EXPLOSIVE') || fullText.includes('ZONE 1') || fullText.includes('ZONE 2') || fullText.includes('TABLEAU BT') || fullText.includes('ARMOIRE ELECTRIQUE')) {



                return 'ÉLECTRICITÉ & INSTRUMENTATION';



            }







            // 2. Métallurgie & Matériaux



            if (primaryText.includes('METALLURG') || primaryText.includes('MATIERE') || primaryText.includes('MATIÈRE') || primaryText.includes('CEV') || primaryText.includes('COULÉE') || primaryText.includes('CHIMI') || primaryText.includes('CHARPY') || primaryText.includes('RESILIENCE') || primaryText.includes('DURET') || primaryText.includes('NACE') || primaryText.includes('10204')) {



                return 'MÉTALLURGIE';



            }



            if (fullText.includes('EN 10204 3.1') || fullText.includes('CARBONE EQUIVALENT') || fullText.includes('HRC') || fullText.includes('HARDNESS')) {



                return 'MÉTALLURGIE';



            }







            // 3. Qualité, Soudage & CND



            if (primaryText.includes('WELD') || primaryText.includes('SOUD') || primaryText.includes('WPS') || primaryText.includes('PQR') || primaryText.includes('CND') || primaryText.includes('NDT') || primaryText.includes('RADIO') || primaryText.includes('UT') || primaryText.includes('MT') || primaryText.includes('PT') || primaryText.includes('ITP') || primaryText.includes('PIE') || primaryText.includes('HOLD') || primaryText.includes('PLAQUE') || primaryText.includes('NAMEPLATE') || primaryText.includes('DEFECT')) {



                return 'QUALITÉ & CND';



            }



            if (fullText.includes('CONTROLE NON DESTRUCTIF') || fullText.includes('PLAN D\'INSPECTION') || fullText.includes('TIERS HABILITE') || fullText.includes('POINT D\'ARRET') || fullText.includes('PLAQUE SIGNALETIQUE')) {



                return 'QUALITÉ & CND';



            }







            // 4. Mécanique & Tuyauterie



            if (primaryText.includes('CALCUL') || primaryText.includes('PRESSION') || primaryText.includes('PRESSURE') || primaryText.includes('EPAISSEUR') || primaryText.includes('ÉPAISSEUR') || primaryText.includes('THICKNESS') || primaryText.includes('STRESS') || primaryText.includes('HYDROSTAT') || primaryText.includes('EPREUVE') || primaryText.includes('ÉPREUVE') || primaryText.includes('BRIDE') || primaryText.includes('FLANGE') || primaryText.includes('TRACE') || primaryText.includes('ISOMETRIQUE') || primaryText.includes('ALIGNMENT') || primaryText.includes('PROFILE')) {



                return 'MÉCANIQUE';



            }







            // 5. Administratif par défaut



            return 'ADMINISTRATIF';



        }







        window.updateArhKpiAndFilterCounts = function() {



            const comments = window.currentDossierComments || [];



            const total = comments.length;



            let critical = 0;



            let major = 0;



            let minor = 0;



            let resolved = 0;



            let missing = 0;







            const discCounts = {



                'ALL': total,



                'ÉLECTRICITÉ & INSTRUMENTATION': 0,



                'MÉTALLURGIE': 0,



                'MÉCANIQUE': 0,



                'QUALITÉ & CND': 0,



                'ADMINISTRATIF': 0



            };







            comments.forEach(c => {



                const p = (c.priority || c.severity || 'MAJOR').toUpperCase();



                if (p === 'CRITICAL') critical++;



                else if (p === 'MAJOR') major++;



                else minor++;







                const isRes = c.status === 'RESOLVED' || c.resolved === true;



                if (isRes) resolved++;







                const isMiss = Boolean(



                    c.is_missing_document ||



                    c.page_number === null ||



                    c.page_number === undefined ||



                    c.page_number === 0 ||



                    c.page_number === '0' ||



                    String(c.page || '').includes('Non Fournie') ||



                    String(c.page || '').includes('Non fournie') ||



                    String(c.page || '').includes('absent') ||



                    String(c.document_concerned || '').includes('Non fourni')



                );



                if (isMiss) missing++;







                const disc = resolveArhCommentDiscipline(c);



                c.discipline = disc;



                if (discCounts[disc] !== undefined) {



                    discCounts[disc]++;



                } else {



                    discCounts['ADMINISTRATIF']++;



                }



            });







            // Update KPI badges



            const elTot = document.getElementById('kpi-reserves-total');



            const elCrit = document.getElementById('kpi-reserves-critical');



            const elMaj = document.getElementById('kpi-reserves-major');



            const elMin = document.getElementById('kpi-reserves-minor');



            const elRes = document.getElementById('kpi-reserves-resolved');



            const elMiss = document.getElementById('kpi-reserves-missing');







            if (elTot) elTot.textContent = total;



            if (elCrit) elCrit.textContent = critical;



            if (elMaj) elMaj.textContent = major;



            if (elMin) elMin.textContent = minor;



            if (elRes) {



                const pct = total > 0 ? Math.round((resolved / total) * 100) : 0;



                elRes.textContent = `${resolved} / ${total} (${pct}%)`;



            }



            if (elMiss) elMiss.textContent = missing;







            // Update Discipline Filter Buttons



            const bAll = document.getElementById('btn-filter-disc-all');



            const bElec = document.getElementById('btn-filter-disc-elec');



            const bMet = document.getElementById('btn-filter-disc-met');



            const bMec = document.getElementById('btn-filter-disc-mec');



            const bQual = document.getElementById('btn-filter-disc-qual');



            const bAdm = document.getElementById('btn-filter-disc-adm');







            if (bAll) bAll.textContent = `Tous (${discCounts['ALL']})`;



            if (bElec) bElec.textContent = `⚡ Électricité & Inst. (${discCounts['ÉLECTRICITÉ & INSTRUMENTATION']})`;



            if (bMet) bMet.textContent = `🧪 Métallurgie (${discCounts['MÉTALLURGIE']})`;



            if (bMec) bMec.textContent = `📐 Mécanique (${discCounts['MÉCANIQUE']})`;



            if (bQual) bQual.textContent = `🔍 Qualité & CND (${discCounts['QUALITÉ & CND']})`;



            if (bAdm) bAdm.textContent = `🏛️ Administratif (${discCounts['ADMINISTRATIF']})`;



        };







