        function resolveArhRealFilename(docName) {



            const masterDoc = currentArhDossier ? (currentArhDossier.master_document || (currentArhDossier.data && currentArhDossier.data.master_document)) : '';



            if (!docName) return masterDoc || (currentArhDossier && currentArhDossier.files && currentArhDossier.files[0]) || '';



            const rawName = String(docName).trim();



            if (rawName.endsWith('.pdf') && (rawName.startsWith('DOC-') || rawName.includes('_'))) {



                return rawName;



            }



            if (!currentArhDossier) return rawName;



            const rawFiles = currentArhDossier.files || 



                             currentArhDossier.source_documents || 



                             currentArhDossier.received_documents || 



                             currentArhDossier.ingested_files || 



                             (currentArhDossier.documents && currentArhDossier.documents.map(d => d.filename || d.file_name || d.name)) || 



                             [];



            const files = Array.isArray(rawFiles) ? rawFiles.filter(Boolean) : [];



            if (!files.length) return masterDoc || rawName;



            if (files.includes(rawName)) return rawName;



            const lower = rawName.toLowerCase();



            const generic = !lower || lower === '?' || lower === '%3f' || ['dossier', 'dossier technique', 'note de calcul', 'annexe e', 'spécification', 'global', 'pièce', 'non spécifié'].some(g => lower.includes(g));



            if (generic) {



                if (masterDoc && files.includes(masterDoc)) return masterDoc;



                return masterDoc || files[0] || rawName;



            }



            const found = files.find(f => f && (f.toLowerCase() === lower || f.toLowerCase().includes(lower) || lower.includes(f.toLowerCase())));



            if (found) return found;



            return masterDoc || files[0] || rawName;



        }







        function getArhCommentMasterFile() {



            if (currentArhDossier) {



                if (currentArhDossier.master_document) return currentArhDossier.master_document;



                if (currentArhDossier.data && currentArhDossier.data.master_document) return currentArhDossier.data.master_document;



                if (currentArhDossier.files && currentArhDossier.files[0]) return currentArhDossier.files[0];



                if (currentArhDossier.data && currentArhDossier.data.files && currentArhDossier.data.files[0]) return currentArhDossier.data.files[0];



            }



            return '';



        }







