        // PRIORITÉ 2 : CHARGEMENT MATRICE PARAMÉTRIQUE & CONCORDANCE TRIPARTITE



        // ══════════════════════════════════════════════════════════════════════════════



        async function loadArhParametricMatrix(dossierId) {



            if (!dossierId) return;



            try {



                const resp = await fetch(`${API_BASE}/api/arh/dossiers/${encodeURIComponent(dossierId)}/parametric-matrix`);



                if (!resp.ok) return;



                const data = await resp.json();







                const badgeStyle = (status) => {



                    if (status === 'CONFORME') return { color: '#27AE60', bg: 'rgba(39,174,96,0.2)' };



                    if (status === 'NON CONFORME') return { color: '#EF4444', bg: 'rgba(239,68,68,0.2)' };



                    return { color: '#F59E0B', bg: 'rgba(245,158,11,0.2)' };



                };







                // 1. Carte Hydrotest (v3.0)



                const hydro = data.hydrotest || data.hydrotest_audit || {};



                const hBadge = document.getElementById('arh-hydro-badge');



                if (hBadge) {



                    const st = hydro.status || (hydro.is_compliant === true ? 'CONFORME' : (hydro.is_compliant === false ? 'NON CONFORME' : 'À VÉRIFIER'));



                    const bs = badgeStyle(st);



                    hBadge.textContent = st;



                    hBadge.style.color = bs.color;



                    hBadge.style.background = bs.bg;



                }



                const hPma = document.getElementById('arh-hydro-pma');



                if (hPma) hPma.textContent = hydro.pma_bar != null ? `${hydro.pma_bar} bar` : 'À vérifier';



                const hReq = document.getElementById('arh-hydro-req');



                if (hReq) hReq.textContent = hydro.legal_minimum_bar != null ? `${hydro.legal_minimum_bar} bar` : 'À vérifier';



                const hVerd = document.getElementById('arh-hydro-verdict');



                if (hVerd) hVerd.textContent = hydro.verdict || 'À vérifier';







                // 2. Carte Rating Brides (v3.0)



                const flange = data.flange || data.flange_audit || {};



                const fBadge = document.getElementById('arh-flange-badge');



                if (fBadge) {



                    const st = flange.status || (flange.is_compliant === true ? 'CONFORME' : (flange.is_compliant === false ? 'NON CONFORME' : 'À VÉRIFIER'));



                    const bs = badgeStyle(st);



                    fBadge.textContent = st;



                    fBadge.style.color = bs.color;



