        function updateArhMirrorTransforms() {



            const c0 = document.getElementById('arh-mirror-canvas-rev0');



            const c1 = document.getElementById('arh-mirror-canvas-rev1');



            const transformStr = `translate(${arhMirrorState.translateX}px, ${arhMirrorState.translateY}px) scale(${arhMirrorState.scale})`;







            if (c0) c0.style.transform = transformStr;



            if (c1) c1.style.transform = transformStr;







            const ind = document.getElementById('arh-mirror-zoom-indicator');



            if (ind) ind.textContent = `Zoom : ${Math.round(arhMirrorState.scale * 100)}%`;



        }







        function toggleArhMirrorSync() {



            arhMirrorState.isSync = !arhMirrorState.isSync;



            const btn = document.getElementById('arh-mirror-sync-btn');



            if (btn) {



                if (arhMirrorState.isSync) {



                    btn.innerHTML = '<i class="ph ph-link"></i> Synchronisation Miroir : ACTIVE';



                    btn.style.color = '#27AE60';



                    btn.style.borderColor = '#27AE60';



                    btn.style.background = 'rgba(39,174,96,0.2)';



                } else {



