                    btn.style.background = 'rgba(230,126,34,0.2)';



                }



            }



        }







        function zoomArhMirror(factor) {



            arhMirrorState.scale = Math.min(Math.max(arhMirrorState.scale * factor, 0.2), 3.5);



            updateArhMirrorTransforms();



        }







        function resetArhMirrorZoom() {



            arhMirrorState.scale = 0.85;



            arhMirrorState.translateX = 0;



            arhMirrorState.translateY = 0;



            updateArhMirrorTransforms();



        }







