        function startArhMirrorPan(e, targetPane) {



            arhMirrorState.isDragging = true;



            arhMirrorState.activePane = targetPane;



            arhMirrorState.startX = e.clientX - arhMirrorState.translateX;



            arhMirrorState.startY = e.clientY - arhMirrorState.translateY;







            const vp = document.getElementById(`arh-mirror-viewport-${targetPane}`);



            if (vp) vp.style.cursor = 'grabbing';







            const onMouseMove = (moveEvt) => {



                if (!arhMirrorState.isDragging) return;



                arhMirrorState.translateX = moveEvt.clientX - arhMirrorState.startX;



                arhMirrorState.translateY = moveEvt.clientY - arhMirrorState.startY;



                updateArhMirrorTransforms();



            };







            const onMouseUp = () => {



                arhMirrorState.isDragging = false;



                if (vp) vp.style.cursor = 'grab';



                window.removeEventListener('mousemove', onMouseMove);



                window.removeEventListener('mouseup', onMouseUp);



            };







            window.addEventListener('mousemove', onMouseMove);



            window.addEventListener('mouseup', onMouseUp);



        }







        function handleArhMirrorWheel(e) {



            e.preventDefault();



            const delta = e.deltaY > 0 ? 0.9 : 1.1;



            zoomArhMirror(delta);



        }







