        function renderArhCompositionAndAdditionalDocs(dossier) {



            if (!dossier) return;







            // 1. En-tête Récapitulatif Officiel & Cartouche



            const stageBadge = document.getElementById('arh-recap-stage-badge');



            if (stageBadge) {



                stageBadge.textContent = dossier.dossier_stage_label || dossier.stage || 'Dossier Préliminaire';



            }







            const dIdEl = document.getElementById('arh-recap-dossier-id');



            if (dIdEl) dIdEl.textContent = `[ID: ${dossier.dossier_id || '-'}]`;







            const titleEl = document.getElementById('arh-recap-title');



            if (titleEl) {



                const tag = dossier.equipment_tag || 'Équipement';



                const desc = dossier.equipment_label || 'Dossier ARH';



                titleEl.textContent = `${tag} — ${desc}`;



            }







            const projEl = document.getElementById('arh-recap-project');



            if (projEl) projEl.textContent = dossier.project_name || '-';







            const unitEl = document.getElementById('arh-recap-unit');



            if (unitEl) unitEl.textContent = dossier.unit_name || '-';







            const eqEl = document.getElementById('arh-recap-eq-label');



            if (eqEl) eqEl.textContent = dossier.equipment_label || dossier.equipment_tag || '-';







            // Décision Réglementaire



            const decEl = document.getElementById('arh-recap-decision');



            const rawDec = dossier.status || dossier.arh_decision || 'REJECTED';



            const decLabel = rawDec === 'APPROVED' ? 'CONFORME (AUTORISÉ)' : rawDec === 'APPROVED_WITH_COMMENTS' ? 'CONFORME AVEC REMARQUES' : 'NON CONFORME (REJETÉ)';



            const decColor = rawDec === 'APPROVED' ? '#27AE60' : rawDec === 'APPROVED_WITH_COMMENTS' ? '#F39C12' : '#E74C3C';



            if (decEl) {



                decEl.textContent = decLabel;



                decEl.style.color = decColor;



            }







            // Score de Conformité



            const scoreEl = document.getElementById('arh-recap-score');



            const score = dossier.compliance_score !== undefined ? dossier.compliance_score : 0;



            if (scoreEl) {



                scoreEl.textContent = `${score.toFixed(1)}%`;



                scoreEl.style.color = score >= 85 ? '#27AE60' : score >= 60 ? '#F39C12' : '#E74C3C';



            }







            // 2. Jauge de Complétude des Pièces de Composition



            const summary = dossier.composition_summary || {};



            const checklist = dossier.mandatory_checklist || [];







            let receivedCount = summary.received_count;



            let totalRequired = summary.total_required;



