                    const ends = pieces.map(p => parseInt(p.page_end, 10)).filter(n => !isNaN(n) && n > 0);



                    const minP = starts.length > 0 ? Math.min(...starts) : 1;



                    const maxP = ends.length > 0 ? Math.max(...ends) : 1;



                    const totalP = pieces.reduce((acc, p) => acc + (parseInt(p.page_count, 10) || 1), 0);



                    const dTotal = (currentArhDossier && (currentArhDossier.total_pages || (currentArhDossier.data && currentArhDossier.data.total_pages))) || data.total_pages || totalP;



                    if (dTotal > 0) {



                        const pct = Math.min(100, Math.round((totalP / dTotal) * 100));



                        covKpi.textContent = `${totalP} / ${dTotal} pages (${pct}%)`;



                    } else {



                        covKpi.textContent = `${totalP} pages (Pages ${minP}-${maxP})`;



                    }



                }



            } catch (err) {



                console.warn('[ARH-SLICER] Erreur chargement pièces découpées:', err);



                if (loader) loader.style.display = 'none';



            }



        }







