        function openArhPieceViewer(encodedFilename, startPage, endPage, title, category, statusLabel, note, snippet, isReserveLocked = false) {



            let filename = decodeURIComponent(encodedFilename || '');



            filename = resolveArhRealFilename(filename);







            // Extraction robuste et insensible au format (ex: 'Page 30 sur 73', 30, '30')



            let targetPage = 1;



            if (startPage !== undefined && startPage !== null) {



                if (typeof startPage === 'number') {



                    targetPage = startPage;



                } else {



                    const m = String(startPage).match(/\d+/);



                    if (m) targetPage = parseInt(m[0], 10);



                }



            }



            if (isNaN(targetPage) || targetPage < 1) targetPage = 1;







            let maxPages = 73;



            if (endPage !== undefined && endPage !== null) {



                if (typeof endPage === 'number') {



                    maxPages = endPage;



                } else {



                    const m = String(endPage).match(/\d+/);



                    if (m) maxPages = parseInt(m[0], 10);



                }



            } else if (currentArhDossier && currentArhDossier.total_pages) {



                maxPages = currentArhDossier.total_pages;



            } else if (currentArhDossier && currentArhDossier.sheet_audit_log && currentArhDossier.sheet_audit_log[0] && currentArhDossier.sheet_audit_log[0].total_pages) {



                maxPages = currentArhDossier.sheet_audit_log[0].total_pages;



            }



            if (isNaN(maxPages) || maxPages < 1) maxPages = 73;



            if (targetPage > maxPages) maxPages = targetPage;







            currentArhViewerDoc.isReserveLocked = Boolean(isReserveLocked);



            currentArhViewerDoc.filename = filename;



            currentArhViewerDoc.currentPage = targetPage;



            currentArhViewerDoc.targetPage = targetPage;



            currentArhViewerDoc.highlightActive = true;



            if (isReserveLocked) {



                currentArhViewerDoc.startPage = targetPage;



                currentArhViewerDoc.endPage = targetPage;



            } else {



                currentArhViewerDoc.startPage = 1;



                currentArhViewerDoc.endPage = maxPages;



            }



            currentArhViewerDoc.zoom = 1.0;



            currentArhViewerDoc.title = title || 'Pièce Documentaire';



            currentArhViewerDoc.category = category || 'Contrôle Réglementaire';



            currentArhViewerDoc.status = statusLabel || 'Remarque Détectée';



            currentArhViewerDoc.note = note || 'Examen requis selon les décrets ARH.';



            currentArhViewerDoc.snippet = snippet || '';







            // Réinitialiser le bouton surlignage sur ON



            const toggleBtn = document.getElementById('arh-viewer-toggle-highlight-btn');



            if (toggleBtn) {



                toggleBtn.style.background = 'rgba(212,163,115,0.18)';



                toggleBtn.style.borderColor = 'var(--accent-primary)';



                toggleBtn.style.color = 'var(--accent-primary)';



                toggleBtn.innerHTML = '<i class="ph ph-highlighter"></i> Surlignage : ON';



            }







            const viewerCard = document.getElementById('arh-doc-viewer-card');



            if (!viewerCard) return;



            viewerCard.style.display = 'flex';



            viewerCard.style.zIndex = '999999';



            document.body.style.overflow = 'hidden';







            // Mettre à jour les informations du volet latéral



            const titleEl = document.getElementById('arh-viewer-piece-title');



            if (titleEl) titleEl.textContent = title || 'Visualisation de la Pièce';







            const fnEl = document.getElementById('arh-viewer-doc-filename');



            if (fnEl) {



                if (currentArhViewerDoc.isReserveLocked) {



                    fnEl.textContent = `${filename} — Page unique verrouillée : ${targetPage}`;



                } else {



                    fnEl.textContent = `${filename} — Page ${targetPage} sur ${maxPages}`;



                }



            }







            const sideTitle = document.getElementById('arh-viewer-side-title');



            if (sideTitle) sideTitle.textContent = title || '-';







            const sideCat = document.getElementById('arh-viewer-side-category');



            if (sideCat) sideCat.textContent = category || '-';







            const sideStatus = document.getElementById('arh-viewer-side-status');



            if (sideStatus) sideStatus.innerHTML = `<span style="font-weight:700; color:var(--accent-primary);">${statusLabel}</span>`;







            const sideNote = document.getElementById('arh-viewer-side-note');



            if (sideNote) sideNote.textContent = note || 'Conforme aux exigences réglementaires ARH.';







            const sideSnip = document.getElementById('arh-viewer-side-snippet');



            if (sideSnip) sideSnip.textContent = snippet || '(Aucun extrait textuel brut détecté sur cette page)';







            // Lien direct de consultation/téléchargement du document source



            const pdfLink = document.getElementById('arh-inline-viewer-pdf-download');



            if (pdfLink && currentArhDossier) {



                const dId = currentArhDossier.dossier_id || (currentArhDossier.data && currentArhDossier.data.dossier_id);



                if (dId) {



                    pdfLink.href = `${API_BASE}/api/arh/dossiers/${encodeURIComponent(dId)}/documents/${encodeURIComponent(filename)}#page=${targetPage}`;



                }



            }







            // Charger l'image haute définition



            renderArhInlineViewerPage();



        }







        function renderArhInlineViewerPage() {



            if (!currentArhDossier) return;



            const dId = currentArhDossier.dossier_id || (currentArhDossier.data && currentArhDossier.data.dossier_id);



            if (!dId) return;







            const indicator = document.getElementById('arh-inline-viewer-page-indicator');



            const navWrapper = indicator ? indicator.parentElement : null;



            if (indicator) {



                if (currentArhViewerDoc.isReserveLocked) {



                    indicator.textContent = `Page ${currentArhViewerDoc.currentPage} (Page unique verrouillée)`;



                } else {



                    indicator.textContent = `Page ${currentArhViewerDoc.currentPage} / ${currentArhViewerDoc.endPage}`;



                }



            }



            if (navWrapper) {



                const prevBtn = navWrapper.querySelector("button[onclick*='-1']");



                const nextBtn = navWrapper.querySelector("button[onclick*='1']");



                if (currentArhViewerDoc.isReserveLocked) {



                    if (prevBtn) prevBtn.style.display = 'none';



                    if (nextBtn) nextBtn.style.display = 'none';



                } else {



                    if (prevBtn) prevBtn.style.display = 'inline-flex';



                    if (nextBtn) nextBtn.style.display = 'inline-flex';



                }



            }







            const fnEl = document.getElementById('arh-viewer-doc-filename');



            if (fnEl) {



                if (currentArhViewerDoc.isReserveLocked) {



                    fnEl.textContent = `${currentArhViewerDoc.filename} — Page unique ciblée sur la réserve : ${currentArhViewerDoc.currentPage}`;



                } else {



                    fnEl.textContent = `${currentArhViewerDoc.filename} — Page ${currentArhViewerDoc.currentPage} sur ${currentArhViewerDoc.endPage}`;



                }



            }







            const img = document.getElementById('arh-inline-viewer-img');



            const loader = document.getElementById('arh-inline-viewer-loader');



            if (!img) return;







            if (loader) {



                loader.style.display = 'block';



                loader.classList.remove('hidden');



                loader.innerHTML = `



                    <div style="width:36px; height:36px; border:3px solid var(--border-color); border-top-color:var(--accent-primary); border-radius:50%; animation:spin 1s linear infinite; margin:0 auto 10px;"></div>



                    <span style="font-size:12px; color:var(--text-secondary);">Rendu haute définition de la page ${currentArhViewerDoc.currentPage}...</span>



                `;



            }



            img.style.display = 'none';



            img.style.transform = `scale(${currentArhViewerDoc.zoom})`;







            const fname = resolveArhRealFilename(currentArhViewerDoc.filename) || (currentArhDossier.files && currentArhDossier.files[0]) || '';







            // Construire les paramètres de surlignage ciblé uniquement pour la réserve active



            const qParams = [];



            if (currentArhViewerDoc.highlightActive && currentArhViewerDoc.currentPage === currentArhViewerDoc.targetPage) {



                if (currentArhViewerDoc.snippet) {



                    qParams.push(`q=${encodeURIComponent(currentArhViewerDoc.snippet)}`);



                }



                if (currentArhViewerDoc.title) {



                    qParams.push(`title=${encodeURIComponent(currentArhViewerDoc.title)}`);



                }



            } else {



                qParams.push('highlight=false');



            }



            const qStr = qParams.length > 0 ? `&${qParams.join('&')}` : '';



            const imgUrl = `${API_BASE}/api/arh/dossiers/${encodeURIComponent(dId)}/pages/${encodeURIComponent(fname)}/${currentArhViewerDoc.currentPage}.png?t=${Date.now()}${qStr}`;







            const newImg = new Image();



            newImg.onload = () => {



                img.src = imgUrl;



                img.style.display = 'block';



                if (loader) {



                    loader.style.display = 'none';



                    loader.classList.add('hidden');



                }



            };



            newImg.onerror = () => {



                console.warn("Échec rendu annoté, tentative avec page vierge:", imgUrl);



                // Si la requête annotée échoue, repli automatique sur la page vierge non surlignée



                if (qParams.length > 0) {



                    const fallbackUrl = `${API_BASE}/api/arh/dossiers/${encodeURIComponent(dId)}/pages/${encodeURIComponent(fname)}/${currentArhViewerDoc.currentPage}.png?highlight=false&t=${Date.now()}`;



                    const fbImg = new Image();



                    fbImg.onload = () => {



                        img.src = fallbackUrl;



                        img.style.display = 'block';



                        if (loader) {



                            loader.style.display = 'none';



                            loader.classList.add('hidden');



                        }



                    };



                    fbImg.onerror = () => {



                        showErrorState();



                    };



                    fbImg.src = fallbackUrl;



                } else {



                    showErrorState();



                }



            };







            function showErrorState() {



                if (loader) {



                    loader.innerHTML = `



                        <div style="padding:24px; text-align:center;">



                            <i class="ph ph-warning-circle" style="font-size:36px; color:#E74C3C; display:block; margin-bottom:8px;"></i>



                            <span style="color:#E74C3C; font-size:13px; font-weight:700;">Impossible de générer le rendu de la page ${currentArhViewerDoc.currentPage}.</span>



                            <div style="font-size:11px; color:var(--text-secondary); margin-top:4px;">Document source : ${escapeHtml(fname)}</div>



                            <div style="margin-top:14px; display:flex; gap:10px; justify-content:center;">



                                <button onclick="renderArhInlineViewerPage()" style="padding:6px 14px; background:rgba(255,255,255,0.08); border:1px solid var(--border-color); color:var(--text-primary); border-radius:6px; font-size:11.5px; cursor:pointer; font-weight:600;">



                                    <i class="ph ph-arrow-clockwise"></i> Réessayer



                                </button>



                                <a href="${API_BASE}/api/arh/dossiers/${encodeURIComponent(dId)}/documents/${encodeURIComponent(fname)}#page=${currentArhViewerDoc.currentPage}" target="_blank" style="padding:6px 14px; background:rgba(99,102,241,0.25); border:1px solid rgba(99,102,241,0.5); color:#C7D2FE; border-radius:6px; font-size:11.5px; text-decoration:none; display:inline-flex; align-items:center; gap:5px; font-weight:700;">



                                    <i class="ph ph-file-pdf"></i> Ouvrir le PDF brut (Page ${currentArhViewerDoc.currentPage})



                                </a>



                            </div>



                        </div>



                    `;



                }



