        function escapeJs(str) {



            if (!str) return '';



            return String(str).replace(/\\/g, '\\\\').replace(/'/g, "\\'").replace(/"/g, '&quot;').replace(/\n/g, ' ').replace(/\r/g, '');



        }







        function escapeHtml(str) {



            if (!str) return '';



            return String(str).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');



        }











        function exportArhCommentsToExcel() {



            if (!currentArhDossier || !currentArhDossier.comments) {



                showToast("Aucune fiche de remarque à exporter.", "warning");



                return;



