            let csv = "\uFEFF" + "N°;Sévérité;Catégorie;Référence Décret;Article;Observation / Non-Conformité;Action de Correction;Délai (Jours);Responsable\n";







            currentArhDossier.comments.forEach((c, idx) => {



                const obs = (c.observation || '').replace(/;/g, ',').replace(/\n/g, ' ');



                const act = (c.action_required || '').replace(/;/g, ',').replace(/\n/g, ' ');



                csv += `${idx+1};${c.severity};${c.category};${c.decree_reference};${c.article_number};${obs};${act};${c.deadline_days};${c.responsible_entity}\n`;



            });







            const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });



            const url = URL.createObjectURL(blob);



            const a = document.createElement('a');



            a.href = url;



            a.download = `fiches_remarques_arh_${currentArhDossier.equipment_tag || 'dossier'}.csv`;



            document.body.appendChild(a);



            a.click();



            document.body.removeChild(a);



            showToast("Export Excel des fiches de remarques ARH réussi !", "success");



