        let pidCurrentScale = 1;







        function pidInitPanZoom() {



            const container = document.getElementById('pid-canvas-container');



            if (!container) return;



            const svg = container.querySelector('svg');



            if (!svg) return;







            // Read the initial viewBox



            const vb = svg.getAttribute('viewBox');



            if (vb) {



                const parts = vb.split(/[\s,]+/).map(Number);



                pidViewBox = { x: parts[0], y: parts[1], w: parts[2], h: parts[3] };



                pidOriginalViewBox = { ...pidViewBox };



            }



            pidCurrentScale = 1;



            updatePidZoomLabel();







            // Mouse wheel zoom



            container.addEventListener('wheel', function(e) {



                e.preventDefault();



                const factor = e.deltaY < 0 ? 0.9 : 1.1;



                pidApplyZoom(factor, e);



            }, { passive: false });







            // Pan: mousedown



            container.addEventListener('mousedown', function(e) {



                if (e.button !== 0) return;



                pidIsPanning = true;



                pidPanStart = { x: e.clientX, y: e.clientY };



                container.style.cursor = 'grabbing';



            });







            // Pan: mousemove



            container.addEventListener('mousemove', function(e) {



                if (!pidIsPanning) return;



                const svg = container.querySelector('svg');



                if (!svg) return;



                const dx = e.clientX - pidPanStart.x;



                const dy = e.clientY - pidPanStart.y;



                const containerRect = container.getBoundingClientRect();



                const scaleX = pidViewBox.w / containerRect.width;



                const scaleY = pidViewBox.h / containerRect.height;



                pidViewBox.x -= dx * scaleX;



                pidViewBox.y -= dy * scaleY;



                svg.setAttribute('viewBox', `${pidViewBox.x} ${pidViewBox.y} ${pidViewBox.w} ${pidViewBox.h}`);



                pidPanStart = { x: e.clientX, y: e.clientY };



            });







            // Pan: mouseup



            window.addEventListener('mouseup', function() {



                if (pidIsPanning) {



                    pidIsPanning = false;



                    container.style.cursor = 'grab';



                }



            });



        }







        function pidApplyZoom(factor, evt) {



            const container = document.getElementById('pid-canvas-container');



            const svg = container ? container.querySelector('svg') : null;



            if (!svg) return;







            const newScale = pidCurrentScale * (1 / factor);



            if (newScale < 0.1 || newScale > 20) return;







            // Zoom towards mouse position



            if (evt) {



                const containerRect = container.getBoundingClientRect();



                const mx = (evt.clientX - containerRect.left) / containerRect.width;



                const my = (evt.clientY - containerRect.top) / containerRect.height;



                const newW = pidViewBox.w * factor;



                const newH = pidViewBox.h * factor;



                pidViewBox.x += (pidViewBox.w - newW) * mx;



                pidViewBox.y += (pidViewBox.h - newH) * my;



                pidViewBox.w = newW;



                pidViewBox.h = newH;



            } else {



                // Center zoom



                const cx = pidViewBox.x + pidViewBox.w / 2;



                const cy = pidViewBox.y + pidViewBox.h / 2;



                pidViewBox.w *= factor;



                pidViewBox.h *= factor;



                pidViewBox.x = cx - pidViewBox.w / 2;



                pidViewBox.y = cy - pidViewBox.h / 2;



            }







            pidCurrentScale = newScale;



            svg.setAttribute('viewBox', `${pidViewBox.x} ${pidViewBox.y} ${pidViewBox.w} ${pidViewBox.h}`);



            updatePidZoomLabel();



        }







        function pidZoom(factor) {



            pidApplyZoom(1 / factor, null);



        }







