        function focusOnPidElement(tag, x0, y0, x1, y1) {



            const container = document.getElementById('pid-canvas-container');



            const svg = container ? container.querySelector('svg') : null;



            if (!svg) return;







            // Map AutoCAD model coordinates to ezdxf SVG viewBox coordinate space



            let targetX0 = x0;



            let targetY0 = y0;



            let targetX1 = x1;



            let targetY1 = y1;







            const meta = window.currentSvgMetadata;



            if (meta && meta.transform) {



                // Use the exact transformation matrix calculated by ezdxf backend for perfect precision!



                const { sx, sy, tx, ty } = meta.transform;



                const mapX = (x) => x * sx + tx;



                const mapY = (y) => y * sy + ty;







                const sx0 = mapX(x0);



                const sy0 = mapY(y0);



                const sx1 = mapX(x1);



                const sy1 = mapY(y1);







                targetX0 = Math.min(sx0, sx1);



                targetY0 = Math.min(sy0, sy1);



                targetX1 = Math.max(sx0, sx1);



                targetY1 = Math.max(sy0, sy1);



            } else if (meta && meta.viewbox && meta.model_extents) {



                const vbParts = meta.viewbox.split(/[\s,]+/).map(Number);



                if (vbParts.length === 4) {



                    const [vx, vy, vw, vh] = vbParts;



                    const ext = meta.model_extents;



                    const dx = ext.max_x - ext.min_x;



                    const dy = ext.max_y - ext.min_y;



                    if (dx > 0 && dy > 0) {



                        // Linear mapping function:



                        // AutoCAD Y values increase upwards; ezdxf SVG viewBox Y values increase downwards.



                        const mapX = (x) => vx + ((x - ext.min_x) / dx) * vw;



                        const mapY = (y) => vy + vh - ((y - ext.min_y) / dy) * vh;







                        const sx0 = mapX(x0);



                        const sy0 = mapY(y0);



                        const sx1 = mapX(x1);



                        const sy1 = mapY(y1);







                        targetX0 = Math.min(sx0, sx1);



                        targetY0 = Math.min(sy0, sy1);



                        targetX1 = Math.max(sx0, sx1);



                        targetY1 = Math.max(sy0, sy1);



                    }



                }



            }







            const cx = (targetX0 + targetX1) / 2;



            const cy = (targetY0 + targetY1) / 2;







            // Focus and zoom in around the target center



            const bboxW = Math.abs(targetX1 - targetX0);



            const bboxH = Math.abs(targetY1 - targetY0);



            const targetW = Math.max(bboxW * 1.8, pidOriginalViewBox.w / 3.2);



            const targetH = Math.max(bboxH * 1.8, pidOriginalViewBox.h / 3.2);







            pidViewBox.w = targetW;



            pidViewBox.h = targetH;



            pidViewBox.x = cx - targetW / 2;



            pidViewBox.y = cy - targetH / 2;







            pidCurrentScale = Math.round((pidOriginalViewBox.w / targetW) * 10) / 10;







            svg.setAttribute('viewBox', `${pidViewBox.x} ${pidViewBox.y} ${pidViewBox.w} ${pidViewBox.h}`);



            updatePidZoomLabel();







            // Render glowing rounded pulsing rectangle highlight dynamically on top of the drawing



            // Skip giant purple rectangle box if focusing on a line (to avoid purple overlay clutter)



            const isLine = tag && (tag.includes('-') || tag.startsWith('Ligne'));



            if (!isLine) {



                const existingHighlight = svg.getElementById('pid-focus-highlight');



                if (existingHighlight) existingHighlight.remove();







                const highlight = document.createElementNS("http://www.w3.org/2000/svg", "g");



                highlight.id = 'pid-focus-highlight';







                const rect = document.createElementNS("http://www.w3.org/2000/svg", "rect");



                // Add a padding margin around the coordinate box so it's clearly visible



                const boxW = Math.max(targetX1 - targetX0, 100);



                const boxH = Math.max(targetY1 - targetY0, 100);



                rect.setAttribute('x', (cx - boxW / 2).toString());



                rect.setAttribute('y', (cy - boxH / 2).toString());



                rect.setAttribute('width', boxW.toString());



                rect.setAttribute('height', boxH.toString());



                rect.setAttribute('fill', 'rgba(168, 85, 247, 0.15)');



                rect.setAttribute('stroke', '#A855F7');



                rect.setAttribute('stroke-width', '6');



                rect.setAttribute('rx', '15');



                rect.setAttribute('stroke-dasharray', '15,8');







                // Add dynamic CSS pulse animation to the highlight element



                const animate = document.createElementNS("http://www.w3.org/2000/svg", "animate");



                animate.setAttribute('attributeName', 'stroke-width');



                animate.setAttribute('values', '6;16;6');



                animate.setAttribute('dur', '1.5s');



                animate.setAttribute('repeatCount', 'indefinite');



                rect.appendChild(animate);







                highlight.appendChild(rect);



                svg.appendChild(highlight);



            }







            // Show toast message confirmation



            showToast(`${tag} localisé avec succès sur le plan vectoriel.`, 'success', 'Localisation');







            // Graceful fade out and removal of the highlight overlay after 6 seconds



            setTimeout(() => {



                const hl = svg.getElementById('pid-focus-highlight');



                if (hl) {



                    hl.style.transition = 'opacity 1s';



                    hl.style.opacity = '0';



                    setTimeout(() => { if (hl) hl.remove(); }, 1000);



                }



            }, 6000);



        }







