        // Map AutoCAD coordinates to ezdxf SVG viewBox coordinate space (A1/A2 helper)



        function mapAutoCadToSvgCoords(x, y) {



            const meta = window.currentSvgMetadata;



            if (meta && meta.transform) {



                const { sx, sy, tx, ty } = meta.transform;



                return { x: x * sx + tx, y: y * sy + ty };



            }







            let viewBoxStr = meta ? meta.viewbox : null;



            let ext = meta ? meta.model_extents : null;







            const canvasContainer = document.getElementById('pid-canvas-container');



            const svgEl = canvasContainer ? canvasContainer.querySelector('svg') : null;



            if (svgEl && !viewBoxStr) {



                viewBoxStr = svgEl.getAttribute('viewBox');



            }







            if (viewBoxStr) {



                const vbParts = viewBoxStr.split(/[\s,]+/).map(Number);



                if (vbParts.length === 4) {



                    const [vx, vy, vw, vh] = vbParts;



                    let min_x = ext ? ext.min_x : 0.0;



                    let max_x = ext ? ext.max_x : (vw > 10000 ? 1000.0 : vw);



                    let min_y = ext ? ext.min_y : 0.0;



                    let max_y = ext ? ext.max_y : (vh > 10000 ? 588.51 : vh);







                    const dx = max_x - min_x;



                    const dy = max_y - min_y;



                    if (dx > 0 && dy > 0) {



                        return {



                            x: vx + ((x - min_x) / dx) * vw,



                            y: vy + vh - ((y - min_y) / dy) * vh



                        };



                    }



                }



            }



            return { x: x, y: y }; // Fallback raw coords



        }







