            // Auto create overlay SVG if no native SVG canvas present



            if (!svgEl) {



                svgEl = document.createElementNS('http://www.w3.org/2000/svg', 'svg');



                svgEl.setAttribute('id', 'pid-overlay-svg');



                svgEl.style.position = 'absolute';



                svgEl.style.top = '0';



                svgEl.style.left = '0';



                svgEl.style.width = '100%';



                svgEl.style.height = '100%';



                svgEl.style.pointerEvents = 'none';



                canvasContainer.appendChild(svgEl);



            }







            // Compute unitScale from SVG viewBox (e.g., 1000000 viewBox -> unitScale = 1000)



            let unitScale = 1.0;



            let viewBoxStr = svgEl.getAttribute('viewBox');



            if (!viewBoxStr && window.currentSvgMetadata) viewBoxStr = window.currentSvgMetadata.viewbox;



            if (viewBoxStr) {



                const vbParts = viewBoxStr.split(/[\s,]+/).map(Number);



                if (vbParts.length === 4 && vbParts[2] > 0) {



                    unitScale = vbParts[2] / 1000.0;



                }



            }







            const color = '#FFD700'; // Luminous Neon Gold / Yellow for high contrast



            const pathCoords = item.path_coords || [];







            // 1. Draw sleek, high-visibility line path highlights (crisp 15px stroke)



            pathCoords.forEach(seg => {



                const x0 = Array.isArray(seg) ? seg[0] : (seg.x0 || seg[0]);



                const y0 = Array.isArray(seg) ? seg[1] : (seg.y0 || seg[1]);



                const x1 = Array.isArray(seg) ? seg[2] : (seg.x1 || seg[2]);



                const y1 = Array.isArray(seg) ? seg[3] : (seg.y1 || seg[3]);







                const p1 = mapAutoCadToSvgCoords(x0, y0);



                const p2 = mapAutoCadToSvgCoords(x1, y1);







                const line = document.createElementNS('http://www.w3.org/2000/svg', 'line');



                line.setAttribute('x1', p1.x);



                line.setAttribute('y1', p1.y);



                line.setAttribute('x2', p2.x);



                line.setAttribute('y2', p2.y);



                line.setAttribute('stroke', color);



                line.setAttribute('stroke-width', (1.8 * unitScale).toString());



                line.setAttribute('stroke-opacity', '0.95');



                line.setAttribute('stroke-linecap', 'round');



                line.classList.add('ll-svg-highlight');



                line.innerHTML = `<animate attributeName="stroke-opacity" values="0.95;0.50;0.95" dur="1.1s" repeatCount="indefinite"/>`;



                svgEl.appendChild(line);



            });







            // 2. Collect connected equipment & valve tags in strict sequential order (Amont -> Inline -> Aval)



            const connectedTags = [];



            if (item.from_equipment && item.from_equipment !== 'OPEN') {



                connectedTags.push({ tag: item.from_equipment.trim(), role: 'Amont (Source)' });



            }







            const rawInlineComps = item.line_components || item.valves || [];



            rawInlineComps.forEach(compObj => {



                const cTag = typeof compObj === 'object' ? compObj.tag : compObj;



                if (cTag && !connectedTags.some(t => t.tag === cTag.trim())) {



                    connectedTags.push({ tag: cTag.trim(), role: 'Composant Ligne' });



                }



            });







            if (item.to_equipment && item.to_equipment !== 'OPEN' && !connectedTags.some(t => t.tag === item.to_equipment.trim())) {



                connectedTags.push({ tag: item.to_equipment.trim(), role: 'Aval (Puits)' });



            }







            // Update Agent Active Badge



            const agentBadge = document.getElementById('ll-agent-active-badge');



            if (agentBadge) {



                agentBadge.innerHTML = `Ligne Active : <strong style="color:#FFD700;">${item.line_number || 'Ligne #' + (lineIndex+1)}</strong> | ${connectedTags.length} élément(s) [Amont ➔ Aval]`;



            }







            // 3. Highlight connected equipment & valves on SVG canvas with proportional badges



            const components = window.currentPidComponents || [];



            connectedTags.forEach((itemObj, stepIdx) => {



                const tag = itemObj.tag;



                let svgPt = null;



                let foundInSvgDom = false;







                // Priority 1: Search SVG DOM for exact text tag using getBBox()



                const textEls = svgEl.querySelectorAll('text, tspan');



                for (let txtEl of textEls) {



                    const txtVal = (txtEl.textContent || '').trim().toUpperCase();



                    if (txtVal === tag.toUpperCase() || (tag.length >= 5 && txtVal.includes(tag.toUpperCase()))) {



                        try {



                            const bbox = txtEl.getBBox();



                            if (bbox && bbox.width > 0) {



                                svgPt = { x: bbox.x + bbox.width / 2, y: bbox.y + bbox.height / 2 };



                                foundInSvgDom = true;



                                break;



                            }



                        } catch (e) {}



                    }



                }







                // Priority 2: Fallback to CAD component coordinates mapped to SVG



                if (!foundInSvgDom) {



                    let comp = components.find(c => c.tag && c.tag.trim().toUpperCase() === tag.toUpperCase());



                    if (comp) {



                        svgPt = mapAutoCadToSvgCoords(comp.x, comp.y);



                    }



                }







                if (svgPt) {



                    const stepNum = stepIdx + 1;



                    const isAmont = itemObj.role.includes('Amont');



                    const isAval = itemObj.role.includes('Aval');



                    const badgeColor = isAmont ? '#10B981' : isAval ? '#EF4444' : '#00F0FF';







                    // Outer Pulsing Glow Ring



                    const circle = document.createElementNS('http://www.w3.org/2000/svg', 'circle');



                    circle.setAttribute('cx', svgPt.x);



                    circle.setAttribute('cy', svgPt.y);



                    circle.setAttribute('r', (8.0 * unitScale).toString());



                    circle.setAttribute('fill', isAmont ? 'rgba(16,185,129,0.35)' : isAval ? 'rgba(239,68,68,0.35)' : 'rgba(0, 240, 255, 0.35)');



                    circle.setAttribute('stroke', badgeColor);



                    circle.setAttribute('stroke-width', (1.2 * unitScale).toString());



                    circle.classList.add('ll-equipment-highlight');



                    circle.innerHTML = `<animate attributeName="r" values="${6.5*unitScale};${9.5*unitScale};${6.5*unitScale}" dur="1.4s" repeatCount="indefinite"/><animate attributeName="stroke-opacity" values="1;0.4;1" dur="1.4s" repeatCount="indefinite"/>`;



                    svgEl.appendChild(circle);







                    // Floating Tag Badge & Step Order Index



                    const g = document.createElementNS('http://www.w3.org/2000/svg', 'g');



                    g.classList.add('ll-eq-badge');







                    const bw = 24.0 * unitScale;



                    const bh = 7.0 * unitScale;







                    const rect = document.createElementNS('http://www.w3.org/2000/svg', 'rect');



                    rect.setAttribute('x', (svgPt.x - bw / 2).toString());



                    rect.setAttribute('y', (svgPt.y - 12.0 * unitScale).toString());



                    rect.setAttribute('width', bw.toString());



                    rect.setAttribute('height', bh.toString());



                    rect.setAttribute('rx', (1.5 * unitScale).toString());



                    rect.setAttribute('fill', '#0F172A');



                    rect.setAttribute('stroke', badgeColor);



                    rect.setAttribute('stroke-width', (0.8 * unitScale).toString());







                    // Step number circle badge



                    const stepCircle = document.createElementNS('http://www.w3.org/2000/svg', 'circle');



                    stepCircle.setAttribute('cx', (svgPt.x - bw / 2 + 3.5 * unitScale).toString());



                    stepCircle.setAttribute('cy', (svgPt.y - 8.5 * unitScale).toString());



                    stepCircle.setAttribute('r', (2.2 * unitScale).toString());



                    stepCircle.setAttribute('fill', '#F59E0B');







                    const stepText = document.createElementNS('http://www.w3.org/2000/svg', 'text');



                    stepText.setAttribute('x', (svgPt.x - bw / 2 + 3.5 * unitScale).toString());



                    stepText.setAttribute('y', (svgPt.y - 7.5 * unitScale).toString());



                    stepText.setAttribute('fill', '#0F172A');



                    stepText.setAttribute('font-size', (2.8 * unitScale).toString());



                    stepText.setAttribute('font-weight', 'bold');



                    stepText.setAttribute('text-anchor', 'middle');



                    stepText.textContent = stepNum;







                    const text = document.createElementNS('http://www.w3.org/2000/svg', 'text');



                    text.setAttribute('x', (svgPt.x + 2.0 * unitScale).toString());



                    text.setAttribute('y', (svgPt.y - 7.5 * unitScale).toString());



                    text.setAttribute('fill', '#FFFFFF');



                    text.setAttribute('font-size', (3.2 * unitScale).toString());



                    text.setAttribute('font-weight', 'bold');



                    text.setAttribute('text-anchor', 'middle');



                    text.setAttribute('font-family', 'monospace');



                    text.textContent = tag.length > 13 ? tag.substring(0, 12) + '…' : tag;







                    g.appendChild(rect);



                    g.appendChild(stepCircle);



                    g.appendChild(stepText);



                    g.appendChild(text);



                    svgEl.appendChild(g);



                }



            });







            // 4. Auto focus viewport on selected line & equipment



            let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;



            pathCoords.forEach(seg => {



                const x0 = Array.isArray(seg) ? seg[0] : (seg.x0 || seg[0]);



                const y0 = Array.isArray(seg) ? seg[1] : (seg.y0 || seg[1]);



                const x1 = Array.isArray(seg) ? seg[2] : (seg.x1 || seg[2]);



                const y1 = Array.isArray(seg) ? seg[3] : (seg.y1 || seg[3]);







                minX = Math.min(minX, x0, x1);



                maxX = Math.max(maxX, x0, x1);



                minY = Math.min(minY, y0, y1);



                maxY = Math.max(maxY, y0, y1);



            });



            if (minX !== Infinity) {



                focusOnPidElement(item.line_number, minX, minY, maxX, maxY);



            }



        }







        // Render colored pipes for all lines on SVG (A2)



        function renderAllPipeColorsOnSvg() {



            // Remove previous pipe overlays



            document.querySelectorAll('.ll-svg-pipe-overlay').forEach(el => el.remove());







