function makeLineListCellEditable(td, lineIndex, field) {



            if (td.querySelector('input')) return; // Already editing



            const currentText = td.textContent.trim();



            const input = document.createElement('input');



            input.type = 'text';



            input.value = currentText;



            input.style.cssText = 'background:rgba(255,255,255,0.1); border:1px solid var(--accent-primary); border-radius:3px; color:var(--text-primary); font-size:11px; padding:2px 4px; width:100%; outline:none; font-family:monospace;';







            const save = () => {



                const newVal = input.value.trim();



                if (newVal !== currentText) {



                    pushLineListUndoState();



                    window.currentPidLines[lineIndex][field] = newVal;



                    renderPidLinesTable(window.currentPidLines);



                    showToast(`Champ "${field}" mis à jour.`, "success", "Édition");



                } else {



                    td.textContent = currentText;



                }



            };







            input.onblur = save;



            input.onkeydown = (e) => {



                if (e.key === 'Enter') { e.preventDefault(); save(); }



                if (e.key === 'Escape') { td.textContent = currentText; }



            };







            td.textContent = '';



            td.appendChild(input);



            input.focus();



            input.select();



        }







