            window.currentPidLines.sort((a, b) => {



                let va = field === '_index' ? 0 : (a[field] || '');



                let vb = field === '_index' ? 0 : (b[field] || '');



                if (field === 'confidence_score') {



                    va = parseFloat(va) || 0;



                    vb = parseFloat(vb) || 0;



                    return lineListSortAsc ? va - vb : vb - va;



                }



                va = String(va).toLowerCase();



                vb = String(vb).toLowerCase();



                return lineListSortAsc ? va.localeCompare(vb) : vb.localeCompare(va);



            });







            renderPidLinesTable(window.currentPidLines);



        }







        // Print view (E6)



        function printLineList() {



            const lines = window.currentPidLines;



            if (!lines || lines.length === 0) {



