                .footer { margin-top:15px; font-size:9px; color:#999; text-align:right; }



                @media print { body { margin:0; } }



            </style></head><body>



            <h1>📋 Line List - ${window.currentPidFilename || 'P&ID'}</h1>



            <p style="font-size:11px; color:#666;">Généré le ${new Date().toLocaleString('fr-FR')} - ${lines.length} lignes détectées</p>



            <table>



                <thead><tr>



