                </tr></thead><tbody>`;







            lines.forEach((item, idx) => {



                const conf = Math.round((item.confidence_score || 0.5) * 100);



                const dn = item.size_dn || DN_CONVERSION[item.size] || '';



                const desc = item.fluid_description || FLUID_SERVICE_DESC[item.fluid] || '';



                const isDead = item.is_dead_leg || ((item.from_equipment === 'OPEN') !== (item.to_equipment === 'OPEN'));



                const alerts = [];



                if (isDead) alerts.push('Dead-leg');



                if (item.has_branch) alerts.push('Branch');



                if (!item.fluid) alerts.push('Fluide?');







                html += `<tr class="${isDead ? 'deadleg' : ''}">



                    <td>${idx + 1}</td>



                    <td><b>${item.line_number || '-'}</b></td>



                    <td>${item.size || '-'}"</td>



