function switchPidRightPanelTab(tab) {



    const btnTable = document.getElementById('tab-pid-table');



    const btnLines = document.getElementById('tab-pid-lines');



    const btnAi = document.getElementById('tab-pid-ai');







    const panelTable = document.getElementById('pid-panel-table');



