    const panelAi = document.getElementById('pid-panel-ai');







    if (panelTable) { panelTable.classList.add('hidden'); panelTable.style.display = 'none'; }



    if (panelLines) { panelLines.classList.add('hidden'); panelLines.style.display = 'none'; }



    if (panelAi) { panelAi.classList.add('hidden'); panelAi.style.display = 'none'; }







    // 2. Reset tab button active states



    if (btnTable) { btnTable.style.borderBottomColor = 'transparent'; btnTable.style.color = 'var(--text-secondary)'; }



    if (btnLines) { btnLines.style.borderBottomColor = 'transparent'; btnLines.style.color = 'var(--text-secondary)'; }



    if (btnAi) { btnAi.style.borderBottomColor = 'transparent'; btnAi.style.color = 'var(--text-secondary)'; }







    // 3. Activate selected panel



    if (tab === 'table') {



        if (btnTable) { btnTable.style.borderBottomColor = 'var(--accent-primary)'; btnTable.style.color = '#FFF'; }



        if (panelTable) { panelTable.classList.remove('hidden'); panelTable.style.display = 'flex'; }



    } else if (tab === 'lines') {



        if (btnLines) { btnLines.style.borderBottomColor = 'var(--accent-primary)'; btnLines.style.color = '#FFF'; }



        if (panelLines) { 



            panelLines.classList.remove('hidden'); 



            panelLines.style.display = 'flex'; 



            if (typeof renderPidLinesTable === 'function') {



                renderPidLinesTable(window.currentPidLines && window.currentPidLines.length > 0 ? window.currentPidLines : defaultDemoLines);



            }



