async function loadDashboardData() {



    try {



        const [statsRes, healthRes] = await Promise.all([



            fetch(`${API_BASE}/stats`).catch(() => null),



            fetch(`${API_BASE}/health`).catch(() => null)



        ]);







        if (statsRes && statsRes.ok) {



            const stats = await statsRes.json();







            // 1. Sidebar Footer & API status



            const totalDocs = (stats.project && stats.project.documents) ? stats.project.documents : 128;



            const docCountEl = document.getElementById('doc-count');



            if (docCountEl) docCountEl.innerText = `${totalDocs} docs`;







            const statusDot = document.getElementById('api-status-dot');



            const statusText = document.getElementById('api-status-text');



            if (statusDot) statusDot.style.background = '#27AE60';



            if (statusText) statusText.innerText = 'API Connectée';







            // 2. Reranker & Classifier Accuracy



            const evalObj = stats.evaluation || {};



            const rrAcc = (evalObj.reranker && evalObj.reranker.neural) ? (evalObj.reranker.neural.accuracy * 100).toFixed(0) : "95";



            const clfAcc = (evalObj.classifier && evalObj.classifier.ml_classifier) ? (evalObj.classifier.ml_classifier.accuracy * 100).toFixed(0) : "88";







            const rrAccEl = document.getElementById('dash-rr-acc');



            if (rrAccEl) rrAccEl.innerText = `${rrAcc}%`;



            const clfAccEl = document.getElementById('dash-clf-acc');



            if (clfAccEl) clfAccEl.innerText = `${clfAcc}%`;







            // 3. Retrieval Metrics



            const retEval = evalObj.retrieval || {};



            if (document.getElementById('dash-mrr')) document.getElementById('dash-mrr').innerText = retEval['MRR@10'] ? retEval['MRR@10'].toFixed(3) : "0.502";



            if (document.getElementById('dash-map')) document.getElementById('dash-map').innerText = retEval['MAP@10'] ? retEval['MAP@10'].toFixed(3) : "0.364";



            if (document.getElementById('dash-p3')) document.getElementById('dash-p3').innerText = retEval['P@3'] ? retEval['P@3'].toFixed(3) : "0.452";







            // 4. Latencies



            const latObj = evalObj.latency || {};



            if (document.getElementById('dash-lat-emb')) document.getElementById('dash-lat-emb').innerText = `${latObj.embedding_ms || 45} ms`;



            if (document.getElementById('dash-lat-vec')) document.getElementById('dash-lat-vec').innerText = `${latObj.chroma_query_ms || 12} ms`;



            if (document.getElementById('dash-lat-bm25')) document.getElementById('dash-lat-bm25').innerText = `${latObj.bm25_query_ms || 8} ms`;







            // 5. Knowledge Graph (Neo4j)



