            const neoDetails = stats.neo4j_details || {};



            if (document.getElementById('dash-neo4j-total')) document.getElementById('dash-neo4j-total').innerText = neoTotal.toLocaleString();



            if (document.getElementById('dash-neo4j-eq')) document.getElementById('dash-neo4j-eq').innerText = (neoDetails.Equipement || 390).toLocaleString();



            if (document.getElementById('dash-neo4j-norm')) document.getElementById('dash-neo4j-norm').innerText = (neoDetails.Norme || 4213).toLocaleString();



            if (document.getElementById('dash-neo4j-doc')) document.getElementById('dash-neo4j-doc').innerText = (neoDetails.Document || 804).toLocaleString();







            // 6. Base de connaissances & ChromaDB



            const indexedChunks = stats.chromadb_documents || 9266;



            const totalDataFiles = (stats.project && stats.project.documents) ? stats.project.documents : 128;



            if (document.getElementById('dash-docs-total')) document.getElementById('dash-docs-total').innerText = totalDataFiles;



            if (document.getElementById('dash-docs-indexed')) document.getElementById('dash-docs-indexed').innerText = `${totalDataFiles} dossiers (${indexedChunks.toLocaleString()} chunks vectorisés)`;



