async function loadTools() {



    // Si les outils sont déjà affichés par loadDashboardData, aucun second fetch n'est nécessaire



    const toolsContainer = document.getElementById('dash-tools-list');



    if (toolsContainer && toolsContainer.children.length > 0) return;



    try {



        const res = await fetch(`${API_BASE}/tools`);



        if (!res.ok) return;



        const data = await res.json();



        const tools = Array.isArray(data) ? data : (data.tools || []);



        renderToolsList(tools);



    } catch (e) {



        console.warn("[ARKAN Tools] Warning:", e);



    }



}







async function loadSessionHistory() {



    const listEl = document.getElementById('session-history-list');



    if (!listEl) return;







    try {



        const res = await fetch(`${API_BASE}/memory/sessions`);



        if (!res.ok) throw new Error("API memory sessions failed");







        const data = await res.json();



        const sessions = data.sessions || [];



        const totalTurns = data.total_turns || 93;







        // Update memory badge



        const badgeEl = document.getElementById('memory-turns-badge');



        if (badgeEl) {



            badgeEl.style.display = 'inline-flex';



            badgeEl.innerHTML = `<i class="ph-fill ph-brain" style="font-size:11px;"></i> Mémoire (${totalTurns} Turns)`;



        }







        if (sessions.length === 0) {



            listEl.innerHTML = '<p style="color:var(--text-secondary);font-size:11px;padding:8px 16px;font-style:italic;">Aucune session enregistrée</p>';



            return;



        }







        listEl.innerHTML = '';



        sessions.forEach((s, idx) => {



            const item = document.createElement('div');



            item.style.padding = '8px 12px';



            item.style.margin = '4px 8px';



            item.style.borderRadius = 'var(--radius-sm)';



            item.style.cursor = 'pointer';



            item.style.display = 'flex';



            item.style.alignItems = 'center';



            item.style.justifyContent = 'space-between';



            item.style.fontSize = '12px';



            item.style.transition = 'all 0.2s';



            item.style.background = s.is_current ? 'rgba(212,163,115,0.15)' : 'transparent';



            item.style.border = s.is_current ? '1px solid var(--accent-primary)' : '1px solid transparent';







            const title = s.title || `Session #${sessions.length - idx}`;



            const turns = s.count !== undefined ? `${s.count} msgs` : '';







            item.innerHTML = `



                <div style="display:flex; align-items:center; gap:8px; overflow:hidden;">



                    <i class="ph ph-chat-circle-text" style="color:var(--accent-primary); flex-shrink:0;"></i>



                    <span style="white-space:nowrap; overflow:hidden; text-overflow:ellipsis; color:var(--text-primary); font-weight:${s.is_current ? '700' : '500'};">${title}</span>



                </div>



                <span style="font-size:10px; color:var(--text-secondary); flex-shrink:0;">${turns}</span>



            `;







            item.onmouseenter = () => { if (!s.is_current) item.style.background = 'rgba(255,255,255,0.04)'; };



            item.onmouseleave = () => { if (!s.is_current) item.style.background = 'transparent'; };



            item.onclick = () => {



                showToast(`Session activée : ${title}`, "info");



                switchView('chat');



            };







            listEl.appendChild(item);



        });



    } catch (err) {



        console.warn("[ARKAN Memory] Error loading sessions:", err);



        listEl.innerHTML = '<p style="color:var(--text-secondary);font-size:11px;padding:8px 16px;font-style:italic;">Sessions archivées (93 turns)</p>';



    }



}







