// CHAT CORE - sendMessage / handleEnter / autoResize



// Ces fonctions ont été perdues et restaurées ici.



// ─────────────────────────────────────────────────────────────────────────────







function autoResize(textarea) {



    textarea.style.height = 'auto';



    textarea.style.height = Math.min(textarea.scrollHeight, 200) + 'px';



}







function handleEnter(event) {



    // Shift+Enter = saut de ligne, Enter seul = envoyer



    if (event.key === 'Enter' && !event.shiftKey) {



        event.preventDefault();



        sendMessage();



    }



}







async function sendMessage() {



    const inputEl  = document.getElementById('user-input');



    const btnSend  = document.getElementById('btn-send');



    const chatBox  = document.getElementById('chat-messages');







    if (!inputEl || !chatBox) return;







    const question = inputEl.value.trim();



    if (!question || isProcessing) return;







    // ── Afficher le message utilisateur ──────────────────────────────────────



    const userMsgEl = document.createElement('div');



    userMsgEl.className = 'message user';



    userMsgEl.innerHTML = `



        <div class="avatar"><i class="ph ph-user"></i></div>



        <div class="message-content"><p style="margin:0;">${question.replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/\n/g,'<br>')}</p></div>



    `;



    chatBox.appendChild(userMsgEl);







    // ── Vider et désactiver l'input ───────────────────────────────────────────



    inputEl.value = '';



    autoResize(inputEl);



    isProcessing = true;



    if (btnSend) { btnSend.disabled = true; }







    // ── Bulle de chargement ───────────────────────────────────────────────────



    const loadingEl = document.createElement('div');



    loadingEl.className = 'message assistant';



    loadingEl.id = 'chat-loading-bubble';



    loadingEl.innerHTML = `



        <div class="avatar"><i class="ph ph-sparkles"></i></div>



        <div class="message-content">



            <div style="display:flex;align-items:center;gap:8px;color:var(--text-secondary);font-size:13px;">



                <span class="loader-dots"><span></span><span></span><span></span></span>



                ARKAN analyse votre question…



            </div>



        </div>



    `;



    chatBox.appendChild(loadingEl);



    chatBox.scrollTop = chatBox.scrollHeight;







    try {



        const payload = {



            question: question,



            session_id: currentSessionId || null,



            use_agents: true



        };







        const headers = { 'Content-Type': 'application/json' };



        if (API_KEY) headers['X-API-Key'] = API_KEY;







        const response = await fetch(`${API_BASE}/question`, {



            method: 'POST',



            headers: headers,



            body: JSON.stringify(payload)



        });







        // Retirer la bulle de chargement



        const bubble = document.getElementById('chat-loading-bubble');



        if (bubble) bubble.remove();







        if (!response.ok) {



            const errText = await response.text().catch(() => response.statusText);



            throw new Error(`Erreur serveur ${response.status}: ${errText}`);



        }







        const data = await response.json();







        // Mettre à jour la session si le serveur en renvoie une



        if (data.session_id) currentSessionId = data.session_id;







        // ── Formater les sources ──────────────────────────────────────────────



        let sourcesHtml = '';



        if (data.sources && data.sources.length > 0) {



            const uniqueSources = [...new Map(data.sources.map(s => [s.file || s.filename || s.source, s])).values()];



            sourcesHtml = `



                <div style="margin-top:10px;padding-top:8px;border-top:1px solid var(--border-color);font-size:11px;color:var(--text-secondary);">



                    <span style="font-weight:600;"><i class="ph ph-files"></i> Sources :</span>



                    ${uniqueSources.slice(0,5).map(s => {



                        const name = (s.file || s.filename || s.source || 'Document').split(/[\\/]/).pop();



                        return `<span style="display:inline-block;background:rgba(212,163,115,0.12);border:1px solid rgba(212,163,115,0.3);border-radius:4px;padding:2px 6px;margin:2px 2px 0 0;">${name}</span>`;



                    }).join('')}



                </div>`;



        }







        // ── Confidence badge ──────────────────────────────────────────────────



        const conf = data.confidence || 0;



        const confColor = conf >= 0.75 ? '#27AE60' : conf >= 0.5 ? '#F59E0B' : '#E74C3C';



        const confLabel = data.confidence_level || (conf >= 0.75 ? 'Élevée' : conf >= 0.5 ? 'Moyenne' : 'Faible');



        const confBadge = `<span style="font-size:10px;background:${confColor}22;color:${confColor};border:1px solid ${confColor}44;border-radius:10px;padding:1px 7px;margin-left:6px;font-weight:600;">Confiance ${confLabel}</span>`;







        // ── Afficher la réponse ───────────────────────────────────────────────



        const answerText = (data.answer || 'Aucune réponse générée.')



            .replace(/</g,'&lt;').replace(/>/g,'&gt;')



            .replace(/\*\*(.+?)\*\*/g,'<strong>$1</strong>')



            .replace(/\*(.+?)\*/g,'<em>$1</em>')



            .replace(/\n/g,'<br>');







        const assistantEl = document.createElement('div');



        assistantEl.className = 'message assistant';



        assistantEl.innerHTML = `



            <div class="avatar"><i class="ph ph-sparkles"></i></div>



            <div class="message-content">



                <div style="font-weight:700;margin-bottom:4px;color:var(--accent-primary);font-size:12px;">



                    ARKAN - RAG &amp; Graphe de Connaissances ${confBadge}



                </div>



                <p style="margin:0;line-height:1.6;">${answerText}</p>



                ${sourcesHtml}



            </div>



        `;



        chatBox.appendChild(assistantEl);







    } catch (err) {



        const bubble = document.getElementById('chat-loading-bubble');



        if (bubble) bubble.remove();







        const errEl = document.createElement('div');



        errEl.className = 'message assistant';



        errEl.innerHTML = `



            <div class="avatar" style="background:rgba(231,76,60,0.15);"><i class="ph ph-warning-circle" style="color:#E74C3C;"></i></div>



            <div class="message-content">



                <div style="font-weight:700;color:#E74C3C;margin-bottom:4px;">Erreur de connexion</div>



                <p style="margin:0;font-size:12px;color:var(--text-secondary);">



                    Impossible de joindre le serveur ARKAN.<br>



                    <code style="font-size:11px;opacity:0.7;">${err.message}</code>



                </p>



            </div>



        `;



        chatBox.appendChild(errEl);



    } finally {



        isProcessing = false;



        if (btnSend) { btnSend.disabled = false; }



        chatBox.scrollTop = chatBox.scrollHeight;



        inputEl.focus();



    }



}







// ── Exposition globale obligatoire pour les onclick inline dans Electron ──────



// Dans Electron/Chromium, les fonctions définies dans un script séparé



// ne sont PAS automatiquement sur window si le script est exécuté en mode



// module ou dans un contexte isolé. On force l'exposition explicitement.



window.sendMessage  = sendMessage;



window.handleEnter  = handleEnter;



window.autoResize   = autoResize;







