function _normalizeBackendContractToState(dbCtr) {



    const itemsRaw = Array.isArray(dbCtr.items) ? dbCtr.items : [];



    const mappedItems = itemsRaw.map((it, idx) => {



        const ordered = parseFloat(it.quantite_contractuelle ?? it.ordered ?? 1) || 1;



        const received = parseFloat(it.quantite_livree ?? it.received ?? 0) || 0;



        const issued = parseFloat(it.quantite_sortie ?? it.issued ?? 0) || 0;



        const returned = parseFloat(it.quantite_reintegree ?? it.returned ?? 0) || 0;



        const pu = parseFloat(it.prix_unitaire ?? it.unitPrice ?? 0) || 0;



        const unite = it.unite || it.unit || "U";



        const delai = it.delai_livraison || dbCtr.delai_livraison || "";



        return {



            dbId: it.id || "",



            code: it.reference || it.code || `EQ-${String(idx + 1).padStart(2, '0')}`,



            name: it.designation || it.name || "Article sans désignation",



            unite: unite,



            ordered: ordered,



            unitPrice: pu,



            totalPrice: Math.round(ordered * pu * 100) / 100,



            delai: delai,



            received: received,



            issued: issued,



            returned: returned,



            netOnSite: Math.max(0, received - issued + returned),



            remaining: Math.max(0, ordered - received)



        };



    });







    const totalOrdered = mappedItems.reduce((s, i) => s + i.ordered, 0);



    const totalReceived = mappedItems.reduce((s, i) => s + i.received, 0);



    const pct = totalOrdered > 0 ? Math.min(100, Math.round((totalReceived / totalOrdered) * 100)) : 0;



    const computedBpu = mappedItems.reduce((s, i) => s + (i.ordered * i.unitPrice), 0);



    const montant = parseFloat(dbCtr.montant || dbCtr.computed_montant || computedBpu || 0) || computedBpu;







    return {



        dbId: dbCtr.id || "",



        project_id: dbCtr.project_id || "general",



        project_name: dbCtr.project_name || dbCtr.projet || "Projet Général / Non classé",



        id: dbCtr.numero_contrat || dbCtr.id || "CTR-N/A",



        supplier: dbCtr.fournisseur || dbCtr.supplier || "Fournisseur non spécifié",



        objet: dbCtr.objet || "",



        delai_livraison: dbCtr.delai_livraison || (mappedItems[0]?.delai || ""),



        date_signature: dbCtr.date_signature || "",



        date_fin_prevue: dbCtr.date_fin_prevue || "",



        montant: montant,



        devise: dbCtr.devise || "DZD",



        document_path: dbCtr.document_path || "",



        pct: pct,



        status: pct === 100 && totalOrdered > 0 ? "ACTIF (100% Livré)" : `ACTIF (${pct}% Livré)`,



        items: mappedItems



    };



}







