async function attachContractPdf(contractDbId, inputEl) {



    const file = inputEl?.files?.[0];



    if (!file || !contractDbId) return;



    inputEl.value = '';



    showToast(`Envoi du PDF "${file.name}" en cours...`, 'info');



    try {



        const formData = new FormData();



        formData.append('file', file);



        formData.append('project_id', 'general');



        formData.append('auto_insert', 'false'); // extract only, don't create new contract







        const res = await fetch(`${API_BASE}/procurement/contracts/import-pdf`, {



            method: 'POST',



            body: formData



        });



        const data = await res.json();



        if (!res.ok) throw new Error(data.detail || 'Erreur lors du téléversement du PDF');







        const docPath = data.extracted?.document_path || '';



        if (!docPath) throw new Error('Chemin PDF non retourné par le serveur');







        // Patch document_path on existing contract



        const patchRes = await fetch(`${API_BASE}/procurement/contracts/${encodeURIComponent(contractDbId)}/document-path`, {



            method: 'PUT',



            headers: { 'Content-Type': 'application/json' },



            body: JSON.stringify({ document_path: docPath })



        });



        if (!patchRes.ok) {



            const patchData = await patchRes.json().catch(() => ({}));



            throw new Error(patchData.detail || 'Impossible de lier le PDF au contrat');



        }







        showToast(`✅ PDF "${file.name}" lié au contrat avec succès !`, 'success');



        await loadProcurementData();



        renderProcurementCascadeView();



    } catch (err) {



        console.error('[attachContractPdf]', err);



        showToast(`Erreur : ${err.message}`, 'error');



    }



}



window.attachContractPdf = attachContractPdf;







function populateProcurementFilterCascades() {



    const contracts = ARKAN_STATE.procurementContracts || [];



    const projectsMap = new Map();







    projectsMap.set("general", { id: "general", name: "Projet Général / Non classé", count: 0 });



    (ARKAN_STATE.procurementProjects || []).forEach(p => {



        projectsMap.set(p.id, { id: p.id, name: p.name, count: 0 });



    });



    contracts.forEach(c => {



        const pid = c.project_id || "general";



        const pname = c.project_name || (pid === "general" ? "Projet Général / Non classé" : pid);



        if (!projectsMap.has(pid)) {



            projectsMap.set(pid, { id: pid, name: pname, count: 0 });



        }



        projectsMap.get(pid).count++;



    });







    const projectsList = Array.from(projectsMap.values());







    // 1. Header Global Project Select & Modal Project Selects



    const globalSel = document.getElementById("proc-global-project-select");



    if (globalSel) {



        const curGlobal = globalSel.value || "general";



        globalSel.innerHTML =



            `<option value="ALL">🌐 Tous les Projets (${projectsList.length})</option>` +



            projectsList.map(p => `<option value="${escapeHtml(p.id)}">📁 ${escapeHtml(p.name)} (${p.count})</option>`).join('') +



            `<option value="__new__">➕ Créer un nouveau projet...</option>`;



        if (curGlobal === "ALL" || projectsList.some(p => p.id === curGlobal)) globalSel.value = curGlobal;



    }







    ["nx-contract-project", "proc-contract-project"].forEach(selId => {



        const el = document.getElementById(selId);



        if (el) {



            const curVal = el.value || (globalSel?.value && globalSel.value !== "ALL" ? globalSel.value : "general");



            el.innerHTML =



                projectsList.map(p => `<option value="${escapeHtml(p.id)}">📁 ${escapeHtml(p.name)}</option>`).join('') +



                `<option value="__new__">➕ Créer un nouveau projet...</option>`;



            if (projectsList.some(p => p.id === curVal)) el.value = curVal;



        }



    });







    // 2. Filter Project Select (Contracts Tab)



    const filterProj = document.getElementById("proc-filter-project-select");



    const rawSelectedProj = filterProj ? filterProj.value : "";



    const selectedProj = (rawSelectedProj === "ALL" || rawSelectedProj === "__new__") ? "" : rawSelectedProj;



    if (filterProj) {



        filterProj.innerHTML = `<option value="">📁 Tous les projets (${projectsList.length})</option>` +



            projectsList.map(p => `<option value="${escapeHtml(p.id)}">📁 ${escapeHtml(p.name)} (${p.count} contrat${p.count > 1 ? 's' : ''})</option>`).join('') +



            `<option value="__new__">➕ Créer un nouveau projet...</option>`;



        filterProj.value = projectsList.some(p => p.id === selectedProj) ? selectedProj : "";



    }







    // 3. Filter Contract Select (Cascaded from selected Project)



    const filterCtr = document.getElementById("proc-filter-contract-select");



    const rawSelectedCtr = filterCtr ? filterCtr.value : "";



    const selectedCtr = rawSelectedCtr === "ALL" ? "" : rawSelectedCtr;



    const contractsForProj = selectedProj



        ? contracts.filter(c => (c.project_id || "general") === selectedProj)



        : contracts;







    if (filterCtr) {



        filterCtr.innerHTML = `<option value="">📄 Tous les contrats (${contractsForProj.length})</option>` +



            contractsForProj.map(c => `<option value="${escapeHtml(c.id)}">${escapeHtml(c.id)} — ${escapeHtml(c.supplier)} (${(c.items || []).length} art.)</option>`).join('');



        filterCtr.value = contractsForProj.some(c => c.id === selectedCtr) ? selectedCtr : "";



    }







    // 4. Filter Item Select (Cascaded from selected Contract or Project)



    const filterItem = document.getElementById("proc-filter-item-select");



    const rawSelectedItem = filterItem ? filterItem.value : "";



    const selectedItem = rawSelectedItem === "ALL" ? "" : rawSelectedItem;



    const activeCtrVal = filterCtr ? filterCtr.value : "";



    const contractsForItems = activeCtrVal



        ? contractsForProj.filter(c => c.id === activeCtrVal)



        : contractsForProj;







    const allItems = [];



    contractsForItems.forEach(c => {



        (c.items || []).forEach(it => {



            allItems.push({



                key: `${c.id}::${it.code}`,



                code: it.code,



                name: it.name,



                contractId: c.id,



                ordered: it.ordered,



                unite: it.unite || "U"



            });



        });



    });







    if (filterItem) {



        filterItem.innerHTML = `<option value="">⚙️ Tous les articles (${allItems.length})</option>` +



            allItems.map(it => `<option value="${escapeHtml(it.key)}">[${escapeHtml(it.contractId)}] ${escapeHtml(it.code)} — ${escapeHtml((it.name || '').substring(0, 65))} (${it.ordered} ${escapeHtml(it.unite)})</option>`).join('');



        filterItem.value = allItems.some(i => i.key === selectedItem) ? selectedItem : "";



    }







    // 5. Stock Inventory Project & Contract Filters



    const stockProj = document.getElementById("proc-stock-project-filter");



    if (stockProj) {



        const curSp = (stockProj.value === "ALL" ? "" : stockProj.value) || "";



        stockProj.innerHTML = `<option value="">Tous les projets (${projectsList.length})</option>` +



            projectsList.map(p => `<option value="${escapeHtml(p.id)}">${escapeHtml(p.name)} (${p.count})</option>`).join('');



        stockProj.value = curSp;



    }



    const stockCtr = document.getElementById("proc-stock-contract-filter");



    if (stockCtr) {



        const curSc = (stockCtr.value === "ALL" ? "" : stockCtr.value) || "";



        const spVal = stockProj ? stockProj.value : "";



        const stockContracts = spVal ? contracts.filter(c => (c.project_id || "general") === spVal) : contracts;



        stockCtr.innerHTML = `<option value="">Tous les contrats (${stockContracts.length})</option>` +



            stockContracts.map(c => `<option value="${escapeHtml(c.id)}">${escapeHtml(c.id)} — ${escapeHtml(c.supplier)}</option>`).join('');



        stockCtr.value = stockContracts.some(c => c.id === curSc) ? curSc : "";



    }



}







