function renderProcurementDashboard() {



    const contracts = ARKAN_STATE.procurementContracts || [];



    const totalContracts = contracts.length;







    let totalOrdered = 0;



    let totalReceived = 0;



    let totalIssued = 0;



    let totalReturned = 0;



    let totalItemsCount = 0;



    let computedValue = 0;



    let mainCurrency = "DZD";







    const byProject = new Map();







    contracts.forEach(c => {



        if (c.devise) mainCurrency = c.devise;



        const cItems = Array.isArray(c.items) ? c.items : [];



        totalItemsCount += cItems.length;



        let cBpu = 0;



        let cOrd = 0;



        let cRec = 0;



        cItems.forEach(i => {



            const ord = parseFloat(i.ordered) || 0;



            const rec = parseFloat(i.received) || 0;



            const iss = parseFloat(i.issued) || 0;



            const ret = parseFloat(i.returned) || 0;



            const pu = parseFloat(i.unitPrice) || 0;



            totalOrdered += ord;



            totalReceived += rec;



            totalIssued += iss;



            totalReturned += ret;



            cOrd += ord;



            cRec += rec;



            cBpu += ord * pu;



        });



        const cVal = (parseFloat(c.montant) > 0 ? parseFloat(c.montant) : cBpu);



        computedValue += cVal;







        const pid = c.project_id || "general";



        const pname = c.project_name || "Projet Général / Non classé";



        if (!byProject.has(pid)) {



            byProject.set(pid, { id: pid, name: pname, contractsCount: 0, itemsCount: 0, totalVal: 0, devise: c.devise || "DZD", ord: 0, rec: 0 });



        }



        const pStat = byProject.get(pid);



        pStat.contractsCount += 1;



        pStat.itemsCount += cItems.length;



        pStat.totalVal += cVal;



        pStat.ord += cOrd;



        pStat.rec += cRec;



    });







    const complianceRate = totalOrdered > 0 ? Math.round((totalReceived / totalOrdered) * 100) : 0;



    const totalAvailable = Math.max(0, totalReceived - totalIssued + totalReturned);







    const kpiProjects = document.getElementById("proc-kpi-projects");



    if (kpiProjects) kpiProjects.innerText = Math.max(byProject.size, (ARKAN_STATE.procurementProjects || []).length, 1);







    const kpiContracts = document.getElementById("proc-kpi-contracts");



    if (kpiContracts) kpiContracts.innerText = totalContracts;







    const kpiItems = document.getElementById("proc-kpi-items");



    if (kpiItems) kpiItems.innerText = totalItemsCount.toLocaleString('fr-FR');







    const kpiValue = document.getElementById("proc-kpi-value");



    if (kpiValue) kpiValue.innerText = computedValue.toLocaleString('fr-FR', { minimumFractionDigits: 2, maximumFractionDigits: 2 }) + " " + mainCurrency;







    const kpiCompliance = document.getElementById("proc-kpi-compliance");



    if (kpiCompliance) kpiCompliance.innerText = complianceRate + "%";







    const stockReceived = document.getElementById("proc-stock-received");



    if (stockReceived) stockReceived.innerText = totalReceived.toLocaleString('fr-FR') + " u";







    const stockIssued = document.getElementById("proc-stock-issued");



    if (stockIssued) stockIssued.innerText = totalIssued.toLocaleString('fr-FR') + " u";







    const stockAvailable = document.getElementById("proc-stock-available");



    if (stockAvailable) stockAvailable.innerText = totalAvailable.toLocaleString('fr-FR') + " u";







    // Synthèse par Projet dans le Dashboard



    const projSummaryEl = document.getElementById("proc-dashboard-projects-summary");



    if (projSummaryEl) {



        if (byProject.size === 0) {



            projSummaryEl.innerHTML = `<div style="color:var(--text-secondary); font-size:13px;">Aucun contrat importé pour le moment.</div>`;



        } else {



            projSummaryEl.innerHTML = Array.from(byProject.values()).map(p => {



                const pct = p.ord > 0 ? Math.min(100, Math.round((p.rec / p.ord) * 100)) : 0;



                return `



                <div style="display:flex; justify-content:space-between; align-items:center; padding:12px 14px; background:var(--bg-app); border:1px solid var(--border-color); border-radius:8px; cursor:pointer;"



                     onclick="document.getElementById('proc-filter-project-select').value='${escapeHtml(p.id)}'; switchProcurementTab('contracts'); onProcurementProjectFilterChange();">



                    <div>



                        <div style="font-size:13px; font-weight:700; color:var(--text-primary); display:flex; align-items:center; gap:6px;">



                            <i class="ph ph-folders" style="color:#8B5CF6;"></i> ${escapeHtml(p.name)}



                        </div>



                        <div style="font-size:11px; color:var(--text-secondary); margin-top:3px;">



                            <strong>${p.contractsCount}</strong> contrat(s) &bull; <strong>${p.itemsCount}</strong> article(s) BPU/DQE



                        </div>



                    </div>



                    <div style="text-align:right;">



                        <div style="font-size:13px; font-weight:700; color:#10B981; font-family:monospace;">



                            ${p.totalVal.toLocaleString('fr-FR', { minimumFractionDigits: 2, maximumFractionDigits: 2 })} ${escapeHtml(p.devise)}



                        </div>



                        <div style="font-size:11px; color:${pct === 100 ? '#27AE60' : 'var(--accent-primary)'}; font-weight:600;">



                            Livraison : ${pct}%



                        </div>



                    </div>



                </div>`;



            }).join('');



        }



    }



}







