async function deleteContract(contractId) {



    if (!confirm(`Êtes-vous sûr de vouloir supprimer le contrat ${contractId} ?`)) return;



    const ctr = ARKAN_STATE.procurementContracts.find(c => c.id === contractId);



    if (ctr && ctr.dbId) {



        try {



            await fetch(`${API_BASE}/procurement/contracts/${encodeURIComponent(ctr.dbId)}`, { method: 'DELETE' });



        } catch (err) {



            console.warn("[Procurement] Erreur suppression SQLite:", err);



        }



    }



    ARKAN_STATE.procurementContracts = ARKAN_STATE.procurementContracts.filter(c => c.id !== contractId);



    populateProcurementFilterCascades();



    renderContracts();



    populateProcurementContractSelects();



    renderProcurementDashboard();



    renderStockBalance();



    showToast(`Contrat ${contractId} supprimé !`, "success");



}







async function deleteArticle(contractId, itemCode) {



    if (!confirm(`Êtes-vous sûr de vouloir supprimer l'article ${itemCode} ?`)) return;



    const contract = ARKAN_STATE.procurementContracts.find(c => c.id === contractId);



    if (contract) {



        const targetItem = contract.items.find(i => i.code === itemCode);



        if (targetItem && targetItem.dbId) {



            try {



                await fetch(`${API_BASE}/procurement/items/${encodeURIComponent(targetItem.dbId)}`, { method: 'DELETE' });



            } catch (err) {



                console.warn("[Procurement] Erreur suppression article SQLite:", err);



            }



        }



        contract.items = contract.items.filter(i => i.code !== itemCode);



        if (contract.items.length > 0) {



            const totalOrdered = contract.items.reduce((sum, i) => sum + i.ordered, 0);



            const totalReceived = contract.items.reduce((sum, i) => sum + i.received, 0);



            const percent = Math.min(100, Math.round((totalReceived / totalOrdered) * 100));



            contract.pct = percent;



            contract.status = percent === 100 ? "ACTIF (100% Livré)" : `ACTIF (${percent}% Livré)`;



        } else {



            contract.pct = 0;



            contract.status = "ACTIF (0% Livré)";



        }



        populateProcurementFilterCascades();



        renderContracts();



        renderProcurementDashboard();



        renderStockBalance();



        showToast(`Article ${itemCode} supprimé !`, "success");



    }



}







function renderContracts() {



    const rawProj = document.getElementById("proc-filter-project-select")?.value || "";



    const selectedProj = (rawProj === "ALL" || rawProj === "__new__") ? "" : rawProj;



    const rawCtr = document.getElementById("proc-filter-contract-select")?.value || "";



    const selectedCtr = rawCtr === "ALL" ? "" : rawCtr;



    const rawItem = document.getElementById("proc-filter-item-select")?.value || "";



    const selectedItemKey = rawItem === "ALL" ? "" : rawItem;



    const rawStatus = (document.getElementById("proc-filter-status-select")?.value || "").toLowerCase();



    const selectedStatus = rawStatus === "all" ? "" : rawStatus;



    const searchVal = (document.getElementById("proc-search-contracts")?.value || "").trim().toLowerCase();







    const filtered = (ARKAN_STATE.procurementContracts || []).filter(ctr => {



        if (selectedProj && (ctr.project_id || "general") !== selectedProj) return false;



        if (selectedCtr && ctr.id !== selectedCtr) return false;



        if (selectedItemKey) {



            const [itemCtrId] = selectedItemKey.split("::");



            if (ctr.id !== itemCtrId) return false;



        }



        if (selectedStatus) {



            const pct = ctr.pct ?? 0;



            if ((selectedStatus === "complet" || selectedStatus === "complete") && pct < 100) return false;



            if ((selectedStatus === "partiel" || selectedStatus === "partial") && (pct <= 0 || pct >= 100)) return false;



            if ((selectedStatus === "attente" || selectedStatus === "pending") && pct > 0) return false;



        }



        if (searchVal) {



            const matchCtr = (ctr.id || "").toLowerCase().includes(searchVal) ||



                             (ctr.supplier || "").toLowerCase().includes(searchVal) ||



                             (ctr.objet || "").toLowerCase().includes(searchVal) ||



                             (ctr.project_name || "").toLowerCase().includes(searchVal) ||



                             (ctr.delai_livraison || "").toLowerCase().includes(searchVal);



            const matchItems = (ctr.items || []).some(item =>



                (item.name || "").toLowerCase().includes(searchVal) ||



                (item.code || "").toLowerCase().includes(searchVal)



            );



            if (!matchCtr && !matchItems) return false;



        }



        return true;



    });



    renderProcurementContracts(filtered);



}



window.renderContracts = renderContracts;







