async function submitContract() {



    const num = (document.getElementById("proc-contract-num")?.value || "").trim();



    const supplier = (document.getElementById("proc-contract-supplier")?.value || "").trim();



    const objet = (document.getElementById("proc-contract-subject")?.value || "").trim() || `Contrat ${num}`;



    const delai = (document.getElementById("proc-contract-delivery")?.value || "").trim();



    const montant = parseFloat(document.getElementById("proc-contract-amount")?.value || "0") || 0;



    const devise = document.getElementById("proc-contract-currency")?.value || "DZD";



    const dateSig = document.getElementById("proc-contract-date-sig")?.value || "";



    const dateStart = document.getElementById("proc-contract-date-start")?.value || "";



    const dateEnd = document.getElementById("proc-contract-date-end")?.value || "";



    const statut = document.getElementById("proc-contract-status")?.value || "signé";



    const modalProjVal = document.getElementById("proc-contract-project")?.value;



    const globalProjVal = document.getElementById("proc-global-project-select")?.value;



    const activeProjectId = (modalProjVal && modalProjVal !== "__new__" && modalProjVal !== "ALL")



        ? modalProjVal



        : ((globalProjVal && globalProjVal !== "__new__" && globalProjVal !== "ALL") ? globalProjVal : "general");







    if (!num || !supplier) {



        showToast("Veuillez remplir le numéro de contrat et le nom du fournisseur", "error");



        return;



    }







    try {



        const res = await fetch(`${API_BASE}/procurement/contracts`, {



            method: 'POST',



            headers: { 'Content-Type': 'application/json' },



            body: JSON.stringify({



                project_id: activeProjectId,



                numero_contrat: num,



                fournisseur: supplier,



                objet: objet,



                delai_livraison: delai,



                date_signature: dateSig,



                date_debut: dateStart,



                date_fin_prevue: dateEnd,



                montant: montant,



                devise: devise,



                statut: statut



            })



        });



        if (res.ok) {



            await loadProcurementData();



            closeContractModal();



            showToast(`Contrat ${num} (${supplier}) enregistré en base avec succès !`, "success");



            return;



        }



    } catch (e) {



        console.warn("[Procurement] Fallback local pour submitContract:", e);



    }







    ARKAN_STATE.procurementContracts.unshift({



        project_id: activeProjectId,



        project_name: "Projet Général / Non classé",



        id: num,



        supplier: supplier,



        objet: objet,



        delai_livraison: delai,



        montant: montant,



        devise: devise,



        date_signature: dateSig,



        pct: 0,



        status: "ACTIF (0% Livré)",



        items: []



    });







    populateProcurementFilterCascades();



    renderContracts();



    populateProcurementContractSelects();



    closeContractModal();



    renderProcurementDashboard();



    renderStockBalance();



    showToast(`Contrat ${num} créé avec succès !`, "success");



}







