function recomputeNuExtractBpuTotals() {



    const tbody = document.getElementById("nx-bpu-tbody");



    if (!tbody) return;



    const rows = tbody.querySelectorAll("tr");



    let sum = 0;



    let validCount = 0;



    rows.forEach(r => {



        const qtyInput = r.querySelector(".nx-row-qty");



        const puInput = r.querySelector(".nx-row-pu");



        const totInput = r.querySelector(".nx-row-total");



        if (!qtyInput || !puInput || !totInput) return;



        validCount++;



        const q = parseFloat(qtyInput.value) || 0;



        const p = parseFloat(puInput.value) || 0;



        const t = Math.round(q * p * 100) / 100;



        totInput.value = t;



        sum += t;



    });



    const countBadge = document.getElementById("nx-items-count-badge");



    if (countBadge) countBadge.textContent = String(validCount);



    const devise = document.getElementById("nx-contract-devise")?.value || "DZD";



    const footer = document.getElementById("nx-bpu-summary-footer");



    if (footer) {



        footer.innerHTML = `Total calculé du Bordereau : <strong style="color:#10B981;">${sum.toLocaleString('fr-FR', { minimumFractionDigits: 2, maximumFractionDigits: 2 })} ${escapeHtml(devise)}</strong>`;



    }



    const montantInput = document.getElementById("nx-contract-montant");



    if (montantInput && sum > 0) {



        montantInput.value = Math.round(sum * 100) / 100;



    }



}







async function saveNuExtractContractToDb() {



    const numero_contrat = (document.getElementById("nx-contract-num")?.value || "").trim();



    const fournisseur = (document.getElementById("nx-contract-supplier")?.value || "").trim();



    const delai_livraison = (document.getElementById("nx-contract-delai")?.value || "").trim();



    const date_signature = (document.getElementById("nx-contract-date-sig")?.value || "").trim();



    const objet = (document.getElementById("nx-contract-objet")?.value || "").trim() || `Contrat ${numero_contrat}`;



    const montant = parseFloat(document.getElementById("nx-contract-montant")?.value || "0") || 0;



    const devise = document.getElementById("nx-contract-devise")?.value || "DZD";



    const document_path = document.getElementById("nx-contract-doc-path")?.value || "";



    const project_id = document.getElementById("nx-contract-project")?.value || document.getElementById("proc-global-project-select")?.value || "general";







    if (!numero_contrat || !fournisseur) {



        showToast("Le numéro de contrat et le nom du fournisseur sont obligatoires.", "error");



        return;



    }







    const items = [];



    const rows = document.querySelectorAll("#nx-bpu-tbody tr");



    rows.forEach((r, idx) => {



        const desig = (r.querySelector(".nx-row-desig")?.value || "").trim();



        if (!desig) return;



        const ref = (r.querySelector(".nx-row-ref")?.value || "").trim() || `EQ-${String(idx + 1).padStart(2, '0')}`;



        const unite = (r.querySelector(".nx-row-unite")?.value || "U").trim() || "U";



        const qty = parseFloat(r.querySelector(".nx-row-qty")?.value || "1") || 1;



        const pu = parseFloat(r.querySelector(".nx-row-pu")?.value || "0") || 0;



        const delai = (r.querySelector(".nx-row-delai")?.value || delai_livraison || "").trim();



        items.push({



            reference: ref,



            designation: desig,



            unite: unite,



            quantite_contractuelle: qty,



            prix_unitaire: pu,



            delai_livraison: delai



        });



    });







    try {



        const res = await fetch(`${API_BASE}/procurement/contracts/import-json`, {



            method: "POST",



            headers: { "Content-Type": "application/json" },



            body: JSON.stringify({



                numero_contrat,



                fournisseur,



                objet,



                delai_livraison,



                date_signature,



                montant,



                devise,



                document_path,



                project_id,



                items



            })



        });



        const data = await res.json();



        if (!res.ok) {



            throw new Error(data.detail || "Erreur lors de l'enregistrement du contrat");



        }



        await loadProcurementData();



        closeNuExtractContractModal();



        switchProcurementTab("contracts");



        showToast(`Contrat ${numero_contrat} (${fournisseur}) inséré avec ${items.length} équipement(s) !`, "success");



    } catch (err) {



        console.error("[saveNuExtractContractToDb]", err);



        showToast(`Erreur d'insertion : ${err.message}`, "error");



    }



}







