async function loadProcurementData() {



    // 1. Synchroniser la liste des Projets Procurement depuis SQLite (/procurement/projects)



    try {



        const resProj = await fetch(`${API_BASE}/procurement/projects`);



        if (resProj.ok) {



            const dbProjects = await resProj.json();



            if (Array.isArray(dbProjects)) {



                ARKAN_STATE.procurementProjects = dbProjects;



            }



        }



    } catch (err) {



        console.warn("[Procurement] Impossible de charger /procurement/projects:", err);



    }







    // 2. Synchroniser les contrats et équipements depuis la base SQLite (/procurement/contracts)



    try {



        const res = await fetch(`${API_BASE}/procurement/contracts`);



        if (res.ok) {



            const dbContracts = await res.json();



            if (Array.isArray(dbContracts)) {



                const mapped = dbContracts.map(_normalizeBackendContractToState);



                ARKAN_STATE.procurementContracts = mapped;



                window.procurementContracts = mapped;



            }



        }



    } catch (err) {



        console.warn("[Procurement] Mode hors-ligne / mémoire locale:", err);



    }







    // 3. Populate cascading project -> contract -> item selects



    populateProcurementFilterCascades();







    // 4. Populate project select inputs in Movements tab



    const projectsList = (ARKAN_STATE.procurementProjects && ARKAN_STATE.procurementProjects.length > 0)



        ? ARKAN_STATE.procurementProjects



        : [{ id: "general", name: "Projet Général / Non classé" }];



    const projectOptions = projectsList.map(p => `<option value="${escapeHtml(p.id)}">${escapeHtml(p.name)}</option>`).join('');







    ["receipt", "issue", "return"].forEach(type => {



        const select = document.getElementById(`proc-${type}-project-select`);



        if (select) {



            const cur = select.value || "";



            select.innerHTML = '<option value="">Tous les projets</option>' + projectOptions;



            select.value = cur;



        }



    });







    // 5. Populate contract select inputs



    populateProcurementContractSelects();







    // 6. Render contracts, dashboard & inventory



    renderContracts();



    renderProcurementDashboard();



    renderStockBalance();



}







function populateProcurementContractSelects() {



    ["receipt", "issue", "return"].forEach(type => {



