async function handleReceiptSubmit(event) {



    event.preventDefault();



    const contractId = document.getElementById("proc-receipt-contract-select")?.value;



    const blNum = document.getElementById("proc-receipt-bl")?.value || "";



    const resp = document.getElementById("proc-receipt-responsible")?.value || "";



    const dateVal = document.getElementById("proc-receipt-date")?.value || new Date().toISOString().slice(0, 10);



    const notesVal = document.getElementById("proc-receipt-notes")?.value || "";







    const contract = ARKAN_STATE.procurementContracts.find(c => c.id === contractId);



    if (!contract) {



        showToast("Contrat invalide !", "error");



        return;



    }







    const rows = document.querySelectorAll("#proc-receipt-rows-container tr");



    if (rows.length === 0) {



        showToast("Veuillez ajouter au moins un article à réceptionner !", "error");



        return;



    }







    for (const row of rows) {



        const code = row.querySelector(".proc-receipt-item-select")?.value;



        const qty = parseFloat(row.querySelector(".proc-receipt-item-qty")?.value || "0");



        const loc = row.querySelector(".proc-receipt-item-loc")?.value || "";



        const status = row.querySelector(".proc-receipt-item-status")?.value || "Conforme";



        const item = contract.items.find(i => i.code === code);



        if (item && qty > 0) {



            item.received += qty;



            item.remaining = Math.max(0, item.ordered - item.received);



            if (item.dbId && contract.dbId) {



                try {



                    await fetch(`${API_BASE}/procurement/receipts`, {



                        method: "POST",



                        headers: { "Content-Type": "application/json" },



                        body: JSON.stringify({



                            item_id: item.dbId,



                            contract_id: contract.dbId,



                            date_reception: dateVal,



                            quantite_recue: qty,



                            bon_livraison: blNum,



                            emplacement_stockage: loc,



                            responsable_reception: resp,



                            statut_qualite: status.toLowerCase(),



                            commentaires: notesVal,



                            auto_generate_pv: true



                        })



                    });



                } catch (err) {



                    console.warn("[handleReceiptSubmit SQLite]", err);



                }



            }



        }



    }







    await loadProcurementData();



    switchProcurementTab("contracts");



    showToast(`PV de Réception (BL #${blNum}) enregistré par ${resp} !`, "success");



}







