    const dateVal = document.getElementById("proc-issue-date")?.value || new Date().toISOString().slice(0, 10);



    const notesVal = document.getElementById("proc-issue-notes")?.value || "";







    const contract = ARKAN_STATE.procurementContracts.find(c => c.id === contractId);



    if (!contract) {



        showToast("Contrat invalide !", "error");



        return;



    }







    const rows = document.querySelectorAll("#proc-issue-rows-container tr");



    if (rows.length === 0) {



        showToast("Veuillez ajouter au moins un article !", "error");



        return;



    }







    for (const row of rows) {



        const code = row.querySelector(".proc-issue-item-select")?.value;



        const qty = parseFloat(row.querySelector(".proc-issue-item-qty")?.value || "0");



        const item = contract.items.find(i => i.code === code);



        if (item && qty > item.received) {



            showToast(`Quantité insuffisante en stock pour ${code} (${item.received} dispo) !`, "error");



            return;



        }



    }







    for (const row of rows) {



        const code = row.querySelector(".proc-issue-item-select")?.value;



        const qty = parseFloat(row.querySelector(".proc-issue-item-qty")?.value || "0");



        const item = contract.items.find(i => i.code === code);



        if (item && qty > 0) {



            item.received -= qty;



            item.issued = (item.issued || 0) + qty;



            if (item.dbId && contract.dbId) {



                try {



                    await fetch(`${API_BASE}/procurement/issues`, {



                        method: "POST",



                        headers: { "Content-Type": "application/json" },



                        body: JSON.stringify({



                            item_id: item.dbId,



                            contract_id: contract.dbId,



                            date_sortie: dateVal,



                            quantite_sortie: qty,



                            destination_chantier: dest,



                            responsable_retrait: resp,



                            commentaires: notesVal,



                            auto_generate_pv: true



                        })



                    });



                } catch (err) {



                    console.warn("[handleIssueSubmit SQLite]", err);



                }



            }



        }



    }







    await loadProcurementData();



    switchProcurementTab("contracts");



    showToast(`PV de Sortie pour chantier (${dest}) validé !`, "success");



}







