function openDcmaNonConformityModal(ruleId) {



    if (!currentPlanningData || !currentPlanningData.tasks) return;







    const modal = document.getElementById("dcma-nonconformity-modal");



    if (!modal) return;







    const tasks = currentPlanningData.tasks;



    let title = "";



    let target = "";



    let nonConformingTasks = [];







    if (ruleId === 1) {



        title = "Règle #1 : Logic & Open Ends (Tâches sans prédécesseur ou successeur)";



        target = "Maximum 0 tâche orpheline (sauf Début/Fin de projet)";



        nonConformingTasks = tasks.filter(t => (!t.predecessors || t.predecessors.length === 0) || (!t.successors || t.successors.length === 0)).map(t => ({



            task: t,



            deviation: (!t.predecessors || t.predecessors.length === 0) ? "Sans prédécesseur (Entrée libre de réseau)" : "Sans successeur (Fin fermée sans suite)",



            recommendation: "Ajouter une liaison logique de dépendance FS/SS pour lier la tâche au réseau."



        }));



    } else if (ruleId === 2) {



        title = "Règle #2 : Leads (Avances sur liaisons - Négatives)";



        target = "0 Lead (Aucun retard négatif)";



        nonConformingTasks = tasks.filter(t => (t.predecessors || []).some(p => p.lag < 0)).map(t => ({



            task: t,



            deviation: "Présence d'un Lag négatif (Lead) sur liaison prédécesseur",



            recommendation: "Supprimer le Lead négatif et scinder la tâche pour préserver Primavera en calcul déterministe."



        }));



    } else if (ruleId === 3) {



        title = "Règle #3 : Lags (Retards sur liaisons de dépendances)";



        target = "Maximum < 5% des liaisons totales";



        nonConformingTasks = tasks.filter(t => 



            (t.predecessors || []).some(p => p.lag > 0) || 



            (t.successors || []).some(s => s.lag > 0)



        ).map(t => {



            const lagPred = (t.predecessors || []).find(p => p.lag > 0) || (t.successors || []).find(s => s.lag > 0);



            return {



                task: t,



                deviation: `Lag positif de +${lagPred ? lagPred.lag : 0}j sur liaison avec ${lagPred ? lagPred.code : 'activité liée'}`,



                recommendation: "Remplacer le lag par une activité physique de séchage/attente."



            };



        });



    } else if (ruleId === 4) {



        title = "Règle #4 : Relationship Types (Liaisons non-FS)";



        target = "> 90% de liaisons FS (Fin à Début)";



        nonConformingTasks = tasks.filter(t => (t.predecessors || []).some(p => p.type && p.type !== 'FS')).map(t => {



            const nonFs = t.predecessors.find(p => p.type && p.type !== 'FS');



            return {



                task: t,



                deviation: `Liaison de type ${nonFs ? nonFs.type : 'Non-FS'} avec ${nonFs ? nonFs.code : 'prédécesseur'}`,



                recommendation: "Convertir en liaison standard FS si possible."



            };



        });



    } else if (ruleId === 5) {



        title = "Règle #5 : Hard Constraints (Contraintes dures)";



        target = "Maximum < 5% des tâches totales";



        nonConformingTasks = tasks.filter(t => t.constraint_type || t.constraint_date).map(t => ({



            task: t,



            deviation: `Contrainte dure fixée (${t.constraint_type || 'Must Finish On'})`,



            recommendation: "Supprimer la contrainte dure et laisser Primavera calculer la marge libre."



        }));



    } else if (ruleId === 6) {



        title = "Règle #6 : High Float (Marge totale > 44 jours)";



        target = "Maximum < 5% des tâches totales";



        nonConformingTasks = tasks.filter(t => t.total_float_days > 44).map(t => ({



            task: t,



            deviation: `Marge totale excessive de ${t.total_float_days} jours`,



            recommendation: "Vérifier si des liaisons successeurs manquent à cette branche WBS."



        }));



    } else if (ruleId === 7) {



        title = "Règle #7 : Negative Float (Marge totale négative < 0j)";



        target = "0 tâche à marge négative";



        nonConformingTasks = tasks.filter(t => t.total_float_days < 0).map(t => ({



            task: t,



            deviation: `Marge négative critique de ${t.total_float_days} jours`,



            recommendation: "Accélérer l'exécution de la branche ou réviser la date cible de fin de projet."



        }));



    } else if (ruleId === 12) {



        title = "Règle #12 : Missed Tasks (Activités en retard sur la date cible)";



        target = "Maximum < 5% des tâches totales";



        const delayed = currentPlanningData.delayedTasks || [];



        nonConformingTasks = delayed.map(d => {



            const matched = tasks.find(t => t.task_code === d.task_code || t.code === d.task_code) || d;



            return {



                task: matched,



                deviation: `Retard accumulé de +${d.delayDays || 0} jours (Fin: ${d.formattedEnd})`,



                recommendation: "Allouer des ressources supplémentaires ou réduire la durée restante."



            };



        });



    } else {



        title = `Règle DCMA #${ruleId} : Audit de Qualité`;



        target = "Conformité selon le standard DCMA 14-Point";



        nonConformingTasks = tasks.slice(0, 5).map(t => ({



            task: t,



            deviation: "Point sous surveillance d'audit",



            recommendation: "Inspecter les liaisons logiques et profils de ressources."



        }));



    }







    document.getElementById("dcma-modal-title").innerText = title;



    document.getElementById("dcma-modal-target-desc").innerText = target;



    document.getElementById("dcma-modal-count-badge").innerText = `${nonConformingTasks.length} Tâche(s) à corriger`;







    const tableBody = document.getElementById("dcma-modal-table-body");



    if (tableBody) {



        if (nonConformingTasks.length > 0) {



            tableBody.innerHTML = nonConformingTasks.slice(0, 40).map(item => {



                const t = item.task;



                const code = t.task_code || t.code || "-";



                return `



                    <tr style="border-bottom:1px solid rgba(255,255,255,0.03);">



                        <td style="padding:10px; font-family:monospace; color:var(--accent-primary); font-weight:700;">${code}</td>



                        <td style="padding:10px; font-weight:600; text-overflow:ellipsis; overflow:hidden; max-width:160px;">${t.task_name || t.name || "-"}</td>



                        <td style="padding:10px; color:var(--text-secondary);">${t.wbs_short || t.wbs_name || "-"}</td>



                        <td style="padding:10px; color:var(--error); font-weight:600;">${item.deviation}</td>



                        <td style="padding:10px; color:var(--text-secondary); font-size:11px;">${item.recommendation}</td>



                        <td style="padding:10px; text-align:center;">



                            <button onclick="closeDcmaNonConformityModal(); openTaskDetailsModal('${code}');" class="new-chat-btn" style="margin:0; font-size:10px; padding:4px 8px;">



                                Inspecter



                            </button>



                        </td>



                    </tr>



                `;



            }).join('');



        } else {



            tableBody.innerHTML = `<tr><td colspan="6" style="padding:20px; text-align:center; color:#27AE60; font-weight:600;">✅ Aucune non-conformité détectée pour cette règle !</td></tr>`;



        }



    }







    modal.classList.remove("hidden");



    modal.classList.add("active");



    modal.style.display = "flex";



    modal.style.opacity = "1";



    modal.style.pointerEvents = "auto";



}







function closeDcmaNonConformityModal() {



