function getDisciplineBadgeInfo(disc) {



    const d = (disc || "").toUpperCase();



    if (d.includes("CIVIL") || d.includes("TERRASSEMENT")) return { label: "Génie Civil", bg: "rgba(59,130,246,0.15)", color: "#60A5FA", border: "#3B82F6" };



    if (d.includes("TUYAUTERIE") || d.includes("PIPING")) return { label: "Tuyauterie", bg: "rgba(212,163,115,0.15)", color: "var(--accent-primary)", border: "var(--accent-primary)" };



    if (d.includes("STRUCTURE") || d.includes("CHARPENTE")) return { label: "Structure", bg: "rgba(245,158,11,0.15)", color: "#FBBF24", border: "#F59E0B" };



    if (d.includes("ELEC") || d.includes("HT_BT")) return { label: "Électricité", bg: "rgba(234,179,8,0.15)", color: "#FDE047", border: "#EAB308" };



    if (d.includes("INSTRUM") || d.includes("AUTOMATISME")) return { label: "Instrumentation", bg: "rgba(168,85,247,0.15)", color: "#C084FC", border: "#A855F7" };



    if (d.includes("DYNAMIQUE") || d.includes("STATIQUE") || d.includes("EQUIPEMENT")) return { label: "Mécanique / Équip.", bg: "rgba(249,115,22,0.15)", color: "#FB923C", border: "#F97316" };



    if (d.includes("COMMISSIONING") || d.includes("PRECOMMISSIONING") || d.includes("TESTS")) return { label: "PC&C / ICAPS", bg: "rgba(16,185,129,0.15)", color: "#34D399", border: "#10B981" };



    if (d.includes("PEINTURE") || d.includes("ISOLATION")) return { label: "Peinture / Calorifuge", bg: "rgba(236,72,153,0.15)", color: "#F472B6", border: "#EC4899" };



    return { label: "Général EPC", bg: "rgba(156,163,175,0.15)", color: "#9CA3AF", border: "#6B7280" };



}







