function recalculateBpuDuration(index, field, value) {



    if (currentExtractedBpuItems[index]) {



        currentExtractedBpuItems[index][field] = value;



        const qty = parseFloat(currentExtractedBpuItems[index].quantite) || 1.0;



        const rend = parseFloat(currentExtractedBpuItems[index].rendement_valeur) || 10.0;



        let newDur = Math.round((qty / rend) * 10) / 10;



        if (newDur < 0.5) newDur = 0.5;



        currentExtractedBpuItems[index].duree_estimee_jours = newDur;







        const durSpan = document.getElementById(`bpu-duration-${index}`);



        if (durSpan) durSpan.innerText = `${newDur} j`;







        const totalEstimatedDays = currentExtractedBpuItems.reduce((acc, it) => acc + (parseFloat(it.duree_estimee_jours) || 1), 0);



        const summarySpan = document.getElementById("bpu-items-summary");



        if (summarySpan) {



            summarySpan.innerHTML = `<strong>${currentExtractedBpuItems.length}</strong> article(s) BPU compris & analysés par l'IA | Durée brute cumulée : <strong>${totalEstimatedDays.toFixed(1)} j</strong>`;



        }



    }



}







function updateBpuItem(index, field, value) {



    if (currentExtractedBpuItems[index]) {



        currentExtractedBpuItems[index][field] = value;



    }



}







function removeBpuItem(index) {



    currentExtractedBpuItems.splice(index, 1);



    renderExtractedBpuTable(currentExtractedBpuItems);



}







