    }







    showToast("Calcul CPM et ordonnancement des tâches...", "info");







    try {



        const headers = { "Content-Type": "application/json" };



        if (API_KEY) headers['X-API-Key'] = API_KEY;







        const res = await fetch(`${API_BASE}/api/planning-ia/bpu/generate-schedule`, {



