            throw new Error(err.detail || "Erreur de génération du planning");



        }







        const planningRes = await res.json();







        // Convertir la réponse planning en format standard de l'UI ARKAN



        const formattedTasks = (planningRes.taches || []).map((t, i) => {



            const startDate = new Date(2026, 8, 1);



            startDate.setDate(startDate.getDate() + Math.round(t.date_debut_tot || 0));



            const endDate = new Date(2026, 8, 1);



            endDate.setDate(endDate.getDate() + Math.round(t.date_fin_tot || t.duree_jours || 1));







            return {



                task_code: t.id_tache,



                code: t.id_tache,



                task_name: t.nom,



                wbs: t.discipline || "06_TUYAUTERIE_MONTAGE_SITE",



                wbs_name: t.phase || "Construction",



                duration: t.duree_jours,



                early_start: t.date_debut_tot || 0,



                early_finish: t.date_fin_tot || t.duree_jours,



                total_float_hr_cnt: Math.round((t.marge_totale || 0) * 8),



                free_float_hr_cnt: Math.round((t.marge_libre || 0) * 8),



                is_critical: t.est_critique,



                status_code: "TK_NotStart",



                phys_complete_pct: 0,



                target_start_date: startDate.toISOString(),



                target_end_date: endDate.toISOString(),



                formattedStart: startDate.toISOString().split('T')[0],



                formattedEnd: endDate.toISOString().split('T')[0],



                predecesseurs: t.predecesseurs || [],



                successeurs: t.successeurs || [],



                equipe_type: t.equipe_type || [],



                ressources_materielles: t.ressources_materielles || [],



                sources: t.sources || []



            };



        });







        const uiPlanningData = {



            projectName: planningRes.projet_contexte,



            projectId: "PRJ-BPU-AUTO",



            tasks: formattedTasks,



            criticalPath: planningRes.chemin_critique,



            delayedTasks: [],



            stats: {



                totalTasks: formattedTasks.length,



                criticalCount: formattedTasks.filter(t => t.is_critical).length,



                nearCriticalCount: 0,



                negativeFloatCount: 0,



                overallScore: 98,



                totalDurationDays: planningRes.duree_totale_jours,



                confidenceScore: planningRes.confidence_score_moyen



            }



        };







        currentPlanningData = uiPlanningData;







        // Afficher l'écran des résultats



        const uploadContainer = document.getElementById("planning-upload-container");



        if (uploadContainer) uploadContainer.style.display = "none";







        const resultsContainer = document.getElementById("planning-results-container");



        if (resultsContainer) resultsContainer.classList.remove("hidden");







        document.getElementById("btn-planning-compare")?.classList.remove("hidden");



        document.getElementById("btn-planning-reset")?.classList.remove("hidden");







        document.getElementById("planning-project-name").innerText = uiPlanningData.projectName;



        document.getElementById("planning-project-id").innerText = uiPlanningData.projectId;



        document.getElementById("planning-file-name").innerText = `BPU (${currentExtractedBpuItems.length} articles métrés)`;







        // Remplir les KPIs



