        document.getElementById("planning-kpi-critical-count").innerText = uiPlanningData.stats.criticalCount;



        document.getElementById("planning-kpi-critical").innerText = `${Math.round((uiPlanningData.stats.criticalCount/formattedTasks.length)*100)}%`;



        document.getElementById("planning-kpi-completed").innerText = "0%";



        document.getElementById("planning-kpi-delayed").innerText = "0";



        document.getElementById("planning-kpi-score").innerText = `${planningRes.confidence_score_moyen}%`;







        // Switch vers la vue Gantt



        switchPlanningTab('gantt');



        showToast(`🎉 Planning CPM généré avec succès (${formattedTasks.length} tâches, durée : ${planningRes.duree_totale_jours}j) !`, "success");







    } catch (e) {



