async function selectSavedXer(fId) {



    showToast("Chargement de l'analyse...", "info");



    let data = null;



    let filename = fId;







    try {



        const headers = {};



        if (API_KEY) {



            headers['X-API-Key'] = API_KEY;



        }



        const res = await fetch(`${API_BASE}/planning/load?path=${encodeURIComponent(fId)}`, { headers });



        if (res.ok) {



            const resData = await res.json();



            if (resData.status === "success") {



                data = resData.data;



                filename = resData.filename;



            }



        }



    } catch (e) {



        console.warn("API load failed, falling back to mock:", e);



    }







    if (!data) {



        filename = fId === 'PL-02' ? "STATION_COMPRESSION_CPF_BASELINE.XER" : "PROJET_HASSI_RMEL_UNIT100_V3.XER";



        data = getMockPlanningData(fId);



    }







    currentPlanningData = data;







    const resultsContainer = document.getElementById("planning-results-container");



    if (resultsContainer) resultsContainer.classList.remove("hidden");







    const uploadContainer = document.getElementById("planning-upload-container");



    if (uploadContainer) uploadContainer.style.display = "none";







    document.getElementById("btn-planning-compare")?.classList.remove("hidden");



    document.getElementById("btn-planning-reset")?.classList.remove("hidden");







    document.getElementById("planning-project-name").innerText = data.projectName || "PROJET SANS NOM";



    document.getElementById("planning-project-id").innerText = data.projectId || "PRJ-UNKNOWN";



    document.getElementById("planning-file-name").innerText = filename;







    // Stats / KPIs



    const stats = data.stats || {};



    const totalTasks = data.tasks ? data.tasks.length : 0;



