async function handlePlanningUpload(event) {



    const file = event.target.files[0];



    if (!file) return;







    const fnLower = file.name.toLowerCase();



    // Si c'est un fichier Excel, PDF ou CSV, basculer AUTOMATIQUEMENT vers le moteur BPU !



    if (fnLower.endsWith(".xlsx") || fnLower.endsWith(".xls") || fnLower.endsWith(".pdf") || fnLower.endsWith(".csv")) {



        switchPlanningSubTab('bpu');



        handleBpuFileUpload(event);



        return;



    }







    showToast("Importation et analyse XER en cours...", "info");







    const formData = new FormData();



    formData.append("file", file);







    try {



        const headers = {};



        if (API_KEY) {



            headers['X-API-Key'] = API_KEY;



        }



        const res = await fetch(`${API_BASE}/planning/analyze`, {



            method: "POST",



            headers: headers,



            body: formData



        });



        if (!res.ok) throw new Error("Échec de l'analyse du fichier XER");



        const resData = await res.json();







        if (resData.status === "success") {



            await loadStoredXerList();







            const matchedFile = ARKAN_STATE.planningSavedFiles.find(f => f.name === resData.filename);



            if (matchedFile) {



                selectSavedXer(matchedFile.id);



            } else {



                showToast("Fichier importé avec succès !", "success");



            }



        }



    } catch (e) {



        showToast("Erreur lors de l'importation: " + e.message, "error");



    }



}







