    if (source === 'table' && tablePanel && timelinePanel) {



        timelinePanel.scrollTop = tablePanel.scrollTop;



    } else if (source === 'timeline' && tablePanel && timelinePanel) {



        tablePanel.scrollTop = timelinePanel.scrollTop;



