function renderRiskChart() {



    const canvas = document.getElementById("risk-confidence-canvas");



    if (!canvas || !currentPlanningData || !currentPlanningData.risk) return;







    if (riskChartInstance) {



        riskChartInstance.destroy();



    }







    const risk = currentPlanningData.risk;







    const formatDate = (dStr) => {



        if (!dStr) return "-";



        const parts = dStr.split("-");



        if (parts.length !== 3) return dStr;



        const months = ["Jan", "Fév", "Mar", "Avr", "Mai", "Jui", "Jyl", "Aoû", "Sep", "Oct", "Nov", "Déc"];



        return `${parts[2]} ${months[parseInt(parts[1]) - 1]} ${parts[0]}`;



    };







    document.getElementById("risk-base-finish").innerText = formatDate(risk.base_finish);



    document.getElementById("risk-p50").innerText = formatDate(risk.p50);



    document.getElementById("risk-p80").innerText = formatDate(risk.p80);



    document.getElementById("risk-p90").innerText = formatDate(risk.p90);







    const riskBody = document.getElementById("risk-criticality-table-body");



    if (riskBody) {



        const crit = risk.criticality || {};



        const sortedCrit = Object.entries(crit).sort((a, b) => b[1] - a[1]).slice(0, 5);







        if (sortedCrit.length > 0) {



            riskBody.innerHTML = sortedCrit.map(([code, val]) => {



                const color = val > 75 ? "var(--error)" : (val > 50 ? "var(--warning)" : "var(--text-secondary)");



                const task = currentPlanningData.tasks.find(t => t.task_code === code) || {};



                return `



                    <tr style="border-bottom:1px solid rgba(255,255,255,0.03); font-size:12px;">



                        <td style="padding:8px; font-family:monospace; color:var(--accent-primary); font-weight:700;">${code}</td>



                        <td style="padding:8px;">${task.task_name || "Activité de projet"}</td>



                        <td style="padding:8px; text-align:center; font-weight:700; color:${color};">${val}%</td>



                        <td style="padding:8px; text-align:center;">+${task.total_float_days || 0} j</td>



                    </tr>



                `;



            }).join('');



        } else {



            riskBody.innerHTML = `



                <tr>



                    <td colspan="4" style="padding:15px; text-align:center; color:var(--text-secondary);">Aucune activité critique.</td>



                </tr>



            `;



        }



    }







    const histList = risk.histogram || [];



    const labels = histList.map(h => formatDate(h.date));



    const histogramData = histList.map(h => h.count);







    let sum = 0;



    const totalRuns = histogramData.reduce((a, b) => a + b, 0) || 1;



    const cumulativeData = histogramData.map(c => {



        sum += c;



        return Math.round((sum / totalRuns) * 100);



    });







    riskChartInstance = new Chart(canvas, {



        type: 'bar',



        data: {



            labels: labels,



            datasets: [



                {



                    type: 'bar',



                    label: 'Densité de Probabilité (Occurrences)',



                    data: histogramData,



                    backgroundColor: 'rgba(212, 163, 115, 0.4)',



                    borderColor: 'var(--accent-primary)',



                    borderWidth: 1,



                    yAxisID: 'y'



                },



                {



                    type: 'line',



                    label: 'Probabilité Cumulative (%)',



                    data: cumulativeData,



                    borderColor: '#3B82F6',



                    borderWidth: 2,



                    fill: false,



                    tension: 0.3,



                    yAxisID: 'y1'



                }



            ]



        },



        options: {



            responsive: true,



            maintainAspectRatio: false,



            plugins: {



                legend: {



                    labels: { color: '#E4E4E7', font: { size: 10 } }



                }



            },



            scales: {



                x: {



                    grid: { color: 'rgba(255,255,255,0.05)' },



                    ticks: { color: '#A1A1AA', maxRotation: 45, minRotation: 45 }



                },



                y: {



                    grid: { color: 'rgba(255,255,255,0.05)' },



                    ticks: { color: '#A1A1AA' },



                    title: { display: true, text: 'Densité', color: '#A1A1AA' }



                },



                y1: {



                    position: 'right',



                    grid: { drawOnChartArea: false },



                    ticks: {



                        color: '#A1A1AA',



                        callback: function(value) { return value + '%'; }



                    },



                    title: { display: true, text: 'Cumulé', color: '#A1A1AA' }



                }



            }



        }



    });



}







