    async function loadIndexFolders() {



        var container = document.getElementById('index-folders-container');



        var triggerLabel = document.getElementById('index-folders-trigger-label');



        if (!container) return;







        container.innerHTML = '<p style="color: var(--text-secondary); font-size: 11px; text-align: center; padding: 10px 0;">Chargement des dossiers...</p>';







        try {



            var headers = { 'Content-Type': 'application/json' };



            var k = _key();



            if (k) headers['X-API-Key'] = k;







            var resp = await fetch(_base() + '/admin/index-folders', { headers: headers });



            if (!resp.ok) throw new Error('HTTP ' + resp.status);







            var data = await resp.json();



            var folders = data.folders || [];







            if (folders.length === 0) {



                container.innerHTML = '<p style="color: var(--text-secondary); font-size: 11px; text-align: center; padding: 10px 0;">Aucun dossier trouvé.</p>';



                if (triggerLabel) triggerLabel.textContent = 'Aucun dossier disponible';



                return;



            }







            var indexedCount = 0;



            container.innerHTML = folders.map(function(f) {



                var isFully = f.status === 'fully_indexed';



                var isPart = f.status === 'partially_indexed';



                if (isFully || isPart) indexedCount++;







                var badgeColor = isFully ? '#27AE60' : (isPart ? '#F59E0B' : 'var(--text-secondary)');



                var badgeText = isFully ? 'Indexé (100%)' : (isPart ? 'Partiel (' + f.indexed_files + '/' + f.total_files + ')' : 'Non indexé (' + f.total_files + ' fich.)');



                var cleanPath = (f.path || '').replace(/\\/g, '\\\\');







                return '<div style="display: flex; justify-content: space-between; align-items: center; padding: 8px 10px; background: rgba(255,255,255,0.03); border: 1px solid var(--border-color); border-radius: 6px;">' +



                    '<div style="display: flex; flex-direction: column; gap: 2px;">' +



                    '<span style="font-size: 12px; font-weight: 600; color: var(--text-primary);">' + f.name + '</span>' +



                    '<span style="font-size: 10px; color: ' + badgeColor + '; font-weight: 600;">' + badgeText + '</span>' +



                    '</div>' +



                    '<div style="display: flex; gap: 6px;">' +



                    (isFully || isPart ? '<button onclick="toggleFolderIndex(\'' + cleanPath + '\', \'deindex\')" style="padding: 4px 8px; font-size: 11px; background: rgba(231, 76, 60, 0.15); color: #E74C3C; border: 1px solid rgba(231, 76, 60, 0.3); border-radius: 4px; cursor: pointer; font-weight: 600;">Désindexer</button>' : '') +



                    '<button onclick="toggleFolderIndex(\'' + cleanPath + '\', \'index\')" style="padding: 4px 8px; font-size: 11px; background: rgba(39, 174, 96, 0.15); color: #27AE60; border: 1px solid rgba(39, 174, 96, 0.3); border-radius: 4px; cursor: pointer; font-weight: 600;">' + (isPart ? 'Re-indexer' : 'Indexer') + '</button>' +



                    '</div>' +



                    '</div>';



            }).join('');







            if (triggerLabel) {



                triggerLabel.textContent = indexedCount + ' / ' + folders.length + ' dossier(s) indexé(s)';



            }



        } catch(err) {



            console.error('[ARKAN] loadIndexFolders error:', err);



            container.innerHTML = '<p style="color: #E74C3C; font-size: 11px; text-align: center; padding: 10px 0;">Erreur : ' + err.message + '</p>';



        }



    }







    function toggleFoldersDropdown(e) {



