function renderCurrentAnalytics() {



    if (!window.currentPlanningIAData || !window.currentPlanningIAData.taches) return;



    const tasks = window.currentPlanningIAData.taches;



    const canvas = document.getElementById('planning-analytics-canvas');



    if (!canvas) return;



    const ctx = canvas.getContext('2d');



    if (!ctx) return;







    const container = canvas.parentElement;



    canvas.width = container.clientWidth ? container.clientWidth - 32 : 800;



    canvas.height = 240;







    const w = canvas.width;



    const h = canvas.height;



    ctx.clearRect(0, 0, w, h);







    const totalDays = Math.max(10, Math.ceil(window.currentPlanningIAData.duree_totale_jours || 10));







    if (currentAnalyticsTab === 'scurve') {



        renderSCurveCanvas(ctx, tasks, totalDays, w, h);



    } else if (currentAnalyticsTab === 'manpower') {



        renderManpowerCanvas(ctx, tasks, totalDays, w, h);



    } else if (currentAnalyticsTab === 'equipment') {



        renderEquipmentCanvas(ctx, tasks, totalDays, w, h);



    }



}







function renderSCurveCanvas(ctx, tasks, totalDays, w, h) {



    const padL = 45, padR = 25, padT = 25, padB = 30;



    const plotW = w - padL - padR;



    const plotH = h - padT - padB;







    // Grille & Axes %



    ctx.strokeStyle = 'rgba(255,255,255,0.06)';



    ctx.lineWidth = 1;



    ctx.fillStyle = '#9CA3AF';



    ctx.font = '10px monospace';



    ctx.textAlign = 'right';







    [0, 25, 50, 75, 100].forEach(pct => {



        const y = padT + plotH - (pct / 100) * plotH;



        ctx.beginPath();



        ctx.moveTo(padL, y);



        ctx.lineTo(w - padR, y);



        ctx.stroke();



        ctx.fillText(`${pct}%`, padL - 6, y + 3);



    });







    // Axe X Jours



    ctx.textAlign = 'center';



    const numTicks = 6;



    for (let i = 0; i <= numTicks; i++) {



        const d = Math.round((i / numTicks) * totalDays);



        const x = padL + (i / numTicks) * plotW;



        ctx.fillText(`J+${d}`, x, h - 10);



    }







    // Calcul des points Early & Late S-Curve



    const totalWorkDays = tasks.reduce((sum, t) => sum + (parseFloat(t.duree_jours) || 1), 0);



    if (totalWorkDays <= 0) return;







    const earlyPts = [];



    const latePts = [];



    const stepDays = Math.max(1, Math.floor(totalDays / 80));







    for (let d = 0; d <= totalDays; d += stepDays) {



        let workDoneEarly = 0;



        let workDoneLate = 0;



        tasks.forEach(t => {



            const dur = parseFloat(t.duree_jours) || 1;



            const es = parseFloat(t.date_debut_tot) || 0;



            const ls = parseFloat(t.date_debut_tard) !== undefined ? parseFloat(t.date_debut_tard) : es;







            if (d >= es) workDoneEarly += Math.min(dur, d - es);



            if (d >= ls) workDoneLate += Math.min(dur, d - ls);



        });







        const pctEarly = Math.min(100, (workDoneEarly / totalWorkDays) * 100);



        const pctLate = Math.min(100, (workDoneLate / totalWorkDays) * 100);



        const x = padL + (d / totalDays) * plotW;



        const yEarly = padT + plotH - (pctEarly / 100) * plotH;



        const yLate = padT + plotH - (pctLate / 100) * plotH;



        earlyPts.push({ x, y: yEarly });



        latePts.push({ x, y: yLate });



    }







    // Tracer la banane (fuseau de flexibilité)



    if (earlyPts.length > 1) {



        ctx.beginPath();



        ctx.moveTo(earlyPts[0].x, earlyPts[0].y);



        earlyPts.forEach(p => ctx.lineTo(p.x, p.y));



        for (let i = latePts.length - 1; i >= 0; i--) {



            ctx.lineTo(latePts[i].x, latePts[i].y);



        }



        ctx.closePath();



        ctx.fillStyle = 'rgba(212, 163, 115, 0.12)';



        ctx.fill();



    }







    // Tracer Courbe au plus tôt (Early - Vert / Doré)



    ctx.beginPath();



    earlyPts.forEach((p, idx) => {



        if (idx === 0) ctx.moveTo(p.x, p.y);



        else ctx.lineTo(p.x, p.y);



    });



    ctx.strokeStyle = '#10B981';



    ctx.lineWidth = 2.5;



    ctx.stroke();







    // Tracer Courbe au plus tard (Late - Bleu Ciel Pointillé)



    ctx.beginPath();



    ctx.setLineDash([4, 4]);



    latePts.forEach((p, idx) => {



        if (idx === 0) ctx.moveTo(p.x, p.y);



        else ctx.lineTo(p.x, p.y);



    });



    ctx.strokeStyle = '#38BDF8';



    ctx.lineWidth = 1.8;



    ctx.stroke();



    ctx.setLineDash([]);







    // Légende



    ctx.fillStyle = '#10B981';



    ctx.fillRect(padL + 10, padT + 6, 12, 4);



    ctx.fillStyle = '#E5E7EB';



    ctx.textAlign = 'left';



    ctx.fillText('Avancement au plus tôt (Early)', padL + 28, padT + 10);







    ctx.fillStyle = '#38BDF8';



    ctx.fillRect(padL + 200, padT + 6, 12, 4);



    ctx.fillStyle = '#E5E7EB';



    ctx.fillText('Avancement au plus tard (Late)', padL + 218, padT + 10);







    ctx.fillStyle = '#D4A373';



    ctx.fillRect(padL + 390, padT + 6, 12, 4);



    ctx.fillStyle = '#E5E7EB';



    ctx.fillText('Fuseau de Flexibilité (Banana Curve)', padL + 408, padT + 10);



}







function renderManpowerCanvas(ctx, tasks, totalDays, w, h) {



    const padL = 45, padR = 25, padT = 25, padB = 30;



    const plotW = w - padL - padR;



    const plotH = h - padT - padB;







    const dailyHeads = new Array(totalDays + 1).fill(0);



    tasks.forEach(t => {



        const es = Math.floor(parseFloat(t.date_debut_tot) || 0);



        const dur = Math.ceil(parseFloat(t.duree_jours) || 1);



        let heads = 0;



        if (t.equipe_type && t.equipe_type.length > 0) {



            heads = t.equipe_type.reduce((s, e) => s + (parseInt(e.effectif) || 1), 0);



        } else {



            heads = 4;



        }



        for (let d = es; d < Math.min(totalDays + 1, es + dur); d++) {



            dailyHeads[d] += heads;



        }



    });







    const maxHead = Math.max(10, Math.ceil(Math.max(...dailyHeads) * 1.15));







    // Grille & Échelle Y



    ctx.strokeStyle = 'rgba(255,255,255,0.06)';



    ctx.lineWidth = 1;



    ctx.fillStyle = '#9CA3AF';



    ctx.font = '10px monospace';



    ctx.textAlign = 'right';







    [0, Math.round(maxHead * 0.5), maxHead].forEach(val => {



        const y = padT + plotH - (val / maxHead) * plotH;



        ctx.beginPath();



        ctx.moveTo(padL, y);



        ctx.lineTo(w - padR, y);



        ctx.stroke();



        ctx.fillText(`${val} h`, padL - 6, y + 3);



    });







    // Barres quotidiennes



    const barW = Math.max(2, plotW / totalDays - 1);



    for (let d = 0; d <= totalDays; d++) {



        const count = dailyHeads[d];



        if (count > 0) {



            const barH = (count / maxHead) * plotH;



            const x = padL + (d / totalDays) * plotW;



            const y = padT + plotH - barH;







            const grad = ctx.createLinearGradient(0, y, 0, padT + plotH);



            grad.addColorStop(0, '#38BDF8');



            grad.addColorStop(1, '#0284C7');



            ctx.fillStyle = grad;



            ctx.fillRect(x, y, barW, barH);



        }



    }







    // Axe X



    ctx.textAlign = 'center';



    for (let i = 0; i <= 6; i++) {



        const d = Math.round((i / 6) * totalDays);



        const x = padL + (i / 6) * plotW;



        ctx.fillText(`J+${d}`, x, h - 10);



    }







    // Légende



    ctx.fillStyle = '#38BDF8';



    ctx.textAlign = 'left';



    ctx.fillText(`👥 Effectif Journalier Mobilisé (Pic maximal : ${Math.max(...dailyHeads)} personnes / jour)`, padL + 10, padT + 10);



}







function renderEquipmentCanvas(ctx, tasks, totalDays, w, h) {



    const padL = 45, padR = 25, padT = 25, padB = 30;



    const plotW = w - padL - padR;



    const plotH = h - padT - padB;







    const dailyEquip = new Array(totalDays + 1).fill(0);



    tasks.forEach(t => {



        const es = Math.floor(parseFloat(t.date_debut_tot) || 0);



        const dur = Math.ceil(parseFloat(t.duree_jours) || 1);



        const eqCount = (t.ressources_materielles && t.ressources_materielles.length > 0) ? t.ressources_materielles.length : 1;



        for (let d = es; d < Math.min(totalDays + 1, es + dur); d++) {



            dailyEquip[d] += eqCount;



        }



    });







    const maxEq = Math.max(5, Math.ceil(Math.max(...dailyEquip) * 1.2));







    ctx.strokeStyle = 'rgba(255,255,255,0.06)';



    ctx.fillStyle = '#9CA3AF';



    ctx.font = '10px monospace';



    ctx.textAlign = 'right';







    [0, Math.round(maxEq * 0.5), maxEq].forEach(val => {



        const y = padT + plotH - (val / maxEq) * plotH;



        ctx.beginPath();



        ctx.moveTo(padL, y);



        ctx.lineTo(w - padR, y);



        ctx.stroke();



        ctx.fillText(`${val} u`, padL - 6, y + 3);



    });







    const barW = Math.max(2, plotW / totalDays - 1);



    for (let d = 0; d <= totalDays; d++) {



        const count = dailyEquip[d];



        if (count > 0) {



            const barH = (count / maxEq) * plotH;



            const x = padL + (d / totalDays) * plotW;



            const y = padT + plotH - barH;







            const grad = ctx.createLinearGradient(0, y, 0, padT + plotH);



            grad.addColorStop(0, '#FBBF24');



            grad.addColorStop(1, '#D97706');



            ctx.fillStyle = grad;



            ctx.fillRect(x, y, barW, barH);



        }



    }







    ctx.textAlign = 'center';



    for (let i = 0; i <= 6; i++) {



        const d = Math.round((i / 6) * totalDays);



        const x = padL + (i / 6) * plotW;



        ctx.fillText(`J+${d}`, x, h - 10);



    }







    ctx.fillStyle = '#FBBF24';



    ctx.textAlign = 'left';



    ctx.fillText(`🚜 Mobilisation Engins Lourds & Outillages (Pic : ${Math.max(...dailyEquip)} engins simultanés)`, padL + 10, padT + 10);



}







