// OPTIMISEUR DE DÉLAIS IA : FAST-TRACKING & CRASHING



// ══════════════════════════════════════════════════════════════════════════════







let currentCrashingTargetPct = 20;







function openPlanningCrashingModal() {



    const data = getOrCreatePlanningData();



    const modal = document.getElementById('modal-planning-crashing');



    if (modal) {



        modal.classList.remove('hidden');



        recalcCrashingSimulation(currentCrashingTargetPct);



    }



}







function closePlanningCrashingModal() {



    const modal = document.getElementById('modal-planning-crashing');



    if (modal) modal.classList.add('hidden');



}



window.openPlanningCrashingModal = openPlanningCrashingModal;



window.closePlanningCrashingModal = closePlanningCrashingModal;







function recalcCrashingSimulation(val) {



    currentCrashingTargetPct = parseInt(val) || 20;



    const targetLabel = document.getElementById('crashing-target-label');



    if (targetLabel) targetLabel.innerText = `-${currentCrashingTargetPct}% de délai`;







    const data = getOrCreatePlanningData();



    const initialDur = parseFloat(data.duree_totale_jours || 100);



    const targetDur = Math.round(initialDur * (1 - currentCrashingTargetPct / 100) * 10) / 10;



    const gain = Math.round((initialDur - targetDur) * 10) / 10;







    const elInit = document.getElementById('crash-sim-initial');



    const elTgt = document.getElementById('crash-sim-target');



    const elGain = document.getElementById('crash-sim-gain');







    if (elInit) elInit.innerText = `${initialDur} jours`;



    if (elTgt) elTgt.innerText = `${targetDur} jours`;



    if (elGain) elGain.innerText = `${gain} jours`;







    // Identifier les tâches critiques à compresser



    const critTasks = data.taches.filter(t => t.est_critique && t.duree_jours > 2);



    const actionsList = document.getElementById('crash-actions-list');



    if (actionsList) {



        let html = '';



        critTasks.slice(0, 5).forEach(t => {



            const oldDur = t.duree_jours;



            const newDur = Math.round(oldDur * (1 - currentCrashingTargetPct / 100) * 10) / 10;



            html += `



                <div style="display:flex; justify-content:space-between; align-items:center; background:rgba(255,255,255,0.03); border:1px solid rgba(255,255,255,0.06); border-radius:4px; padding:6px 10px; font-size:11px;">



                    <div>



                        <span style="font-family:monospace; color:#F87171; font-weight:700;">[${t.id_tache}]</span>



                        <strong style="color:var(--text-primary); margin-left:4px;">${t.nom.slice(0, 45)}</strong>



                        <div style="font-size:10px; color:var(--text-secondary); margin-top:2px;">Action IA : Doublement d'équipe & extension horaire 2x8h</div>



                    </div>



                    <div style="text-align:right; font-family:monospace;">



                        <span style="color:var(--text-secondary); text-decoration:line-through;">${oldDur}j</span>



                        <span style="color:#34D399; font-weight:800; margin-left:6px;">${newDur}j</span>



                    </div>



                </div>



            `;



        });



        actionsList.innerHTML = html || '<div style="color:var(--text-secondary); padding:8px;">Toutes les durées critiques sont déjà optimales.</div>';



    }



}







function applyCrashingScenario() {



    const data = getOrCreatePlanningData();



    const factor = 1 - currentCrashingTargetPct / 100;



    data.taches.forEach(t => {



        if (t.est_critique && t.duree_jours > 2) {



            t.duree_jours = Math.max(0.5, Math.round(t.duree_jours * factor * 10) / 10);



            if (t.rendement && t.rendement.valeur > 0) {



                t.rendement.valeur = Math.round((t.rendement.valeur / factor) * 10) / 10;



            }



        }



    });







    recalculateClientCPM(data);



    const durEl = document.getElementById('kpi-pia-duration');



    if (durEl) durEl.innerText = `${data.duree_totale_jours} jours`;



    const cpmEl = document.getElementById('kpi-pia-cpm');



    if (cpmEl) cpmEl.innerText = `${data.chemin_critique.length} tâches`;







    renderPlanningTable(data.taches);



    renderNativePlanningGantt(data.taches, data.chemin_critique);



    renderCurrentAnalytics();







    closePlanningCrashingModal();



    if (typeof showToast === 'function') {



        showToast(`Scénario accéléré (-${currentCrashingTargetPct}%) appliqué avec succès !`, "success");



    }



}







