// SIMULATION MONTE CARLO (PERT P50 / P80 / P90)



// ══════════════════════════════════════════════════════════════════════════════







function openMonteCarloModal() {



    const data = getOrCreatePlanningData();



    const modal = document.getElementById('modal-monte-carlo');



    if (modal) {



        modal.classList.remove('hidden');



        setTimeout(() => { runMonteCarloSimulation(); }, 50);



    }



}







function closeMonteCarloModal() {



    const modal = document.getElementById('modal-monte-carlo');



    if (modal) modal.classList.add('hidden');



}







function runMonteCarloSimulation() {



    if (!window.currentPlanningIAData || !window.currentPlanningIAData.taches) return;



    const tasks = window.currentPlanningIAData.taches;







    const rWeather = parseFloat(document.getElementById('mc-risk-weather')?.value || 0.15);



    const rProc = parseFloat(document.getElementById('mc-risk-procurement')?.value || 0.15);



    const rSite = parseFloat(document.getElementById('mc-risk-site')?.value || 0.15);



    const totalRiskFactor = (rWeather + rProc + rSite) / 3.0;







    const iterations = 1000;



    const simDurations = [];







    for (let iter = 0; iter < iterations; iter++) {



        const simTasks = tasks.map(t => {



            const baseDur = parseFloat(t.duree_jours) || 1;



            // Distribution PERT Triangulaire : a (opt), m (mode), b (pess)



            const a = baseDur * 0.85;



            const m = baseDur;



            const b = baseDur * (1.0 + totalRiskFactor * 1.8);



            // Échantillonnage triangulaire



            const u = Math.random();



            const f = (m - a) / (b - a);



            const dur = (u < f) ? a + Math.sqrt(u * (b - a) * (m - a)) : b - Math.sqrt((1 - u) * (b - a) * (b - m));



            return {



                id_tache: t.id_tache,



                predecesseurs: t.predecesseurs,



                duree_jours: dur



            };



        });







        // Calcul rapide Forward Pass



        const tMap = {};



        simTasks.forEach(t => { tMap[t.id_tache] = t; });



        simTasks.forEach(t => {



            let maxPred = 0;



            if (t.predecesseurs) {



                t.predecesseurs.forEach(pid => {



                    const p = tMap[pid];



                    if (p) {



                        const pef = (p.es || 0) + p.duree_jours;



                        if (pef > maxPred) maxPred = pef;



                    }



                });



            }



            t.es = maxPred;



            t.ef = t.es + t.duree_jours;



        });







        const totalD = Math.max(...simTasks.map(t => t.ef));



        simDurations.push(totalD);



    }







    simDurations.sort((a, b) => a - b);



    const p50 = Math.round(simDurations[Math.floor(iterations * 0.50)] * 10) / 10;



    const p80 = Math.round(simDurations[Math.floor(iterations * 0.80)] * 10) / 10;



    const p90 = Math.round(simDurations[Math.floor(iterations * 0.90)] * 10) / 10;







    document.getElementById('mc-p50-val').innerText = `${p50} j`;



    document.getElementById('mc-p80-val').innerText = `${p80} j`;



    document.getElementById('mc-p90-val').innerText = `${p90} j`;







    // Dessiner l'histogramme de probabilité sur canvas



    renderMonteCarloCanvas(simDurations, p50, p80, p90);



}







function renderMonteCarloCanvas(durations, p50, p80, p90) {



    const canvas = document.getElementById('monte-carlo-canvas');



    if (!canvas) return;



    const ctx = canvas.getContext('2d');



    if (!ctx) return;







    canvas.width = canvas.parentElement.clientWidth - 24;



    canvas.height = 160;



    const w = canvas.width;



    const h = canvas.height;



    ctx.clearRect(0, 0, w, h);







    const minD = durations[0];



    const maxD = durations[durations.length - 1];



    const numBins = 30;



    const bins = new Array(numBins).fill(0);



    const binSize = (maxD - minD) / numBins;







    durations.forEach(d => {



        const bIdx = Math.min(numBins - 1, Math.floor((d - minD) / binSize));



        bins[bIdx]++;



    });







    const maxBin = Math.max(...bins);



    const padL = 20, padR = 20, padT = 15, padB = 25;



    const plotW = w - padL - padR;



    const plotH = h - padT - padB;







    // Barres de l'histogramme



    const barW = plotW / numBins;



    for (let i = 0; i < numBins; i++) {



        const count = bins[i];



        const barH = (count / maxBin) * plotH;



        const x = padL + i * barW;



        const y = padT + plotH - barH;







        ctx.fillStyle = 'rgba(167, 139, 250, 0.4)';



        ctx.strokeStyle = '#A78BFA';



        ctx.lineWidth = 1;



        ctx.fillRect(x, y, barW - 1, barH);



        ctx.strokeRect(x, y, barW - 1, barH);



    }







    // Lignes verticales pour P50, P80, P90



    const drawPercentileLine = (val, color, label) => {



        const x = padL + ((val - minD) / (maxD - minD)) * plotW;



        ctx.beginPath();



        ctx.moveTo(x, padT);



        ctx.lineTo(x, padT + plotH);



        ctx.strokeStyle = color;



        ctx.lineWidth = 2;



        ctx.setLineDash([3, 3]);



        ctx.stroke();



        ctx.setLineDash([]);







        ctx.fillStyle = color;



        ctx.font = '10px monospace';



        ctx.textAlign = 'center';



        ctx.fillText(label, x, padT - 3);



    };







    drawPercentileLine(p50, '#60A5FA', 'P50');



    drawPercentileLine(p80, '#34D399', 'P80');



    drawPercentileLine(p90, '#FBBF24', 'P90');



}







