window.openEquipmentFicheModal = async function(tagOrObj, type, label, desc, spec1, spec2, ptest, mat, norm, docs, status, arhDocsList) {



        try {



            var modal = document.getElementById('equipment-fiche-modal');



            if (!modal) {



                console.error("[ARKAN] Element #equipment-fiche-modal non trouvé");



                showToast("Fenêtre de fiche technique introuvable", "error");



                return;



            }







            var tag = tagOrObj;



            var eqObj = null;







            if (typeof tagOrObj === 'object' && tagOrObj !== null) {



                eqObj = tagOrObj;



                tag = eqObj.tag;



                type = eqObj.type || type;



                label = eqObj.label || label;



                desc = eqObj.desc || eqObj.description || desc;



                spec1 = eqObj.spec1 || spec1;



                spec2 = eqObj.spec2 || spec2;



                ptest = eqObj.ptest || ptest;



                mat = eqObj.material || eqObj.mat || mat;



                norm = eqObj.norm || norm;



                docs = eqObj.docs || docs;



                status = eqObj.status || status;



                arhDocsList = eqObj.arhDocsList || arhDocsList;



            } else if (typeof tag === 'string') {



                try { tag = decodeURIComponent(tag); } catch(e) {}







                // 1. Recherche prioritaire dans currentProjectEquipmentsList



                if (typeof currentProjectEquipmentsList !== 'undefined' && Array.isArray(currentProjectEquipmentsList)) {



                    eqObj = currentProjectEquipmentsList.find(function(item) {



                        return item && item.tag && item.tag.toLowerCase().trim() === tag.toLowerCase().trim();



                    });



                }







                // 2. Recherche dans ARKAN_STATE



                if (!eqObj && typeof ARKAN_STATE !== 'undefined' && ARKAN_STATE.projectEquipments) {



                    for (var pKey in ARKAN_STATE.projectEquipments) {



                        var list = ARKAN_STATE.projectEquipments[pKey];



                        if (Array.isArray(list)) {



                            eqObj = list.find(function(item) {



                                return item && item.tag && item.tag.toLowerCase().trim() === tag.toLowerCase().trim();



                            });



                            if (eqObj) break;



                        }



                    }



                }







                if (eqObj) {



                    type = type || eqObj.type;



                    label = label || eqObj.label;



                    desc = desc || eqObj.desc || eqObj.description;



                    spec1 = spec1 || eqObj.spec1;



                    spec2 = spec2 || eqObj.spec2;



                    ptest = ptest || eqObj.ptest || (eqObj.raw && eqObj.raw.p_test);



                    mat = mat || eqObj.material || eqObj.mat || (eqObj.raw && (eqObj.raw.material || eqObj.raw.mat));



                    norm = norm || eqObj.norm || (eqObj.raw && eqObj.raw.norm);



                    docs = docs || eqObj.docs || (eqObj.raw && eqObj.raw.related_documents && eqObj.raw.related_documents.join(', '));



                    status = status || eqObj.status || (eqObj.raw && eqObj.raw.status);



                }



            }







            // Déductions intelligentes selon le tag Oil & Gas



            tag = (tag || 'ÉQUIP-001').toUpperCase().trim();



            type = (type || 'EQUIPMENT').toUpperCase().trim();



            if (type === 'EQUIPMENT') {



                if (/^(V|SEP|TK|BALLON)/i.test(tag)) type = 'VESSEL';



                else if (/^(K|COMP)/i.test(tag)) type = 'COMPRESSOR';



                else if (/^(P|POMP)/i.test(tag)) type = 'PUMP';



                else if (/^(E|HEX|AER|COND)/i.test(tag)) type = 'HEAT_EXCHANGER';



                else if (/^(FV|PV|LV|TV|FCV|PCV|LCV|TCV|XV|MOV|PSV|ROK)/i.test(tag)) type = 'VALVE';



                else if (/^(PIT|FIT|LIT|TIT|PDIT)/i.test(tag)) type = 'INSTRUMENT';



            }







            label = label || `${tag} - Équipement Réglementé Procédé ARH`;



            desc = desc || `Équipement sous pression soumis au contrôle de conformité ARH selon le décret exécutif 21-314 & les normes internationales (ASME / API / ISO).`;



