            ptest = ptest || 'P_test = 60.0 bar g (1.5 x Pdesign)';



            mat = mat || 'Acier Carbone A516 Gr 70 / Inox 316L';



            norm = norm || 'ASME VIII Div 1 / API 6D / DE 21-314';



            docs = docs || `${tag}-DATASHEET.pdf`;



            status = status || 'CONFORME ARH';







            if (!arhDocsList || arhDocsList.length === 0) {



                arhDocsList = [



                    { code: 'DOC-01', name: 'Notice Technique & Plan de Fabrication', ref: 'P-CTE-1 / ISO 9001' },



                    { code: 'DOC-02', name: 'Attestation de Conformité de Construction', ref: 'DE 21-314 Art 12' },



                    { code: 'DOC-03', name: 'Procès-Verbal d’Épreuve Hydrostatique (Ptest)', ref: 'ASME Sect VIII / DE 21-261' },



                    { code: 'DOC-04', name: 'Rapport CND (Rx 100% / US / Magnetoscopie)', ref: 'ASME V / EN 10204 3.1' },



                    { code: 'DOC-05', name: 'Certificats de Matériaux Traçables 3.1', ref: 'EN 10204 / NACE MR0175' },



                    { code: 'DOC-06', name: 'Étude de Danger HAZOP & Système de Sécurité', ref: 'DE 21-315 / API 14C' }



                ];



            }







            // Mise à jour de tous les champs dans le DOM de la modale



            var tagEl = document.getElementById('eq-fiche-tag-header');



            if (tagEl) tagEl.textContent = tag;







            var typeEl = document.getElementById('eq-fiche-type-badge');



            if (typeEl) typeEl.textContent = type;







            var labelEl = document.getElementById('eq-fiche-label-header');



            if (labelEl) labelEl.textContent = label;







            var descEl = document.getElementById('eq-fiche-desc');



            if (descEl) descEl.textContent = desc;







            var s1El = document.getElementById('eq-fiche-spec1');



            if (s1El) s1El.textContent = spec1;







            var s2El = document.getElementById('eq-fiche-spec2');



            if (s2El) s2El.textContent = spec2;







            var ptEl = document.getElementById('eq-fiche-ptest');



            if (ptEl) ptEl.textContent = ptest;







            var matEl = document.getElementById('eq-fiche-material') || document.getElementById('eq-fiche-mat');



            if (matEl) matEl.textContent = mat;







