    window.processMtoUpload = async function(fileOrFiles) {



        if (!fileOrFiles) return;



        const files = (fileOrFiles instanceof FileList) 



            ? Array.from(fileOrFiles) 



            : (Array.isArray(fileOrFiles) ? fileOrFiles : [fileOrFiles]);



        if (files.length === 0) return;



        const isBatch = files.length > 1 || files[0].name.toLowerCase().endsWith('.zip');



        const firstFile = files[0];







        window.currentMtoFileName = isBatch ? `Lot_${files.length}_isometriques` : firstFile.name;







        // Pré-charger le fichier dans le visualiseur si c'est un plan unique



        if (!isBatch && typeof window.loadPlanInViewer === 'function') {



            window.loadPlanInViewer(firstFile);



        }







        const uploadZone = document.getElementById('mto-upload-zone');



        const loader = document.getElementById('mto-loader');



        const results = document.getElementById('mto-results');



        const resetBtn = document.getElementById('btn-mto-reset');



        const excelBtn = document.getElementById('btn-mto-download-excel');







        if (uploadZone) uploadZone.style.display = 'none';



        if (results) results.classList.add('hidden');



        if (loader) {



            loader.classList.remove('hidden');



            const lTitle = loader.querySelector('h4');



            const lDesc = loader.querySelector('p');



            if (lTitle) {



                lTitle.textContent = isBatch 



                    ? `Consolidation globale de ${files.length} plan(s) en cours...` 



                    : `Analyse du plan technique en cours...`;



            }



            if (lDesc) {



                lDesc.textContent = isBatch 



                    ? `Extraction des nomenclatures, déduplication, calculs ASME et génération du classeur Excel (.xlsx)...` 



                    : `Le système extrait les métadonnées géométriques et structurelles de la tuyauterie.`;



            }



        }







        showToast(isBatch ? `Consolidation MTO de ${files.length} plans en cours...` : `Analyse MTO en cours pour ${firstFile.name}...`, "info");







        try {



            const formData = new FormData();



            const base = typeof API_BASE !== 'undefined' ? API_BASE : window.location.origin;



            let endpoint = '';







            if (isBatch) {

                for (let i = 0; i < files.length; i++) {

                    if (files[i] instanceof File || files[i] instanceof Blob) {

                        formData.append('files', files[i]);

                    }

                }

                endpoint = `${base}/mto/batch-calculate`;

            } else {

                if (firstFile instanceof File || firstFile instanceof Blob) {

                    formData.append('file', firstFile);

                }

                if (firstFile && firstFile.path) {

                    formData.append('file_path', firstFile.path);

                }

                endpoint = `${base}/mto/calculate`;

            }







            const res = await fetch(endpoint, {



                method: 'POST',



                body: formData



            });







            if (!res.ok) {



