                } else {



                    showToast(`Nomenclature MTO extraite avec succès (${window.currentMtoData.length} articles) !`, "success");



                }



            }







        } catch (err) {



            console.error("Erreur MTO upload:", err);



            showToast(`Erreur d'analyse MTO: ${err.message}`, "error");



            if (uploadZone) uploadZone.style.display = 'block';



        } finally {



            if (loader) loader.classList.add('hidden');



        }



    };







