    window.resolveStandardMtoItemFromAnomaly = function(a, idx, currentMtoData) {



        currentMtoData = currentMtoData || [];







        // 1. Découverte du contexte de la ligne (Diamètre dominant, schedule, matières)



        let dominantSize = '8"';



        let dominantSchedule = 'SCH 40';



        let dominantPipeMaterial = 'ASTM A106 Gr.B';



        let dominantFittingMaterial = 'ASTM A234 WPB';



        let dominantFlangeMaterial = 'ASTM A105';



        let dominantValveMaterial = 'ASTM A216 WCB';







        const sizesCount = {};



        currentMtoData.forEach(it => {



            if (it.size && it.size !== '-') {



                sizesCount[it.size] = (sizesCount[it.size] || 0) + 1;



            }



            const descUpper = (it.description || '').toUpperCase();



            const mat = it.material || '';



            if (descUpper.includes('PIPE') && mat && mat !== '-') dominantPipeMaterial = mat;



            if (descUpper.includes('ELBOW') || descUpper.includes('TEE') || descUpper.includes('FITTING') || descUpper.includes('COUDE')) {



                if (mat && mat !== '-') dominantFittingMaterial = mat;



            }



            if (descUpper.includes('FLANGE') && mat && mat !== '-') dominantFlangeMaterial = mat;



            if (descUpper.includes('VALVE') && mat && mat !== '-') dominantValveMaterial = mat;



            if (it.schedule && it.schedule !== '-') dominantSchedule = it.schedule;



        });







        let maxCnt = 0;



        for (const s in sizesCount) {



            if (sizesCount[s] > maxCnt) {



                maxCnt = sizesCount[s];



                dominantSize = s;



            }



        }







        // 2. Identification de la catégorie technique et du type d'article



        const ruleId = String(a.id || a.rule || '').toUpperCase();



        const titleUpper = String(a.title || '').toUpperCase();



        const compUpper = String(a.component || a.category || '').toUpperCase();



        const descUpper = String(a.description || '').toUpperCase();







        let category = 'Others';



        let itemType = 'OTHER';







        if (ruleId.includes('BEND') || ruleId.includes('ELBOW') || compUpper.includes('FIT') || titleUpper.includes('COUDE') || descUpper.includes('COUDE')) {



            category = 'Fittings';



            itemType = 'ELBOW_90';



        } else if (ruleId.includes('VALVE') || compUpper.includes('VALVE') || titleUpper.includes('VANNE') || descUpper.includes('VANNE')) {



            category = 'Valves';



            itemType = 'VALVE_BALL';



        } else if (ruleId.includes('PIPE') || compUpper.includes('PIPE') || titleUpper.includes('MÉTRAGE') || titleUpper.includes('TUYAU') || descUpper.includes('MÉTRAGE')) {



            category = 'Pipes';



            itemType = 'PIPE';



        } else if (ruleId.includes('FLANGE') || compUpper.includes('FLANGE') || titleUpper.includes('BRIDE') || descUpper.includes('BRIDE')) {



            category = 'Flanges';



            itemType = 'FLANGE_WN';



        } else if (ruleId.includes('BOLT') || compUpper.includes('BOLT') || titleUpper.includes('BOULON') || descUpper.includes('BOULON')) {



            category = 'Others';



            itemType = 'BOLT';



        } else if (ruleId.includes('GASKET') || compUpper.includes('GASKET') || titleUpper.includes('JOINT') || descUpper.includes('JOINT')) {



            category = 'Others';



            itemType = 'GASKET';



        } else if (ruleId.includes('INST') || compUpper.includes('INST') || titleUpper.includes('INSTRUMENT')) {



            category = 'Instruments';



            itemType = 'INSTRUMENT';



        }







        // 3. Détection du diamètre nominal (NPS)



        let size = a.size || '';



        if (!size) {



            const fullTxt = `${a.description || ''} ${a.title || ''} ${a.found || ''} ${a.expected || ''}`;



            const sMatch = fullTxt.match(/\b(\d+(?:\.\d+)?|\d+\/\d+|\d+-\d+\/\d+)\s*["'”]/);



            if (sMatch) size = sMatch[0];



        }



        if (!size || size === '-') size = dominantSize;



        const cleanNps = size.replace(/\s+/g, '');







        // 4. Calcul de la quantité exacte (Écart détecté ou valeur trouvée)



        let quantity = 1;



        let unit = (category === 'Pipes') ? 'm' : 'EA';







        const parseNum = (str) => {



            if (!str) return null;



            const m = String(str).match(/([\d]+(?:[.,]\d+)?)/);



            return m ? parseFloat(m[1].replace(',', '.')) : null;



        };







        const numFound = parseNum(a.found);



        const numExpected = parseNum(a.expected);







        if (numFound !== null && numExpected !== null) {



            const delta = Math.abs(numFound - numExpected);



            quantity = delta > 0 ? (category === 'Pipes' ? Number(delta.toFixed(3)) : Math.round(delta)) : numFound;



        } else if (numFound !== null) {



            quantity = category === 'Pipes' ? Number(numFound.toFixed(3)) : Math.round(numFound);



        } else if (numExpected !== null) {



            quantity = category === 'Pipes' ? Number(numExpected.toFixed(3)) : Math.round(numExpected);



        }







        const valStr = String(a.found || a.expected || '').toLowerCase();



        if (valStr.includes('m') && !valStr.includes('ea') && !valStr.includes('mm')) {



            unit = 'm';



        }







        // 5. Recherche d'un article existant identique dans le plan pour hériter à 100% des spécifications réelles



        let standardDescription = '';



        let material = '';



        let schedule = dominantSchedule;



        let unitWeight = 0;







        const existingMatch = currentMtoData.find(it => {



            const itDesc = (it.description || '').toUpperCase();



