            if (itemType === 'VALVE_BALL' && (itDesc.includes('VALVE') || itDesc.includes('VANNE'))) return true;



            if (itemType === 'PIPE' && itDesc.includes('PIPE')) return true;



            if (itemType === 'FLANGE_WN' && itDesc.includes('FLANGE')) return true;



            return false;



        });







        if (existingMatch) {



            standardDescription = existingMatch.description;



            size = existingMatch.size || size;



            schedule = existingMatch.schedule || schedule;



            material = existingMatch.material || material;



            unitWeight = existingMatch.weight_unit || 0;



