            '3"': 11.29, '4"': 16.07, '6"': 28.26, '8"': 42.53, '10"': 60.31,



            '12"': 73.81, '14"': 81.33, '16"': 93.27, '18"': 105.15, '20"': 117.00, '24"': 141.00



        };







        const asmeValveWeights = {



            '1/2"': 2.5, '3/4"': 3.5, '1"': 5.0, '1-1/2"': 7.5, '2"': 11.0,



            '3"': 22.0, '4"': 36.0, '6"': 62.0, '8"': 85.0, '10"': 135.0, '12"': 195.0



        };







        const asmeFlangeWeights = {



            '1/2"': 0.9, '3/4"': 1.2, '1"': 1.6, '1-1/2"': 2.2, '2"': 3.0,



            '3"': 5.2, '4"': 7.5, '6"': 11.5, '8"': 19.0, '10"': 25.0, '12"': 38.0



        };







        if (!standardDescription) {



            if (itemType === 'ELBOW_90') {



                standardDescription = '90° LR ELBOW ASME B16.9';



                material = dominantFittingMaterial || 'ASTM A234 WPB';



                unitWeight = asmeFittingWeights[cleanNps] || 30.50;



            } else if (itemType === 'VALVE_BALL') {



                standardDescription = 'BALL VALVE FLANGED ASME B16.34 CL.150';



                material = dominantValveMaterial || 'ASTM A216 WCB';



                unitWeight = asmeValveWeights[cleanNps] || 85.00;



            } else if (itemType === 'PIPE') {



                standardDescription = 'SEAMLESS PIPE ASME B36.10M BE';



                material = dominantPipeMaterial || 'ASTM A106 Gr.B';



                unitWeight = asmePipeWeights[cleanNps] || 42.53;



            } else if (itemType === 'FLANGE_WN') {



                standardDescription = 'WELDING NECK FLANGE RF ASME B16.5 CL.150';



                material = dominantFlangeMaterial || 'ASTM A105';



                unitWeight = asmeFlangeWeights[cleanNps] || 19.00;



            } else if (itemType === 'BOLT') {



                standardDescription = 'STUD BOLT WITH 2 HEAVY HEX NUTS ASME B18.2.1 / B18.2.2';



                material = 'ASTM A193 B7 / A194 2H';



                unitWeight = 0.85;



            } else if (itemType === 'GASKET') {



                standardDescription = 'SPIRAL WOUND GASKET 316L/GRAPHITE ASME B16.20 CL.150';



                material = 'SS316L / Graphite';



                unitWeight = 0.45;



            } else if (itemType === 'INSTRUMENT') {



                standardDescription = a.title || 'PRESSURE TRANSMITTER 4-20mA HART EX-D';



                material = 'AISI 316L';



                unitWeight = 4.20;



            } else {



                standardDescription = a.title || 'Article Technique Validé';



                material = 'Standard EPC';



                unitWeight = 5.00;



            }



        }







        if (!unitWeight || unitWeight === 0) {



            if (itemType === 'ELBOW_90') unitWeight = asmeFittingWeights[cleanNps] || 30.50;



            else if (itemType === 'PIPE') unitWeight = asmePipeWeights[cleanNps] || 42.53;



            else if (itemType === 'VALVE_BALL') unitWeight = asmeValveWeights[cleanNps] || 85.00;



            else if (itemType === 'FLANGE_WN') unitWeight = asmeFlangeWeights[cleanNps] || 19.00;



            else unitWeight = 5.00;



        }







        // Tag propre



        const prefix = category === 'Fittings' ? 'FIT' : (category === 'Pipes' ? 'PIP' : (category === 'Valves' ? 'VAL' : (category === 'Flanges' ? 'FLG' : 'MAT')));



