    window.validateMtoAnomaly = function(idx) {



        if (!window.currentMtoAnomalies || !window.currentMtoAnomalies[idx]) return;



        const a = window.currentMtoAnomalies[idx];







        if (a.status === 'VALIDATED') {



            // Annulation de la validation : réouverture



            a.status = 'OPEN';



            a.validated_at = null;



            a._inserted_mto_item = null;







            // Retirer l'article correspondant du tableau d'extraction MTO



            if (window.currentMtoData && window.currentMtoData.length > 0) {



                const itemIdx = window.currentMtoData.findIndex(it => it._source_reserve_idx === idx);



                if (itemIdx !== -1) {



                    window.currentMtoData.splice(itemIdx, 1);



                    window.renderMtoTable(window.currentMtoData);



                    const kpiTotal = document.getElementById('kpi-mto-total');



                    if (kpiTotal) kpiTotal.textContent = window.currentMtoData.length;



                }



            }



            showToast("Validation annulée — réserve réouverte et retirée du tableau MTO.", "info");



        } else {



            // Validation et création d'un article ASME normalisé et détaillé



            a.status = 'VALIDATED';



            a.validated_at = new Date().toLocaleString('fr-FR');







            const newItem = window.resolveStandardMtoItemFromAnomaly(a, idx, window.currentMtoData);



            a._inserted_mto_item = newItem;







            if (!window.currentMtoData) window.currentMtoData = [];







            // Mise à jour si déjà présent, sinon insertion dans le tableau d'extraction



            const existingIdx = window.currentMtoData.findIndex(it => it._source_reserve_idx === idx);



            if (existingIdx !== -1) {



                window.currentMtoData[existingIdx] = newItem;



            } else {



                window.currentMtoData.push(newItem);



            }







            // Rendu immédiat du tableau MTO mis à jour et des KPIs



            window.renderMtoTable(window.currentMtoData);



            const kpiTotal = document.getElementById('kpi-mto-total');



            if (kpiTotal) kpiTotal.textContent = window.currentMtoData.length;







            const excelBtn = document.getElementById('btn-mto-download-excel');



            if (excelBtn) excelBtn.classList.remove('hidden');







            showToast(`✅ Réserve validée : ${newItem.quantity} ${newItem.unit} ${newItem.description} (${newItem.size}, ${newItem.weight_total} kg) inséré dans le tableau MTO !`, "success");



        }



        window.renderMtoAnomalies();



    };







