    window.exportMtoToCsv = function() {



        if (!window.currentMtoData || window.currentMtoData.length === 0) {



            showToast("Aucun article MTO à exporter.", "warning");



            return;



        }



        let csv = "\uFEFFCatégorie,Tag / Ref,Description,Diamètre,Spécification,Quantité,Unité,Poids Unitaire (kg),Poids Total (kg),Remarques\n";



        window.currentMtoData.forEach(it => {



            const row = [



                `"${(it.category || '').replace(/"/g, '""')}"`,



                `"${(it.tag || '').replace(/"/g, '""')}"`,



                `"${(it.description || '').replace(/"/g, '""')}"`,



                `"${(it.size || '').replace(/"/g, '""')}"`,



                `"${(it.material || it.rating || '').replace(/"/g, '""')}"`,



                it.quantity || 1,



                `"${(it.unit || 'EA').replace(/"/g, '""')}"`,



                it.weight_unit || 0,



                it.weight_total || 0,



                `"${(it.remarks || '').replace(/"/g, '""')}"`



            ];



            csv += row.join(",") + "\n";



        });







        const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });



        const url = URL.createObjectURL(blob);



        const a = document.createElement('a');



        a.href = url;



        const fname = (window.currentMtoFileName ? window.currentMtoFileName.replace(/\.[^/.]+$/, "") : "MTO") + "_Export_ARKAN.csv";



        a.download = fname;



        document.body.appendChild(a);



        a.click();



        document.body.removeChild(a);



        URL.revokeObjectURL(url);



        showToast(`Fichier ${fname} téléchargé avec succès !`, "success");



    };







    window.downloadCaesarModel = async function() {



        showToast("Récupération du modèle Caesar II neutral...", "info");



        try {



            const base = typeof API_BASE !== 'undefined' ? API_BASE : window.location.origin;



            const res = await fetch(`${base}/mto/caesar-export`);



            if (!res.ok) {



                throw new Error("Modèle Caesar II non disponible pour ce plan.");



            }



            const blob = await res.blob();



            const url = URL.createObjectURL(blob);



            const a = document.createElement('a');



            a.href = url;



            a.download = (window.currentMtoFileName ? window.currentMtoFileName.replace(/\.[^/.]+$/, "") : "caesar") + "_model.txt";



            document.body.appendChild(a);



            a.click();



            document.body.removeChild(a);



            URL.revokeObjectURL(url);



            showToast("Modèle Caesar II téléchargé avec succès !", "success");



        } catch (err) {



            showToast(err.message || "Erreur de téléchargement Caesar II", "warning");



        }



    };







