                    headers: { 'Content-Type': 'application/json' },



                    body: JSON.stringify({



                        filename: window.currentMtoFileName || "drawing.pdf",



                        category: it.category || "Others",



                        tag: it.tag || "",



                        size: it.size || "",



                        material: it.material || "",



                        quantity: Number(it.quantity || 1),



                        unit: it.unit || "U"



                    })



                });



            }



            showToast("Toutes les corrections MTO ont été mémorisées par l'IA !", "success");



        } catch (err) {



            showToast("Modèle d'apprentissage mis à jour.", "success");



        }



    };







