async function triggerPlanningIAGeneration() {



    const promptEl = document.getElementById('planning-ia-prompt');



    const promptVal = promptEl ? promptEl.value.trim() : '';



    if (!promptVal) {



        alert("Veuillez décrire le projet ou le lot de travaux à planifier.");



        return;



    }







    const typeInst = document.getElementById('planning-ia-type')?.value || null;



    const wbsLevel = parseInt(document.getElementById('planning-ia-wbs-level')?.value || '3', 10);



    const loc = document.getElementById('planning-ia-loc')?.value || "Hassi Messaoud";



    const dateStart = document.getElementById('planning-ia-date')?.value || null;







    const progContainer = document.getElementById('planning-ia-progress-container');



    const progStatus = document.getElementById('planning-ia-progress-status');



    const progBar = document.getElementById('planning-ia-progress-bar');



    const progCount = document.getElementById('planning-ia-progress-count');



    const resultsContainer = document.getElementById('planning-ia-results-container');



    const btn = document.getElementById('btn-generate-planning-ia');







    if (progContainer) progContainer.classList.remove('hidden');



    if (resultsContainer) resultsContainer.classList.add('hidden');



    if (btn) { btn.disabled = true; btn.style.opacity = '0.6'; }



    if (progBar) progBar.style.width = '10%';



    if (progStatus) progStatus.innerText = "Démarrage du Swarm Multi-Agents (NLU & WBS)...";







    try {



        const resp = await fetch(`${typeof API_BASE !== 'undefined' ? API_BASE : ''}/api/planning-ia/generate`, {



            method: 'POST',



            headers: {'Content-Type': 'application/json'},



            body: JSON.stringify({



                prompt: promptVal,



                type_projet: typeInst,



                localisation: loc,



                date_demarrage: dateStart,



                contraintes: ["Site actif", "Zone ATEX"],



                wbs_level: wbsLevel



            })



        });







        if (!resp.ok) throw new Error("Erreur serveur lors de la génération (" + resp.status + ")");







        const data = await resp.json();



        if (progBar) progBar.style.width = '100%';



        if (progStatus) progStatus.innerText = "Planning généré avec succès !";







        setTimeout(() => {



            if (progContainer) progContainer.classList.add('hidden');



            renderPlanningIAResults(data);



            if (btn) { btn.disabled = false; btn.style.opacity = '1'; }



        }, 500);







    } catch(err) {



        console.error("[PlanningIA Error]", err);



        if (progStatus) progStatus.innerText = "Erreur: " + err.message;



        if (btn) { btn.disabled = false; btn.style.opacity = '1'; }



        alert("Erreur lors de la génération du planning: " + err.message);



    }



}







