function renderNativePlanningGantt(taches, criticalPath) {



    const container = document.getElementById('mermaid-gantt-container');



    if (!container) return;







    if (!taches || taches.length === 0) {



        container.innerHTML = '<div style="padding:40px; text-align:center; color:var(--text-secondary);"><i class="ph ph-chart-bar-horizontal" style="font-size:32px; display:block; margin-bottom:8px; opacity:0.4;"></i>Aucune tâche à afficher.</div>';



        return;



    }







    let displayTasks = taches;



    if (planningGanttFilterCritOnly) {



        displayTasks = taches.filter(t => t.est_critique);



    }







    // 1. Calcul des bornes globales



    let maxDay = 0;



    taches.forEach(t => {



        const es = parseFloat(t.date_debut_tot || 0);



        const dur = parseFloat(t.duree_jours || 1);



        const marge = parseFloat(t.marge_totale || 0);



        const ef = es + dur;



        if (ef > maxDay) maxDay = ef;



        if (es + dur + marge > maxDay) maxDay = es + dur + marge;



    });



    maxDay = Math.max(10, Math.ceil(maxDay * 1.05));







    // 2. Grille temporelle



    let step = 10;



    if (maxDay <= 30) step = 5;



    else if (maxDay <= 100) step = 10;



    else if (maxDay <= 300) step = 25;



    else if (maxDay <= 600) step = 50;



    else step = 100;







    if (planningGanttZoomMode === 'weeks') {



        step = 7;



    }







    const markers = [];



    for (let d = 0; d <= maxDay; d += step) {



        markers.push(d);



    }



    if (markers[markers.length - 1] < maxDay) {



        markers.push(maxDay);



    }







    const markersHTML = markers.map(d => {



        const leftPct = (d / maxDay) * 100;



        const label = planningGanttZoomMode === 'weeks' ? `S${Math.floor(d/7)} (${d}j)` : `J+${d}`;



        return `



            <div style="position:absolute; left:${leftPct}%; transform:translateX(-50%); top:6px; font-size:10px; font-weight:600; color:var(--text-secondary); font-family:monospace;">



                ${label}



            </div>



            <div style="position:absolute; left:${leftPct}%; top:26px; bottom:0; width:1px; background:rgba(255,255,255,0.06); pointer-events:none;"></div>



        `;



    }).join('');







    // 3. Regroupement par Phase



    const phases = {};



    displayTasks.forEach(t => {



        const ph = t.phase || "Construction";



        if (!phases[ph]) phases[ph] = [];



        phases[ph].push(t);



    });







    // 4. Construction des lignes de tâches



    let rowsHTML = '';



    Object.keys(phases).forEach((phName) => {



        const phTasks = phases[phName];



        const phStart = Math.min(...phTasks.map(t => parseFloat(t.date_debut_tot || 0)));



        const phEnd = Math.max(...phTasks.map(t => parseFloat(t.date_fin_tot || (parseFloat(t.date_debut_tot||0) + parseFloat(t.duree_jours||1)))));



        const phDur = Math.max(1, Math.round((phEnd - phStart) * 10) / 10);



        const phStartPct = (phStart / maxDay) * 100;



        const phWidthPct = Math.max(1.5, ((phEnd - phStart) / maxDay) * 100);







        rowsHTML += `



            <div style="display:flex; align-items:center; background:rgba(255,255,255,0.03); border-top:1px solid rgba(255,255,255,0.06); border-bottom:1px solid rgba(255,255,255,0.04); height:30px; position:relative;">



                <div style="width:320px; min-width:320px; padding:0 12px; font-size:11px; font-weight:700; color:var(--text-primary); display:flex; align-items:center; gap:6px; border-right:1px solid var(--border-color); background:#151518; z-index:2;">



                    <i class="ph ph-folder" style="color:var(--accent-primary);"></i> ${phName} 



                    <span style="font-size:10px; font-weight:normal; color:var(--text-secondary);">(${phTasks.length} tâche${phTasks.length > 1 ? 's' : ''} • ${phDur}j)</span>



                </div>



                <div style="flex:1; position:relative; height:100%; overflow:hidden;">



                    <div style="position:absolute; left:${phStartPct}%; width:${phWidthPct}%; top:9px; height:10px; background:rgba(212,163,115,0.35); border:1px solid var(--accent-primary); border-radius:2px;"></div>



                </div>



            </div>



        `;







        phTasks.forEach((t) => {



            const es = parseFloat(t.date_debut_tot || 0);



            const dur = parseFloat(t.duree_jours || 1);



            const ef = parseFloat(t.date_fin_tot || (es + dur));



            const floatVal = parseFloat(t.marge_totale || 0);



            const isCrit = t.est_critique || floatVal === 0;







            const leftPct = (es / maxDay) * 100;



            const widthPct = Math.max(1.2, (dur / maxDay) * 100);



            const floatWidthPct = floatVal > 0 ? (floatVal / maxDay) * 100 : 0;







            const barBg = isCrit 



                ? 'linear-gradient(90deg, #EF4444 0%, #DC2626 100%)' 



                : 'linear-gradient(90deg, #0284C7 0%, #0EA5E9 100%)';



            const barBorder = isCrit ? '#F87171' : '#38BDF8';



            const barShadow = isCrit ? '0 0 10px rgba(239,68,68,0.4)' : '0 0 6px rgba(2,132,199,0.3)';







            const equipeStr = t.equipe_type ? t.equipe_type.map(e => `${e.effectif}x ${e.role}`).join(', ') : 'Standard';



            const resStr = t.ressources_materielles ? t.ressources_materielles.join(', ') : 'Standard';



            const predsStr = t.predecesseurs && t.predecesseurs.length ? t.predecesseurs.join(', ') : 'Aucun';







            const tooltipText = `



                <div style='font-weight:700; color:#F3F4F6; margin-bottom:4px; font-size:12px;'>[${t.id_tache}] ${t.nom}</div>



                <div style='font-size:11px; color:#D1D5DB; margin-bottom:2px;'><b>Phase :</b> ${t.phase} | <b>Discipline :</b> ${t.discipline}</div>



                <div style='font-size:11px; color:#D1D5DB; margin-bottom:2px;'><b>Quantité :</b> ${t.quantite_estimee} ${t.unite_oeuvre} (Rendement: ${t.rendement?.valeur || 0} ${t.rendement?.unite || ''})</div>



                <div style='font-size:11px; color:#D1D5DB; margin-bottom:2px;'><b>Équipe :</b> ${equipeStr}</div>



                <div style='font-size:11px; color:#D1D5DB; margin-bottom:2px;'><b>Outillage :</b> ${resStr}</div>



                <div style='font-size:11px; color:#A78BFA; margin-top:4px; font-family:monospace;'><b>Calendrier :</b> Début: J+${es} | Fin: J+${ef} | Durée: ${dur}j ${isCrit ? '<b style="color:#EF4444;">(CRITIQUE)</b>' : '| Marge: ' + floatVal + 'j'}</div>



                <div style='font-size:10px; color:#9CA3AF;'><b>Prédécesseurs :</b> ${predsStr}</div>



            `.replace(/"/g, '&quot;');







            rowsHTML += `



                <div style="display:flex; align-items:center; height:34px; border-bottom:1px solid rgba(255,255,255,0.03); position:relative; cursor:pointer;" onclick="highlightTableRow('${t.id_tache}')" onmouseover="this.style.background='rgba(255,255,255,0.03)'" onmouseout="this.style.background='transparent'">



                    <!-- Volet Gauche -->



                    <div style="width:320px; min-width:320px; padding:0 12px; display:flex; align-items:center; justify-content:space-between; border-right:1px solid var(--border-color); background:#131315; z-index:2; height:100%;">



                        <div style="display:flex; align-items:center; gap:8px; overflow:hidden; white-space:nowrap; text-overflow:ellipsis;">



                            <span style="font-family:monospace; font-size:11px; font-weight:700; color:${isCrit ? '#EF4444' : 'var(--accent-primary)'}; min-width:44px;">${t.id_tache}</span>



                            <span style="font-size:11px; color:var(--text-primary); overflow:hidden; text-overflow:ellipsis;" title="${t.nom}">${t.nom}</span>



                        </div>



                        <span style="font-size:11px; font-weight:700; font-family:monospace; color:${isCrit ? '#F87171' : '#34D399'}; min-width:40px; text-align:right;">${dur}j</span>



                    </div>







                    <!-- Volet Droite (Gantt) -->



                    <div style="flex:1; position:relative; height:100%; display:flex; align-items:center;">



                        ${floatVal > 0 ? `



                            <div style="position:absolute; left:${leftPct + widthPct}%; width:${floatWidthPct}%; height:6px; border:1px dashed #64748B; background:rgba(100,116,139,0.15); border-radius:2px; pointer-events:none;" title="Marge totale: ${floatVal} jours"></div>



                        ` : ''}







                        <div class="planning-gantt-bar" 



                             data-tippy-content="${tooltipText}"



                             style="position:absolute; left:${leftPct}%; width:${widthPct}%; height:18px; background:${barBg}; border:1px solid ${barBorder}; border-radius:4px; box-shadow:${barShadow}; display:flex; align-items:center; justify-content:center; padding:0 4px; transition:transform 0.15s ease, filter 0.15s ease; z-index:1;"



                             onmouseover="this.style.transform='scaleY(1.2)'; this.style.zIndex='10';"



                             onmouseout="this.style.transform='scaleY(1)'; this.style.zIndex='1';">



                            <span style="font-size:10px; font-weight:700; color:#FFFFFF; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; text-shadow:0 1px 2px rgba(0,0,0,0.9);">${dur}j</span>



                        </div>



                    </div>



                </div>



            `;



        });



    });







    container.innerHTML = `



        <div style="display:flex; flex-direction:column; width:100%; background:#131315; overflow-x:auto;">



            <div style="display:flex; height:28px; background:#18181A; border-bottom:1px solid var(--border-color); position:sticky; top:0; z-index:5;">



                <div style="width:320px; min-width:320px; padding:0 12px; font-size:10px; font-weight:700; color:var(--text-secondary); text-transform:uppercase; display:flex; align-items:center; border-right:1px solid var(--border-color); background:#18181A;">



                    TÂCHE (WBS) & DURÉE



                </div>



                <div style="flex:1; position:relative; min-width:600px;">



