                </div>



            </div>



            <div style="display:flex; flex-direction:column; min-width:920px; position:relative;">



                ${rowsHTML}



            </div>



        </div>



    `;







    try {



        if (typeof tippy !== 'undefined') {



            tippy('.planning-gantt-bar', {



                allowHTML: true,



