function recalculateClientCPM(data) {



    if (!data || !data.taches) return;



    const tasks = data.taches;



    const taskMap = {};



    tasks.forEach(t => { taskMap[t.id_tache] = t; });







    // 1. Forward Pass (ES / EF)



    tasks.forEach(t => {



        let maxPredEF = 0;



        if (t.predecesseurs && t.predecesseurs.length > 0) {



            t.predecesseurs.forEach(pId => {



                const p = taskMap[pId];



                if (p) {



                    const pEF = (p.date_debut_tot || 0) + (p.duree_jours || 1);



                    if (pEF > maxPredEF) maxPredEF = pEF;



                }



            });



        }



        t.date_debut_tot = Math.round(maxPredEF * 10) / 10;



        t.date_fin_tot = Math.round((t.date_debut_tot + (t.duree_jours || 1)) * 10) / 10;



    });







    const totalDuration = Math.round(Math.max(...tasks.map(t => t.date_fin_tot || 0)) * 10) / 10;



    data.duree_totale_jours = totalDuration;







    // 2. Backward Pass (LF / LS / Marges)



    tasks.forEach(t => {



        t.date_fin_tard = totalDuration;



    });







    for (let i = tasks.length - 1; i >= 0; i--) {



        const t = tasks[i];



        const succs = tasks.filter(s => s.predecesseurs && s.predecesseurs.includes(t.id_tache));



        if (succs.length > 0) {



            const minSuccLS = Math.min(...succs.map(s => s.date_debut_tard !== undefined ? s.date_debut_tard : (s.date_fin_tard - (s.duree_jours || 1))));



            t.date_fin_tard = Math.round(minSuccLS * 10) / 10;



        }



        t.date_debut_tard = Math.round((t.date_fin_tard - (t.duree_jours || 1)) * 10) / 10;



        t.marge_totale = Math.max(0, Math.round((t.date_debut_tard - t.date_debut_tot) * 10) / 10);



        t.est_critique = (t.marge_totale <= 0.1);



    }







    data.chemin_critique = tasks.filter(t => t.est_critique).map(t => t.id_tache);



    return data;



}







function saveEditedTaskYield() {



    if (!currentEditedTaskId || !window.currentPlanningIAData || !window.currentPlanningIAData.taches) return;



    const task = window.currentPlanningIAData.taches.find(t => t.id_tache === currentEditedTaskId);



    if (!task) return;







    const newQ = parseFloat(document.getElementById('modal-edit-quantite')?.value || 1);



    const newY = parseFloat(document.getElementById('modal-edit-rendement')?.value || 1);







    if (isNaN(newQ) || newQ <= 0 || isNaN(newY) || newY <= 0) {



        alert("Veuillez saisir une quantité et un rendement valides et strictement positifs.");



        return;



    }







    const oldY = task.rendement?.valeur || 1;



    task.quantite_estimee = newQ;



    if (!task.rendement) task.rendement = { valeur: newY, unite: 'u/j' };



    task.rendement.valeur = newY;



    task.duree_jours = Math.max(0.5, Math.round((newQ / newY) * 10) / 10);







    // Recalcul CPM complet



    recalculateClientCPM(window.currentPlanningIAData);







    // Mise à jour des compteurs KPI



    const durEl = document.getElementById('kpi-pia-duration');



    if (durEl) durEl.innerText = `${window.currentPlanningIAData.duree_totale_jours} jours`;



    const cpmEl = document.getElementById('kpi-pia-cpm');



    if (cpmEl) cpmEl.innerText = `${window.currentPlanningIAData.chemin_critique ? window.currentPlanningIAData.chemin_critique.length : 0} tâches`;







    // Rafraîchir tableau & Gantt



    renderPlanningTable(window.currentPlanningIAData.taches);



    renderNativePlanningGantt(window.currentPlanningIAData.taches, window.currentPlanningIAData.chemin_critique);







    // Envoi de la correction d'apprentissage au backend



    fetch(`${typeof API_BASE !== 'undefined' ? API_BASE : ''}/api/planning-ia/validate`, {



        method: 'POST',



        headers: {'Content-Type': 'application/json'},



        body: JSON.stringify({



            tache_id_db: null,



            nom_tache: task.nom,



            discipline: task.discipline,



            rendement_estime: oldY,



            rendement_reel: newY,



            projet_id: "PROJET_ACTIF",



            commentaire: `Ajustement planificateur : Quantité ${newQ} ${task.unite_oeuvre}, Rendement ${newY}`



        })



    }).catch(e => console.warn(e));







    closeEditTaskYieldModal();



    if (typeof showToast === 'function') {



        showToast(`Tâche [${task.id_tache}] ajustée : ${task.duree_jours} jours (Chemin critique recalculé)`, "success");



    }



}







