            const container = document.getElementById('pid-gen-canvas-container');



            if (!container || container._panZoomInitialized) return;



            container._panZoomInitialized = true;







            container.addEventListener('mousedown', (e) => {



                if (e.button !== 0) return;



                pidGenIsDragging = true;



                pidGenStartX = e.clientX - pidGenPanX;



                pidGenStartY = e.clientY - pidGenPanY;



                container.style.cursor = 'grabbing';



            });







            window.addEventListener('mousemove', (e) => {



                if (!pidGenIsDragging) return;



                pidGenPanX = e.clientX - pidGenStartX;



                pidGenPanY = e.clientY - pidGenStartY;



                pidGenApplyTransform();



            });







            window.addEventListener('mouseup', () => {



                if (pidGenIsDragging) {



                    pidGenIsDragging = false;



                    const c = document.getElementById('pid-gen-canvas-container');



                    if (c) c.style.cursor = 'grab';



                }



            });







            container.addEventListener('wheel', (e) => {



                e.preventDefault();



                const factor = e.deltaY < 0 ? 1.15 : 0.85;



                pidGenZoomLevel = Math.max(0.4, Math.min(4.0, pidGenZoomLevel * factor));



                pidGenApplyTransform();



            }, { passive: false });



        }







