                                    <button onclick="event.stopPropagation(); deleteWorkspaceFolder(${f.id}, '${f.name.replace(/'/g, "\\'")}')" title="Retirer du suivi ARKAN" style="background:none; border:none; color:var(--text-muted); cursor:pointer; font-size:13px; padding:2px; display:flex; align-items:center; opacity:0.6; transition:opacity 0.2s;" onmouseenter="this.style.opacity=1; this.style.color='#EF4444';" onmouseleave="this.style.opacity=0.6; this.style.color='var(--text-muted)';"><i class="ph ph-trash"></i></button>



