        async function selectWorkspaceFolder(folderId) {



            window.currentWsFolderId = folderId;



            const folder = window.currentWsFolders.find(f => f.id === folderId);



            if (!folder) return;







            // Re-render folder list cards to update active styles



            const listEl = document.getElementById('ws-folders-list');



            if (listEl) {



                Array.from(listEl.children).forEach((child, idx) => {



                    if (window.currentWsFolders[idx]) {



                        const isThis = (window.currentWsFolders[idx].id === folderId);



                        child.style.borderColor = isThis ? 'var(--accent-primary)' : 'var(--border-color)';



                        child.style.background = isThis ? 'rgba(59,130,246,0.08)' : 'var(--bg-surface)';



                    }



                });



            }







            // Top Header active folder badge



            const nameEl = document.getElementById('ws-active-folder-name');



            const statusBadge = document.getElementById('ws-active-folder-status-badge');



            if (nameEl) nameEl.innerText = `${folder.name} (${folder.code})`;







            const isIndexed = Boolean(folder.is_indexed);



            if (statusBadge) {



                statusBadge.style.display = 'inline-block';



                if (isIndexed) {



                    statusBadge.style.background = 'rgba(16,185,129,0.12)';



                    statusBadge.style.color = '#10B981';



                    statusBadge.style.border = '1px solid rgba(16,185,129,0.3)';



                    statusBadge.innerHTML = `<i class="ph-bold ph-check"></i> INDEXÉ (${folder.file_count || 0} fichiers)`;



