                    statusBadge.style.background = 'rgba(245,158,11,0.12)';



                    statusBadge.style.color = '#F59E0B';



                    statusBadge.style.border = '1px solid rgba(245,158,11,0.3)';



                    statusBadge.innerHTML = `<i class="ph-bold ph-lock-key"></i> NON INDEXÉ`;



                }



