        async function fetchWorkspaceDrawings() {



            if (!window.currentWsFolderId) return;



            const q = (document.getElementById('ws-search-input')?.value || '').trim();



            const resultsEl = document.getElementById('ws-plans-results');



            const plansBadge = document.getElementById('ws-plans-badge');







            try {



                const url = `${API_BASE}/api/workspace/folders/${window.currentWsFolderId}/search?q=${encodeURIComponent(q)}&doc_type=${encodeURIComponent(window.currentWsDocFilter)}&latest_only=true`;



                const res = await fetch(url);



                if (res.status === 403) {



                    const err = await res.json();



                    document.getElementById('ws-unindexed-warning').style.display = 'flex';



                    document.getElementById('ws-search-controls').style.display = 'none';



                    resultsEl.innerHTML = '';



                    return;



                }



                const data = await res.json();



                const plans = data.results || [];







                if (plansBadge) plansBadge.innerText = plans.length;







                if (!plans.length) {



                    resultsEl.innerHTML = `



                        <div style="text-align:center; padding:30px; color:var(--text-muted);">



                            <i class="ph ph-magnifying-glass" style="font-size:28px; margin-bottom:8px; display:block;"></i>



                            <div style="font-size:12px;">Aucun plan trouvé pour cette recherche.</div>



                        </div>



                    `;



                    return;



                }







                resultsEl.innerHTML = plans.map(p => {



                    const latest = p.latest_revision || (p.all_revisions && p.all_revisions[0]) || {};



                    const revCount = (p.all_revisions || []).length;



                    const unliftedFcd = p.unlifted_fcd_count || 0;







                    const fcdPill = unliftedFcd > 0



                        ? `<span style="background:rgba(239,68,68,0.15); color:#EF4444; border:1px solid rgba(239,68,68,0.3); font-size:10px; font-weight:700; padding:2px 7px; border-radius:10px;">⚠️ ${unliftedFcd} FCD non levé(s)</span>`



                        : '';







                    // Historique sub-revisions



                    const historyRows = (p.all_revisions || []).map(r => {



                        const isCurr = r.is_latest ? '<span style="color:#10B981; font-weight:700;">(En vigueur)</span>' : '<span style="color:var(--text-muted);">(Périmé)</span>';



                        return `



                            <div style="display:flex; align-items:center; justify-content:space-between; padding:5px 8px; border-radius:4px; background:rgba(255,255,255,0.02); font-size:11px;">



                                <div>



                                    <strong style="color:var(--text-primary);">${r.revision_label}</strong> ${isCurr}



                                    <span style="color:var(--text-muted); margin-left:6px;">${(r.file_size / 1024).toFixed(0)} Ko</span>



                                </div>



                                <button onclick="event.stopPropagation(); loadPlanIntoViewerById(${r.id}, ${p.master_id})" style="background:var(--bg-surface); border:1px solid var(--border-color); color:var(--text-primary); font-size:10px; padding:2px 8px; border-radius:3px; cursor:pointer;">



                                    👁️ Ouvrir



                                </button>



                            </div>



                        `;



                    }).join('');







                    return `



                        <div style="background:var(--bg-app); border:1px solid var(--border-color); border-radius:var(--radius-sm); padding:10px 12px; display:flex; flex-direction:column; gap:8px;">



                            <div style="display:flex; align-items:center; justify-content:space-between;">



                                <div style="display:flex; align-items:center; gap:8px; min-width:0;">



                                    <span style="font-size:10px; font-weight:800; background:rgba(59,130,246,0.12); color:var(--accent-primary); padding:2px 6px; border-radius:4px;">${latest.doc_type || 'PLAN'}</span>



                                    <strong style="font-size:12px; color:var(--text-primary); white-space:nowrap; overflow:hidden; text-overflow:ellipsis;" title="${p.drawing_root_no}">${p.drawing_root_no}</strong>



                                </div>



                                <span style="background:rgba(16,185,129,0.12); color:#10B981; border:1px solid rgba(16,185,129,0.3); font-size:10px; font-weight:800; padding:2px 7px; border-radius:8px;">${latest.revision_label || 'REV 0'}</span>



                            </div>







                            <div style="font-size:11px; color:var(--text-secondary); white-space:nowrap; overflow:hidden; text-overflow:ellipsis;">



                                ${latest.file_name || p.title}



                            </div>







                            <div style="display:flex; align-items:center; justify-content:space-between; margin-top:2px;">



                                <div style="display:flex; align-items:center; gap:6px;">



                                    ${fcdPill}



                                    <span style="font-size:10px; color:var(--text-muted);">${revCount} révision(s)</span>



                                </div>



                                <div style="display:flex; align-items:center; gap:6px;">



                                    ${revCount > 1 ? `<button onclick="toggleMasterHistory(${p.master_id})" style="background:transparent; border:none; color:var(--text-secondary); font-size:11px; cursor:pointer; text-decoration:underline;">Historique (${revCount})</button>` : ''}



                                    <button onclick="loadPlanIntoViewerById(${latest.id || latest.revision_id}, ${p.master_id})" style="background:linear-gradient(135deg, #3B82F6, #1D4ED8); border:none; color:#FFF; font-weight:700; font-size:11px; padding:4px 10px; border-radius:var(--radius-sm); cursor:pointer; display:flex; align-items:center; gap:4px;">



                                        <i class="ph ph-eye"></i> Visualiser



                                    </button>



                                </div>



                            </div>







                            <!-- Drawer Historique déroulant -->



                            <div id="ws-history-${p.master_id}" style="display:none; flex-direction:column; gap:4px; margin-top:6px; padding-top:6px; border-top:1px dashed var(--border-color);">



                                <span style="font-size:10px; font-weight:700; text-transform:uppercase; color:var(--text-muted); margin-bottom:2px;">Historique des versions :</span>



                                ${historyRows}



                            </div>



                        </div>



                    `;



                }).join('');



            } catch (err) {



                console.error("[Workspace] fetchWorkspaceDrawings error:", err);



            }



        }







        function toggleMasterHistory(masterId) {



            const el = document.getElementById(`ws-history-${masterId}`);



            if (el) {



                el.style.display = (el.style.display === 'flex' ? 'none' : 'flex');



            }



        }







        async function loadPlanIntoViewerById(revId, masterId) {



            try {



                // Requête directe et instantanée par master_id (sans limite de pagination de recherche)



                const res = await fetch(`${API_BASE}/api/workspace/masters/${masterId}`);



                if (!res.ok) throw new Error("Impossible de récupérer la fiche du plan maître #" + masterId);



                const data = await res.json();



                const master = data.master;



                if (!master) return;







                const rev = (master.all_revisions || []).find(r => r.id === revId || r.revision_id === revId) || master.latest_revision || (master.all_revisions && master.all_revisions[0]);



                if (!rev) return;







                window.currentWsActivePlan = rev;



                window.currentWsActiveMaster = master;







                // Update Header



                const titleEl = document.getElementById('ws-viewer-title');



                const subtitleEl = document.getElementById('ws-viewer-subtitle');



                if (titleEl) titleEl.innerText = `${master.drawing_root_no} (${rev.revision_label || 'REV 0'})`;



                if (subtitleEl) subtitleEl.innerText = rev.file_name;







                window.wsViewerZoom = 1.0;



                applyViewerZoom();







                // Populate revision selector



                const sel = document.getElementById('ws-viewer-rev-select');



                const selCont = document.getElementById('ws-viewer-rev-container');



                if (sel && master.all_revisions && master.all_revisions.length > 0) {



                    selCont.style.display = 'flex';



                    sel.innerHTML = master.all_revisions.map(r => {



                        const isSel = (r.id === rev.id || r.revision_id === rev.id) ? 'selected' : '';



                        const tag = r.is_latest ? ' (En vigueur)' : ' (Périmé)';



                        return `<option value="${r.id || r.revision_id}" ${isSel}>${r.revision_label}${tag}</option>`;



                    }).join('');



                }







                // Show Action Buttons



                const btnMto = document.getElementById('ws-btn-calc-mto');



                const btnFs = document.getElementById('ws-btn-open-fullscreen');



                const btnNative = document.getElementById('ws-btn-open-native');



                if (btnMto) btnMto.style.display = 'flex';



                if (btnFs) btnFs.style.display = 'flex';



                if (btnNative) btnNative.style.display = 'flex';







                // Viewport Elements



                const ph = document.getElementById('ws-viewer-placeholder');



                const imgCont = document.getElementById('ws-viewer-img-container');



                const cardCont = document.getElementById('ws-viewer-file-card');



                const docCont = document.getElementById('ws-viewer-doc-container');



                const pageControls = document.getElementById('ws-viewer-page-controls');



                const zoomControls = document.getElementById('ws-viewer-zoom-controls');







                if (ph) ph.style.display = 'none';







                const ext = (rev.extension || '').toLowerCase();







                if (ext === '.pdf' || ['.png', '.jpg', '.jpeg', '.webp', '.tif', '.tiff', '.bmp'].includes(ext)) {



                    if (cardCont) cardCont.style.display = 'none';



                    if (docCont) docCont.style.display = 'none';



                    if (imgCont) imgCont.style.display = 'flex';



                    if (zoomControls) zoomControls.style.display = 'flex';







                    // Récupérer le nombre de pages du document



                    window.wsViewerCurrentPage = 0;



                    window.wsViewerTotalPages = 1;







                    try {



                        const infoRes = await fetch(`${API_BASE}/api/workspace/doc-info?path=${encodeURIComponent(rev.file_path)}`);



                        if (infoRes.ok) {



                            const infoData = await infoRes.json();



                            window.wsViewerTotalPages = infoData.page_count || 1;



                        }



                    } catch (e) {



                        console.warn("[DocInfo] Erreur récupération info document :", e);



                    }







                    // Mettre à jour l'affichage de la pagination



                    if (pageControls) {



                        pageControls.style.display = (window.wsViewerTotalPages > 1) ? 'flex' : 'none';



                        const curEl = document.getElementById('ws-viewer-current-page');



                        const totEl = document.getElementById('ws-viewer-total-pages');



                        if (curEl) curEl.innerText = '1';



                        if (totEl) totEl.innerText = window.wsViewerTotalPages;



                    }







                    // Rendu immédiat de la page en haute définition (< 100 ms via PyMuPDF)



                    renderCurrentViewerPage();







                } else {



                    // Formats CAO/DAO (DWG, DXF) ou Bureautique (XLSX, DOCX, PPTX)



                    if (imgCont) imgCont.style.display = 'none';



                    if (pageControls) pageControls.style.display = 'none';



                    if (zoomControls) zoomControls.style.display = 'none';



                    renderInteractiveDocumentPreview(rev, ext);



                }







                // Check FCD comments for this drawing



                loadFcdCommentsForActivePlan(master.drawing_root_no);







            } catch (err) {



                console.error("[Workspace] loadPlanIntoViewerById error:", err);



                showToast("Erreur lors de l'ouverture du plan : " + err.message, "error");



            }



        }







        async function openActivePlanInNativeApp() {



            if (!window.currentWsActivePlan) return;



            const plan = window.currentWsActivePlan;



            try {



                showToast(`Ouverture locale en cours pour ${plan.file_name}...`, "info");



                const res = await fetch(`${API_BASE}/api/workspace/open-native?path=${encodeURIComponent(plan.file_path)}`, {



                    method: 'POST'



                });



                const data = await res.json();



                if (res.ok) {



                    showToast(data.message || `Fichier ouvert avec succès : ${plan.file_name}`, "success");



                } else {



                    showToast(data.detail || "Erreur lors de l'ouverture locale.", "error");



                }



            } catch (err) {



                console.error("[Workspace] openActivePlanInNativeApp error:", err);



                showToast("Erreur de connexion : " + err.message, "error");



            }



        }







        async function renderInteractiveDocumentPreview(rev, ext) {



            const docCont = document.getElementById('ws-viewer-doc-container');



            const cardCont = document.getElementById('ws-viewer-file-card');



            const tabsEl = document.getElementById('ws-doc-tabs');



