            if (cardCont) cardCont.style.display = 'none';







            bodyEl.innerHTML = `



                <div style="display:flex; flex-direction:column; align-items:center; justify-content:center; height:240px; gap:12px; color:var(--text-secondary);">



                    <div class="spinner" style="width:28px; height:28px; border:3px solid rgba(59,130,246,0.2); border-top-color:var(--accent-primary); border-radius:50%; animation:spin 0.8s linear infinite;"></div>



                    <span style="font-size:12px; font-weight:600;">Extraction et analyse du document ${escapeHtml(rev.file_name)}...</span>



