            `;







            try {



                const res = await fetch(`${API_BASE}/api/workspace/preview-content?path=${encodeURIComponent(rev.file_path)}`);



                if (!res.ok) throw new Error("Aperçu non disponible pour ce document");



                const data = await res.json();







                // 1. EXCEL (.xlsx, .xls, .csv)



                if (data.doc_type === 'EXCEL') {



                    if (metaEl) metaEl.innerText = `${data.total_rows} ligne(s) • ${data.total_cols} colonne(s)`;



                    if (tabsEl) {



                        tabsEl.innerHTML = (data.sheets || []).map(s => {



