                            return `<button onclick="switchExcelSheet('${escapeHtml(s)}')" style="background:${isActive ? 'var(--accent-primary)' : 'var(--bg-app)'}; color:${isActive ? '#FFF' : 'var(--text-secondary)'}; border:1px solid var(--border-color); padding:4px 12px; border-radius:4px; font-size:11px; font-weight:700; cursor:pointer; white-space:nowrap;">${escapeHtml(s)}</button>`;



