                    }







                    const rows = data.rows || [];



                    if (rows.length === 0) {



                        bodyEl.innerHTML = `<div style="text-align:center; padding:40px; color:var(--text-muted); font-size:12px;">Feuille vide</div>`;



                    } else {



                        let html = `



                            <div style="margin-bottom:12px; display:flex; justify-content:space-between; align-items:center; flex-wrap:wrap; gap:8px;">



                                <div style="display:flex; align-items:center; gap:8px;">



                                    <span style="font-size:12px; font-weight:700; color:var(--text-primary);">Feuille active : <span style="color:var(--accent-primary);">${escapeHtml(data.active_sheet)}</span></span>



                                    <span style="font-size:10px; background:rgba(16,185,129,0.12); color:#10B981; border:1px solid rgba(16,185,129,0.3); padding:2px 6px; border-radius:4px; font-weight:800;">EXCEL TABLE</span>



                                </div>



                                <button onclick="openActivePlanInNativeApp()" style="background:linear-gradient(135deg, #10B981, #059669); color:#FFF; border:none; padding:5px 12px; border-radius:4px; font-size:11px; font-weight:700; cursor:pointer; display:flex; align-items:center; gap:6px;">



                                    <i class="ph-bold ph-arrow-square-out"></i> Ouvrir dans Excel



                                </button>



                            </div>



                            <div style="overflow:auto; max-height:calc(100vh - 280px); border:1px solid var(--border-color); border-radius:6px; box-shadow:0 4px 14px rgba(0,0,0,0.2);">



