            const img = document.getElementById('ws-viewer-img');



            if (spinner) spinner.style.display = 'flex';







            const pageIdx = window.wsViewerCurrentPage || 0;



            const renderUrl = `${API_BASE}/api/workspace/render-page?path=${encodeURIComponent(rev.file_path)}&page=${pageIdx}&dpi=150&_t=${Date.now()}`;







            const preloader = new Image();



            preloader.onload = function() {



                if (img) {



                    img.src = renderUrl;



                    img.style.transform = `scale(${window.wsViewerZoom || 1.0})`;



                }



                if (spinner) spinner.style.display = 'none';



            };



            preloader.onerror = function() {



                if (spinner) spinner.style.display = 'none';



                showToast("Échec du rendu graphique de la page " + (pageIdx + 1), "error");



            };



            preloader.src = renderUrl;







            const curEl = document.getElementById('ws-viewer-current-page');



            if (curEl) curEl.innerText = (pageIdx + 1);



        }







        function prevViewerPage() {



            if (!window.currentWsActivePlan || window.wsViewerCurrentPage <= 0) return;



            window.wsViewerCurrentPage--;



            renderCurrentViewerPage();



        }







        function nextViewerPage() {



            if (!window.currentWsActivePlan || window.wsViewerCurrentPage >= (window.wsViewerTotalPages - 1)) return;



            window.wsViewerCurrentPage++;



            renderCurrentViewerPage();



        }







