            const navBadge = document.getElementById('workspace-unlifted-badge');



            const listEl = document.getElementById('ws-fcd-comments-list');







            try {



                const res = await fetch(`${API_BASE}/api/workspace/folders/${window.currentWsFolderId}/fcd-comments`);



                const data = await res.json();



                const kpis = data.kpis || { total: 0, non_leve: 0, en_cours: 0, leve: 0 };



                const comments = data.comments || [];







                if (kpiNonLeve) kpiNonLeve.innerText = kpis.non_leve;



                if (kpiEnCours) kpiEnCours.innerText = kpis.en_cours;



                if (kpiLeve) kpiLeve.innerText = kpis.leve;



                if (fcdBadge) fcdBadge.innerText = kpis.non_leve;







                if (navBadge) {



                    if (kpis.non_leve > 0) {



                        navBadge.innerText = kpis.non_leve;



                        navBadge.style.display = 'inline-block';



                    } else {



                        navBadge.style.display = 'none';



                    }



                }







                if (!comments.length) {



                    listEl.innerHTML = `



                        <div style="text-align:center; padding:30px; color:var(--text-muted);">



                            <i class="ph ph-check-circle" style="font-size:28px; color:#10B981; margin-bottom:8px; display:block;"></i>



                            <div style="font-size:12px; font-weight:600;">Aucun commentaire client FCD.</div>



                            <div style="font-size:11px; margin-top:4px;">Toutes les réserves sont levées ou aucun document FCD n'a été indexé.</div>



                        </div>



                    `;



                    return;



                }







                listEl.innerHTML = comments.map(c => {



                    const isNonLeve = (c.status === 'NON_LEVE');



                    const sevColor = c.severity === 'CRITICAL' ? '#EF4444' : '#F59E0B';



                    return `



                        <div style="background:var(--bg-app); border:1px solid ${isNonLeve ? 'rgba(239,68,68,0.3)' : 'var(--border-color)'}; border-radius:var(--radius-sm); padding:10px 12px; display:flex; flex-direction:column; gap:6px;">



                            <div style="display:flex; align-items:center; justify-content:space-between;">



                                <div style="display:flex; align-items:center; gap:8px;">



                                    <span style="font-size:10px; font-weight:800; color:${sevColor}; border:1px solid ${sevColor}; padding:1px 6px; border-radius:4px;">${c.severity}</span>



                                    <strong style="font-size:12px; color:var(--text-primary);">${c.target_drawing_no}</strong>



                                </div>



                                <span style="font-size:10px; font-weight:700; background:rgba(255,255,255,0.06); padding:2px 6px; border-radius:4px; color:var(--text-muted);">${c.target_revision || 'REV 0'}</span>



                            </div>



                            <div style="font-size:12px; color:var(--text-secondary); line-height:1.4;">${c.comment_text}</div>



                            <div style="display:flex; align-items:center; justify-content:space-between; margin-top:4px; font-size:11px;">



                                <span style="color:${isNonLeve ? '#EF4444' : '#10B981'}; font-weight:700;">● ${isNonLeve ? 'NON LEVÉ (Réservé)' : 'LEVÉ / SOURCÉ'}</span>



                                ${isNonLeve ? `<button onclick="openResolveCommentModalById(${c.id}, '${escape(c.comment_text)}')" style="background:var(--success); border:none; color:#FFF; font-weight:700; font-size:10px; padding:3px 10px; border-radius:3px; cursor:pointer;">Lever la réserve</button>` : `<span style="color:var(--text-muted); font-size:10px;">${c.resolved_in_revision || ''}</span>`}



                            </div>



                        </div>



                    `;



                }).join('');







            } catch (err) {



                console.error("[Workspace] fetchWorkspaceFcdComments error:", err);



            }



        }







