                showToast("Échec : " + err.message, "error");



            }



        }







        async function deleteWorkspaceFolder(id, name) {



            if (!confirm(`Supprimer définitivement le dossier "${name}" et le retirer de tous les onglets ARKAN ?`)) return;



            try {



                const res = await fetch(`${API_BASE}/api/workspace/folders/${id}`, { method: 'DELETE' });



                const data = await res.json();



                if (res.ok) {



                    showToast(data.message || "Dossier supprimé de tous les onglets.", "info");



                    if (window.currentWsFolderId === id) {



                        window.currentWsFolderId = null;



                        resetWorkspaceViewToEmpty();



                    }



                    await loadWorkspaceFolders();



                    // Synchronisation instantanée des autres onglets (Synthèse, Équipements, Cohérence & Anomalies)



                    if (typeof loadScadaProjects === 'function') loadScadaProjects();



                    if (typeof loadProjectsAndEquipments === 'function') loadProjectsAndEquipments();



                    const vIframe = document.getElementById('verification-iframe');



                    if (vIframe && vIframe.contentWindow) {



                        try { vIframe.contentWindow.location.reload(); } catch(e) {}



                    }



                } else {



                    showToast(data.detail || "Erreur suppression dossier.", "error");



                }



            } catch (e) {



                console.error("[Workspace] deleteWorkspaceFolder error:", e);



                showToast("Erreur réseau : " + e.message, "error");



            }



        }







